window.__LITE_PARTS__=window.__LITE_PARTS__||[];window.__LITE_PARTS__.push([{"t":"新款马自达 EZ-60 激光版上市，限时价 11.39 万元起","b":"IT之家 9 月 26 日消息，2027 款 EZ-60 激光版今晚正式上市。新车共推出 9 款车型，限时惊喜价 11.39 万至 16.69 万元，新增激光雷达，智能辅助驾驶能力得到提升。IT之家汇总如下：\n| 马自达 EZ-60 | ||\n| 车型 | 官方指导价（万元） | 限时惊喜价（万元） |\n| 增程 200 Air | 11.99 | 11.39 |\n| 增程 200 Pro | 13.99 | 13.39 |\n| 增程 200 Pro 激光版 | 15.19 | 14.59 |\n| 增程 200 Max | 15.49 | 14.89 |\n| 增程 200 Max 激光版 | 16.69 | 16.09 |\n| 纯电 600 Pro | 14.59 | 13.99 |\n| 纯电 600 Pro 激光版 | 15.79 | 15.19 |\n| 纯电 600 Max | 16.09 | 15.49 |\n| 纯电 600 Max 激光版 | 17.29 | 16.69 |\n官方同步推出超级置换礼、配置升级礼、选择基金礼、金融权益礼、自燃包赔礼。新增激光雷达可实现高速与城区双域领航、全场景泊车以及全域主动安全等功能。\n外观方面，新车延续现款 EZ-60 设计风格，主要变化是车顶增设激光雷达模块，以提升智能辅助驾驶能力。车身侧面保持运动姿态，配备隐藏式门把手和电子后视镜。\n尾部采用较大倾角后车窗，搭配贯穿式尾灯组、后扰流板和后包围。尺寸方面，长宽高分别为 4850/1935/1620mm，轴距 2902mm，定位中型 SUV。\n其内饰沿用飞翼环抱悬浮座舱布局，搭载 26.45 英寸 5K 一体式悬浮大屏，内置 3nm 车规级芯片。车辆还配备 50 英寸 AR-HUD 抬头显示和云感零重力座椅，支持座椅加热、通风。\n动力提供增程和纯电两种选择。增程车型搭载 1.5L 增程器，增程器最大功率 70kW，驱动电机峰值功率 190kW，峰值扭矩 290N·m，CLTC 纯电续航 200km。\n纯电车型搭载磷酸铁锂电池，采用单电机后驱布局，最大功率 190kW，峰值扭矩 290N·m，CLTC 纯电续航 600km。\n广告声明：文内含有的对外跳转链接（包括不限于超链接、二维码、口令等形式），用于传递更多信息，节省甄选时间，结果仅供参考，IT之家包含外链的文章均包含本声明。","d":"2026-09-26","u":"https://www.ithome.com/1/007/431.htm","c":"AI与智能科技/具身智能/硬件和控制","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"马自达EZ-60上市","sc":6.4,"scd":{"b":1.0,"i":9.0,"r":4.0,"d":7.0,"t":8.0},"as":"2027款马自达EZ-60激光版上市，共9款车型，限时价11.39万至16.69万元（官方指导价11.99万至17.29万元），核心变化是新增激光雷达，支持高速与城区双域领航、全场景泊车及全域主动安全等功能。新车定位中型SUV，尺寸4850/1935/1620mm，轴距2902mm，配备隐藏式门把手、电子后视镜。内饰沿用飞翼环抱悬浮座舱，搭载26.45英寸5K一体屏、3nm车规级芯片、50英寸AR-HUD及零重力座椅。动力提供增程（1.5L增程器）和纯电两种选择。官方同步推出置换、配置升级、金融权益等多项购车权益。","kp":["限时价[马自达 EZ-60 激光版]: 11.39 万至 16.69 万元","新增配置: 激光雷达，高速与城区双域智能辅助驾驶"]},{"t":"北京越野泰钽 700 开启首批交付：搭载华为乾崑智驾 ADS 5，超级焕新价 24.98 万元起","b":"IT之家 9 月 26 日消息，在今日举行的北京越野全球用户大会盛典上，泰钽 700 开启首批车主交付。\n据IT之家此前报道，北京越野泰钽 700 于 8 月 25 日上市，超级焕新价 24.98 万元起：\n- 豪华版：27.98 万元，超级焕新价 24.98 万元\n- 乾崑旗舰版：32.98 万元，超级焕新价 29.98 万元\n- 乾崑巅峰版：37.98 万元，超级焕新价 34.98 万元\n泰钽 700 搭载华为乾崑智驾 ADS 5，配备 896 线双光路图像级激光雷达，支持 AEB、RAEB、CAS 5.0 全维防碰撞等。该车还拥有华为乾崑全维融合感知系统，前向有 13 个传感器、侧向有 6 个传感器、后向有 11 个传感器。\n新车定位中大型豪华越野 SUV，尺寸为 5040×1959×1926mm、轴距 2820mm；配备 10.25 英寸全液晶仪表 + 15.6 英寸中控液晶显示屏 + 15.6 英寸副驾液晶显示屏 + HUD 抬头显示。\n泰钽 700 搭载 1.5T 魔核智能增程系统，综合功率 391kW，综合扭矩 625N·m，配备 49.4kWh 宁德时代三元锂电池，CLTC 纯电续航 220km、CLTC 综合续航里程 1340km。","d":"2026-09-26","u":"https://www.ithome.com/1/007/430.htm","c":"AI与智能科技/具身智能/硬件和控制","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"越野泰钽700交付","sc":6.8,"scd":{"b":2.0,"i":9.0,"r":4.0,"d":8.0,"t":8.0},"aip":1,"as":"北京越野泰钽700在9月26日全球用户大会开启首批交付。该车8月25日上市，超级焕新价24.98万元起（豪华版24.98万、乾崑旗舰版29.98万、乾崑巅峰版34.98万）。新车搭载华为乾崑智驾ADS 5，配备896线双光路图像级激光雷达，支持AEB、RAEB、CAS 5.0全维防碰撞，全维融合感知系统含前向13个、侧向6个、后向11个传感器。定位中大型豪华越野SUV，尺寸5040×1959×1926mm、轴距2820mm，配备10.25英寸仪表、双15.6英寸屏及HUD。动力为1.5T魔核智能增程系统，综合功率391kW、扭矩625N·m，配49.4kWh宁德时代三元锂电池，CLTC纯电续航220km、综合续航1340km。","kp":["售价[北京越野泰钽 700]: 超级焕新价 24.98 万元起","智驾系统: 华为乾崑智驾 ADS 5","激光雷达: 896 线双光路图像级","传感器配置: 前向 13 个、侧向 6 个、后向 11 个","尺寸/轴距: 5040×1959×1926mm / 2820mm"]},{"t":"荣耀 Magic9 Pro Max 手机搭载自研至臻黑钻屏：反射率 1.5%、峰值亮度 1 万尼特","b":"9 月 26 日消息，全新荣耀 Magic9 系列手机将于 9 月 28 日 14:30 发布并开售。\n荣耀工作人员王飞今日发文表示，荣耀 Magic9 Pro Max 搭载自研至臻黑钻屏，包含 5600 层氮化硅镀膜，\n反射率降低至 1.5%\n官方海报显示，荣耀 Magic9 Pro Max 手机的屏幕支持 25 倍耐摔、15 倍耐刮，\n峰值亮度可达 10000 尼特\n博主 @数码闲聊站 已曝光荣耀 Magic9 Pro Max 手机规格信息，IT之家整理如下：\n6.8\"2868*1320p 1.5K+120Hz LTPO 大直屏，大 R 角极窄四等边\n骁龙 8EE6 处理器（第六代骁龙 8 超级至尊版），8800mAh 大电池 +100W 有线充 +80W 无线充\n55Mp F2.0 1:1 方形前摄，后置 200Mp 1/1.28\" F1.57 超大底主摄 +50Mp F2.0 超广角 +200Mp 1/1.4\" F2.6 大底潜望长焦\n3D 人脸识别 +3D 超声波指纹，AI 键 + 拍照键，横向大矩阵 Deco，双 1216 扬声器，IP68/69/69K\n▲ IT之家开箱：荣耀 Magic9 Pro Max 手机图赏","d":"2026-09-26","u":"https://www.ithome.com/1/007/429.htm","c":"通用技术/材料工程/特种功能材料/介电/导电材料","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"荣耀黑钻屏发布","sc":7.5,"scd":{"b":5.0,"i":9.0,"r":4.0,"d":8.0,"t":8.0},"aip":1,"as":"荣耀Magic9系列将于9月28日发布。Magic9 Pro Max搭载自研至臻黑钻屏，采用5600层氮化硅镀膜，反射率降至1.5%，峰值亮度达10000尼特，支持25倍耐摔、15倍耐刮。屏幕为6.8英寸1.5K 120Hz LTPO直屏。其他规格包括第六代骁龙8至尊版处理器、8800mAh电池配100W有线和80W无线充电、200Mp大底主摄与200Mp潜望长焦，并具备3D人脸识别、3D超声波指纹及IP68/69/69K防护。","kp":["反射率[荣耀Magic9 Pro Max至臻黑钻屏]: 1.5%","峰值亮度[荣耀Magic9 Pro Max至臻黑钻屏]: 10000尼特","镀膜层数[至臻黑钻屏氮化硅镀膜]: 5600层","耐摔[至臻黑钻屏]: 25倍","耐刮[至臻黑钻屏]: 15倍"]},{"t":"英国第二大图书馆：牛津大学博德利图书馆藏书被曝用于 OpenAI 模型训练","b":"IT之家 9 月 26 日消息，据英媒卫报消息，正值各大科技公司在学术机构中四处搜寻全新语料之际，牛津大学已允许 ChatGPT 开发商 OpenAI 利用其博德利图书馆（Bodleian Library）的历史典籍来训练其人工智能模型。\nIT之家注：博德利图书馆是英国牛津大学主要的研究图书馆，是英国规模仅次于大英图书馆的第二大图书馆。\n一份内部文件显示，由 OpenAI 完成数字化的博德利藏书已被用来“构建 OpenAI 的训练集”。牛津大学于 2025 年 3 月宣布与该公司达成合作，使用 OpenAI 的软件对该校这座享誉世界的图书馆藏书进行数字化处理。\n校方当时表示，此举将让广大学生和研究人员更便捷地查阅这些文献资料。然而，当时的合作公告并未提及这些资料会被用于训练 OpenAI 的模型。\nOpenAI 的一位发言人表示，公司很荣幸能够促成“当今的 AI 模型为后世守护人类的历史文化瑰宝”。\n该发言人还补充道：“目前全球已有超过十亿人在日常生活中使用这项技术，因此让它充分反映不同的文化、历史和视角至关重要。”\n一份根据《信息自由法》调取的牛津大学会议纪要显示，包括博德利管理委员会成员在内的教职员工均表达了顾虑。他们不仅担忧与 OpenAI 合作可能会引发声誉风险，还指出这项合作涉及高能耗技术，可能会对大学自身作出的环保承诺产生负面影响。\n在一个名为“NextGenAI”的项目下，OpenAI 已与包括波士顿公共图书馆、加州理工学院、麻省理工学院以及密歇根大学在内的多家美国研究型图书馆签署了类似协议。牛津大学则是该项目中唯一的英国成员。\n截至 2025 年 6 月，博德利图书馆已向 OpenAI 提供了 12.5 万份历史学位论文的扫描影印页，其中涵盖了 19 至 20 世纪欧美高校的博士论文。其他已扫描的文献还包括一份罕见的 16 世纪“宽边民谣 / 街头民谣（Broadside Ballads）”珍藏集，共计 1 万首，记录了曾流传于都铎王朝街头巷尾的歌词与乐谱。\n此外，教职人员还商讨了后续的数字化计划，涉及 18 世纪爱尔兰国家档案、爱尔兰小说家玛利亚 · 埃奇沃思（Maria Edgeworth）的私人信函，以及多萝西 · 霍奇金（Dorothy Hodgkin）关于青霉素研究的实验笔记。\n校方否认了向公众和学生隐瞒机器学习相关用途的指责。发言人表示，数字化确实是学校的核心诉求，但教职员工始终明确承认，该项目同时会为模型提供训练数据。\n牛津大学发言人表示：“通过与 OpenAI 合作完成数字化的文献资料规模有限，均已超出版权保护期；此外，OpenAI 对这些资料的使用权是非排他性的。”\n博德利图书馆同样保留了自主发布这些数字化资源的权利。在未来几个月内，图书馆将逐步在网络上公开提供这批资料，正如我们对待其他数字化合作成果一样。\n事实上，该项目将帮助博德利图书馆惠及更广泛的公众群体，让那些原本难以接触到这些文献的人能够轻松查阅。","d":"2026-09-26","u":"https://www.ithome.com/1/007/426.htm","c":"AI与智能科技/AI软件层/底座大模型/文本模型","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"行业观察","tp":"OpenAI训练语料争议","sc":5.1,"scd":{"b":3.0,"i":4.0,"r":6.0,"d":4.0,"t":7.0},"as":"据卫报报道，牛津大学允许OpenAI利用博德利图书馆的历史典籍训练AI模型。该校2025年3月与OpenAI达成数字化合作，但公告当时未提及资料将用于训练模型。截至2025年6月，图书馆已提供12.5万份19至20世纪历史学位论文扫描页。内部会议纪要显示教职员工担忧声誉风险及高能耗技术与学校环保承诺冲突。OpenAI还在'NextGenAI'项目下与波士顿公共图书馆、麻省理工等多家美国机构签署类似协议。","kp":["[OpenAI与牛津博德利图书馆合作]: 数字化藏书已被用于构建OpenAI训练集","[2025年3月合作公告]: 未提及藏书将用于训练OpenAI模型"]},{"t":"李小龙：华为大疆联名款 Osmo Pocket 4 云台相机有更多协同功能","b":"感谢IT之家网友\n9 月 26 日消息，华为官方今日宣布，\nHUAWEI × DJI Osmo Pocket 4 官宣 9 月 26 日起陆续到店\n。预热图显示，进店的 DJI Osmo Pocket 4 将印上“HUAWEI”的 LOGO。\nIT之家注意到，华为终端 BG CTO 李小龙刚刚发文透露，\n这款华为大疆联名款的 Osmo Pocket 4 有更多协同功能\n，更好用。具体支持哪些功能，李小龙暂未公布，但预计会支持与华为设备的联动。\n今年 4 月，大疆正式发布全新一英寸口袋云台相机 Osmo Pocket 4\n，该机搭载全新升级的一英寸 CMOS，拥有 14 级宽广动态范围，并支持 10‑bit D‑Log 专业色彩模式，定价为 2999 元起。\nOsmo Pocket 4 搭载智能跟随 7.0，支持最高 4 倍距离的智能跟拍。机身同步升级智能对焦系统，新增“锁定主角追焦”与“登记主角优先”模式，新增的手势控制功能，无需触碰屏幕，简单手势即可启动或停止跟随、开始或结束录制。\n华为 LOGO 印上大疆云台相机：HUAWEI × DJI Osmo Pocket 4 官宣 9 月 26 日起陆续到店\n大疆 Osmo Pocket 4 云台相机发布：搭 1 英寸传感器、支持智能跟随 7.0，2999 元起","d":"2026-09-26","u":"https://www.ithome.com/1/007/424.htm","c":"AI与智能科技/具身智能/硬件和控制","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"华为大疆联名相机","sc":5.4,"scd":{"b":2.0,"i":6.0,"r":4.0,"d":5.0,"t":8.0},"as":"华为与大疆联名款Osmo Pocket 4云台相机于9月26日宣布陆续到店，机身印有HUAWEI标志。华为终端BG CTO李小龙表示该联名款拥有更多协同功能，更好用，预计支持与华为设备联动，具体功能尚未公布。原版Osmo Pocket 4于今年4月发布，搭载一英寸CMOS，14级动态范围，支持10-bit D-Log色彩模式、智能跟随7.0、锁定主角追焦及手势控制，定价2999元起。","kp":["CMOS[Osmo Pocket 4]: 一英寸","动态范围[Osmo Pocket 4]: 14级","色彩模式[Osmo Pocket 4]: 10-bit D-Log专业色彩","智能跟随[Osmo Pocket 4]: 智能跟随7.0，支持最高4倍距离智能跟拍","[华为大疆联名款Osmo Pocket 4]: 具备更多协同功能"]},{"t":"华为 Mate 60、Pura 70 等机型推送 HarmonyOS 7.0.0.109 SP6 版本，新增智能识别信息内容等功能","b":"感谢IT之家网友\n9 月 26 日消息，华为今日面向老机型推送了鸿蒙\nHarmonyOS\n7.0.0.109 SP6\n版本，覆盖 Mate 60、Pura 70 等系列设备。据介绍，本次更新优化了部分场景的显示效果，同时提升了整机系统稳定性。\n▲ IT之家开箱：华为 Mate60 Pro+「宣白」图赏\nIT之家附新版本更新内容如下：\n智能识别信息内容，挪车提醒、候补车票成功等信息可通过实况窗展示，提醒更及时\n文本通话支持声音修复，当发音不清晰时，使用该功能可让对方听得更清晰，轻松实现无障碍沟通（设置 > 关怀和无障碍 > 文本通话，需通过应用市场将小艺更新至 11.7.7.301 及以上版本）\n优化控制中心部分场景的显示效果\n优化图库稳定性及部分界面的显示效果\n优化部分场景连接耳机的使用体验\n优化整机系统稳定性\n需要注意的是，华为\nHarmonyOS 系统常采取分批方式进行推送，未收到推送需继续等待。部分用户有快速升级的需求，可以通过“设置-软件更新-检查更新”尝试下载版本进行升级。","d":"2026-09-26","u":"https://www.ithome.com/1/007/422.htm","c":"AI与智能科技/AI软件层/工程改进","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"鸿蒙系统更新推送","sc":6.1,"scd":{"b":2.0,"i":8.0,"r":4.0,"d":4.0,"t":8.0},"as":"华为9月26日面向Mate 60、Pura 70等老机型推送HarmonyOS 7.0.0.109 SP6版本。更新新增智能识别信息内容功能，挪车提醒、候补车票成功等信息可通过实况窗展示；文本通话支持声音修复，发音不清晰时可使对方听得更清晰，需将小艺更新至11.7.7.301以上版本；同时优化控制中心和图库显示效果、耳机连接体验及整机系统稳定性。系统采取分批推送方式。","kp":["系统版本[HarmonyOS推送]: 7.0.0.109 SP6","小艺版本要求[文本通话声音修复]: 11.7.7.301及以上"]},{"t":"OpenCode 宣布为 DeepSeek V4.1 Flash 永久提供 60 美元额度","b":"IT之家 9 月 26 日消息，OpenCode 昨日宣布启动“Operation Cheepseek”第二阶段，DeepSeek V4.1 Flash 在 OpenCode Go 中原本限时提供的 60 美元（IT之家注：现汇率约合 403.5 元人民币）额度现调整为永久有效。\n此前，OpenCode 曾将 DeepSeek V4.1 Flash 的使用额度临时提升至原标准的 4 倍，即从 15 美元提高至 60 美元，并计划于 9 月 20 日结束该活动。OpenCode 当前 Go 页面已将该模型的额度标注为 60 美元，原 15 美元额度被划线标记。\nDeepSeek 最新发布的 V4.1 Flash 采用 5520 亿参数的 MoE 架构，输入侧激活参数量为 80 亿，输出侧为 160 亿，并采用新的 Causal Encoder-Decoder 架构。模型同时支持原生多模态视觉理解。\n与上一代相比，DeepSeek V4.1 Flash 的 KV Cache 对 HBM 的需求降低至四分之一，对 SSD 的需求降低至八分之一。\nDeepSeek 此前还宣布 OpenCode 已作为官方合作伙伴全量接入 V4.1 Flash。OpenCode 数据显示，截至 9 月 25 日，该模型在平台近期使用量中排名第一，占观测到的 200 万级使用量的约 13%。","d":"2026-09-26","u":"https://www.ithome.com/1/007/421.htm","c":"AI与智能科技/AI软件层/底座大模型/文本模型","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"DeepSeek V4.1 Flash","sc":6.4,"scd":{"b":6.0,"i":6.0,"r":5.0,"d":7.0,"t":7.0},"as":"OpenCode宣布启动'Operation Cheepseek'第二阶段，将DeepSeek V4.1 Flash在OpenCode Go中的60美元使用额度从限时调整为永久有效，此前该额度曾从15美元临时提升4倍。DeepSeek V4.1 Flash采用5520亿参数MoE架构，输入激活参数80亿、输出160亿，采用Causal Encoder-Decoder架构并支持原生多模态视觉理解，KV Cache对HBM需求降至四分之一、SSD需求降至八分之一。截至9月25日，该模型在平台使用量排名第一，约占13%。","kp":["总参数量[DeepSeek V4.1 Flash]: 5520亿","架构[DeepSeek V4.1 Flash]: MoE，Causal Encoder-Decoder","激活参数量[输入侧]: 80亿","激活参数量[输出侧]: 160亿","KV Cache对HBM需求[V4.1 Flash相比上代]: 降低至四分之一"]},{"t":"中国天眼 FAST 联合 DESI 观测：恒星“减产”并非燃料耗尽，宇宙缺的不是气而是“加工”能力","b":"感谢IT之家网友\n9 月 26 日消息，中国科学院国家天文台、上海天文台、上海交通大学等组成的国际合作团队，利用“中国天眼”（FAST）与国际暗能量光谱仪（DESI）联合观测，对过去 45 亿年的宇宙中性氢演化进行高精度测量。\n研究发现，宇宙恒星形成活动显著减弱的同时，中性氢储备并未同步枯竭。相关成果发表于《自然 · 天文》杂志。\n恒星形成率下降是星系演化领域的核心问题。一个流行解释是，孕育恒星的冷气体不断被消耗，导致造星活动衰退。如果这一图景成立，恒星形成率下降应伴随冷气体储备的同步骤减。但此次测量给出了不同答案。\n中性氢是星系中重要的冷气体储备，通过极其微弱的 21 厘米射电谱线发出信号（该谱线频率约 1420MHz，是中性氢原子的特征辐射）。遥远星系的单个信号常淹没在背景噪声中，过去观测长期受限于“看得深却看不广、看得广又不够深”的瓶颈。\n▲ 图为宇宙中性氢密度随红移的演化趋势。黑色圆点代表本研究团队测量的数据点。\n研究团队将 FAST 的高灵敏度射电观测与 DESI 的大规模光谱巡天深度结合，分析覆盖约三分之一天区的约 250 万个星系。他们利用中性氢谱线叠加技术，将大量微弱信号按星系红移精确对齐后叠加，从噪声中提取出平均信号，以前所未有的统计精度追踪中性氢演化轨迹。\n测量结果显示：45 亿年前的宇宙恒星形成率约为今天的 2.5 倍，而同期中性原子氢密度仅约为今天的 1.4 倍。论文通讯作者、中国科学院上海天文台研究员郭宏表示，如果“燃料耗尽”是主因，两者本应同步骤减，但数据并不支持这一说法。\n恒星并非直接由中性氢形成。中性氢需先转变成更致密的分子氢云，分子氢云才是恒星真正的“产房”。论文第一作者、中国科学院国家天文台副研究员张传朋解释，晚期宇宙真正显著变化的，可能是气体从中性氢向分子氢、再到恒星的转化过程。\n随着供气减弱、气体密度降低，中性氢向分子氢转变的效率下降。中性氢储备得以相对稳定保留，而真正能直接孕育恒星的分子气体却在慢慢减少。“我们看到的不是宇宙缺气，而是气越来越难被‘加工’成恒星。”郭宏说。\n该研究由中国科学院国家天文台姜鹏研究员团队、上海天文台郭宏研究员团队，以及上海交通大学杨小虎教授、景益鹏院士团队，联合 DESI 国际团队共同完成。论文第一作者为国家天文台张传朋副研究员、上海天文台郭宏研究员、上海交通大学顾一舟助理研究员。\nIT之家附论文地址：\nhttps://doi.org/10.1038/s41550-026-02965-9\n“中国天眼”FAST 落成启用十年，将继续推进 FAST 二期工程\n中国天眼 FAST 构建世界最大中性氢星系样本库，探测源达 15.6 万个","d":"2026-09-26","u":"https://www.ithome.com/1/007/420.htm","c":"通用技术/基础学科/基础物理","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"行业观察","tp":"中性氢演化观测","sc":7.4,"scd":{"b":9.0,"i":3.0,"r":6.0,"d":7.0,"t":8.0},"aip":1,"as":"中科院国家天文台、上海天文台、上海交通大学等团队利用FAST与DESI联合观测，高精度测量过去45亿年宇宙中性氢演化。研究将FAST高灵敏度射电观测与DESI大规模光谱巡天结合，分析约250万个星系，用谱线叠加技术提取信号。结果显示45亿年前恒星形成率约为今天的2.5倍，而中性氢密度仅为今天的1.4倍，表明恒星'减产'并非因冷气体燃料耗尽，气体向分子氢转化的效率下降可能是主因。成果发表于《自然·天文》。","kp":["[中性氢21厘米谱线]: 频率约1420MHz，为中性氢原子特征辐射","观测星系数量[FAST联合DESI中性氢研究]: 约250万个，覆盖约三分之一天区","研究方法[FAST联合DESI]: 中性氢谱线叠加技术","研究结论[过去45亿年宇宙中性氢演化]: 恒星形成活动减弱同时中性氢储备并未同步枯竭，恒星减产并非燃料耗尽"]},{"t":"微软 Xbox 新一轮重组波及多家工作室：黑曜石划归贝塞斯达后引发员工担忧和不满，忍者理论出售未果面临关闭","b":"9 月 26 日消息，微软于当地时间 9 月 22 日宣布对旗下游戏工作室进行新一轮架构调整，同时裁撤 268 个岗位。这是继 2026 年 7 月首轮裁员后的又一次重大变动。\n据《The Game Business》，Xbox 近期重组后，部分工作室被重新划分至动视和 ZeniMax 旗下，引发了开发团队对工作室自主权、项目成本及未来项目命运的担忧。\n其中，黑曜石（Obsidian）的员工对工作室被纳入贝塞斯达（Bethesda）体系并不满意。消息人士称，黑曜石过去拥有较高的自主权，可以自由决定开发项目，而此次组织架构调整可能改变这一状况。\nBethesda 此前公开表示，不希望此次调整影响黑曜石的独立运作方式。不过，目前尚无法确认新架构下黑曜石的实际决策权限是否会发生变化。\n《The Game Business》主编克里斯 · 德林认为，近年来黑曜石推出的游戏虽然获得一定评价，但销量和玩家参与度没有达到微软及工作室此前预期。他将此次 Xbox 重组形容为类似“反向收购”的过程，即动视和 ZeniMax 体系中的 IP 及发行资源正在吸收 Xbox Game Studios 旗下部分业务。\n与此同时，黑曜石已经确认，《天外世界 2》此前承诺推出的 DLC 仍将继续开发。不过，该系列后续作品目前暂未有进一步安排。\n另一家受到关注的工作室是 Undead Labs。微软今年 7 月曾宣布该工作室将被第三方收购，但最终 Undead Labs 选择通过管理层及员工方面的安排实现独立运营，同时伴随着部分裁员。\n克里斯 · 德林透露，Undead Labs 最初的潜在收购方是英国游戏开发商 Splash Damage，但双方交易最终因未知原因告吹。此后曾有其他交易方案被讨论，包括一度出现的 Krafton，但目前没有进一步确认。\n相比之下，忍者理论（Ninja Theory）的情况更为严峻。该工作室此前同样被宣布计划出售，但相关交易最终未能完成，微软目前正在考虑关闭工作室。\n德林称，Xbox 此前表示至少有两方对 Ninja Theory 感兴趣，但相关交易均已失败。他接触到的两名潜在投资方认为，该工作室的团队运营成本过高，因此没有继续推进。\nNinja Theory 目前正在开发下一款作品《Senua》。德林援引 Xbox Game Studios 内部人士的说法称，该项目目前进展良好，相比《地狱之刃 2》有明显改进。不过，如果工作室最终关闭，该项目能否完成并正式发行仍存在不确定性。\nRare 工作室此次没有出现大规模裁员，但组织架构被调整至动视体系。该工作室此前负责《盗贼之海》等作品，同时还有其他项目处于开发阶段，后续是否继续将由动视方面决定。\nRare 此前的《Everwild》项目已经取消，并因此产生部分人员调整。工作室随后将部分员工转移至《盗贼之海》项目，同时减少外包规模，以降低人员调整带来的影响。\n黑曜石并入 B 社的“定心丸”：官方回应称领导层不变、游戏项目路线不变\n微软 Xbox 裁员波及黑曜石：〈宣誓〉艺术总监马特 · 汉森被炒，此前曾因 DEI 言论引发争议\n消息称微软 XBOX 部门重组后，原 Halo Studios 开发的〈光环 7〉游戏新作及二 / 三代重制版均已被叫停\nDreunen 教授称微软重组游戏业务形成“反向收购”格局：XBOX 自有 IP 转向动视等\n仅剩 20 人，消息称微软 XBOX 旗下光环工作室近乎解散","d":"2026-09-26","u":"https://www.ithome.com/1/007/419.htm","c":"不相关","a":"IT之家","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"行业观察"},{"t":"约30亿元！中比新能源12GWh钠电项目落地江苏南京","b":"本次新建产线将实现32140系列钠离子电芯的规模化制造，持续迭代优化电芯性能，推动钠离子电池从小批量送样走向大规模商业化应用，为市场提供锂电之外的高性价比储能及动力电池解决方案。\n据“中比新能源”消息，9月23日，中比新能源与南京高淳经济开发区正式完成投资协议签约，12GWh钠离子电芯项目即将落地江苏南京高淳。\n据悉，该项目规划总投资约30亿元，全面建成达产后，预计可为公司新增48~50亿元销售额，公司计划于2027年下半年推动项目建设相关工作落地实施。本次新建产线将实现32140系列钠离子电芯的规模化制造，持续迭代优化电芯性能，推动钠离子电池从小批量送样走向大规模商业化应用，为市场提供锂电之外的高性价比储能及动力电池解决方案。\n技术层面，中比新能源自研的32140系列钠离子电芯已经完成多轮严苛性能验证，具备优异宽温域、高安全、长循环综合性能，-40℃低温环境放电保持率表现依然突出，可适配南北不同地域、高低温差异大的复杂工况环境，产品面向户用储能、便携储能、轻型交通工具、备用电源等多元化场景。\n资料显示，中比新能源作为国内大圆柱电池领域的主流企业，长期深耕锂电、钠电双技术路线研发与制造，依托南京高淳成熟的产业配套、营商环境与区位优势，本次重大项目落地，是政企双向赋能、协同发展的重要成果。\n项目聚焦钠离子电芯研发、规模化生产与系统集成业务，建成后将面向储能、轻型动力、特种电源等多元市场输出钠电产品，作为新能源领域的另一重要技术路线，助力全球电动化提速。\n更多行业价值资讯浏览、分享，欢迎扫描下方二维码关注我爱电车网官方微信（xevcar）！","d":"2026-09-26","u":"http://www.xevcar.com/gongsi/092615Q452026.html","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/钠电","a":"我爱电车网","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"中比新能源钠电项目","sc":7.0,"scd":{"b":4.0,"i":8.0,"r":5.0,"d":7.0,"t":7.0},"aip":1,"as":"中比新能源9月23日与南京高淳经济开发区签约，12GWh钠离子电芯项目落地江苏南京，规划总投资约30亿元，预计达产后新增48~50亿元销售额，计划2027年下半年推进建设。项目将实现32140系列钠离子电芯规模化制造，该电芯已完成多轮性能验证，具备宽温域、高安全、长循环性能，-40℃低温放电保持率突出，面向户用储能、便携储能、轻型交通工具、备用电源等场景。","kp":["项目产能[中比新能源钠离子电芯项目]: 12GWh","项目总投资[中比新能源钠电项目]: 约30亿元","电芯型号[中比新能源]: 32140系列钠离子电芯","低温放电保持率[32140系列钠离子电芯]: -40℃环境下表现突出","达产后新增销售额[中比新能源钠电项目]: 预计48~50亿元"]},{"t":"长安汽车：已开展20Ah氧聚复合固态电池验证","b":"关于固态电池项目，长安汽车正有序推进研发，已开展20Ah氧聚复合固态电池验证。\n近日，重庆辖区上市公司投资者网上集体接待日暨半年度业绩说明会举行，长安汽车（000625）资本运营部副总经理，董事会办公室副主任谢仁军表示，公司在三电和智能化领域均已进行系统布局。三电方面，公司已实现电池、电驱、电控产业布局全覆盖：电池领域打造了“金钟罩”电池品牌，获2025年国家科技进步二等奖；电驱领域，量产行业首款多合一电驱，太行分布式电驱技术正式迈入量产与普及阶段；电控领域，行业首发“七合一”跨域融合SVDC。\n智能化方面，长安汽车继去年12月获得国内首块L3级自动驾驶专用正式号牌后，今年又获批L4级自研Robotaxi测试牌照，成为拥有全合规、全场景L4级无人驾驶实测资格的车企；2026年9月4日公司正式发布天枢领航，为公司全栈自研的智能辅助驾驶解决方案，全系搭载激光雷达、全系采用“端到端”技术，目前天枢领航已进入量产上车阶段。公司将持续推进电池技术的自主研发与产业化。\n关于固态电池项目，长安汽车正有序推进研发，已开展20Ah氧聚复合固态电池验证。公司将加速推动具身智能人形机器人、飞行汽车等新兴产业布局和产业化落地，力争在2028年实现人形机器人量产、2030年推出商用航线飞行汽车，各项研发均按计划有序推进，具体进展以公司官方发布为准。\n钠离子电池领域，长安汽车已取得阶段性进展，钠离子电池突破高功率极片单点技术，提升极端温况续航体验；此外公司深化与宁德时代合作，钠新换电技术项目立项，共同研发新体系电池。\n更多行业价值资讯浏览、分享，欢迎扫描下方二维码关注我爱电车网官方微信（xevcar）！","d":"2026-09-26","u":"http://www.xevcar.com/gongsi/092615Q412026.html","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/固态电池","a":"我爱电车网","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"技术突破","tp":"固态电池验证","sc":5.8,"scd":{"b":5.0,"i":6.0,"r":5.0,"d":5.0,"t":6.0},"as":"长安汽车在投资者接待日披露，固态电池研发有序推进，已开展20Ah氧聚复合固态电池验证。三电领域，公司打造'金钟罩'电池品牌获2025年国家科技进步二等奖，量产行业首款多合一电驱，行业首发'七合一'跨域融合SVDC。智能化方面已获批L4级Robotaxi测试牌照，全栈自研天枢领航智能辅助驾驶方案全系搭载激光雷达并采用端到端技术，已量产上车。公司还突破钠电池高功率极片技术，并与宁德时代合作钠新换电项目，计划2028年量产人形机器人。","kp":["固态电池验证[长安汽车]: 已开展20Ah氧聚复合固态电池验证","自动驾驶等级[长安汽车]: 获国内首块L3级自动驾驶专用正式号牌，获批L4级自研Robotaxi测试牌照","技术路线[天枢领航]: 全栈自研，全系搭载激光雷达、全系端到端技术"]},{"t":"2.4亿元！辽宁丹东一电化学储能电站项目签约","b":"希格斯东港电化学储能电站项目，将落户辽宁丹东东港经济开发区，规划装机容量100MW/200MWh，采用磷酸铁锂电化学储能技术路线。\n据“丹东发布”消息，9月23日，在第七届中国辽宁国际投资贸易洽谈会开幕式上，东港市与山东希格斯新能源有限责任公司签约100MW/200MWh电化学储能电站项目，总投资2.4亿元。\n据悉，希格斯东港电化学储能电站项目，将落户辽宁丹东东港经济开发区，规划装机容量100MW/200MWh，采用磷酸铁锂电化学储能技术路线，主要建设储能电池系统、储能变流器系统、BMS/EMS/通讯监控系统及并网配套设施。\n资料显示，项目投资方山东希格斯新能源有限责任公司是国家级高新技术企业，拥有授权专利88项，在电化学储能领域具备成熟的技术积累和项目经验。\n更多行业价值资讯浏览、分享，欢迎扫描下方二维码关注我爱电车网官方微信（xevcar）！","d":"2026-09-26","u":"http://www.xevcar.com/gongsi/092615Q3H026.html","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"我爱电车网","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"储能电站签约","sc":5.5,"scd":{"b":2.0,"i":7.0,"r":3.0,"d":6.0,"t":7.0},"as":"9月23日，东港市与山东希格斯新能源在第七届中国辽宁国际投资贸易洽谈会上签约100MW/200MWh电化学储能电站项目，总投资2.4亿元。项目落户辽宁丹东东港经济开发区，采用磷酸铁锂技术路线，主要建设储能电池系统、储能变流器系统、BMS/EMS/通讯监控系统及并网配套设施。投资方希格斯新能源为国家级高新技术企业，拥有授权专利88项，在电化学储能领域具备成熟技术积累。","kp":["装机容量[希格斯东港储能电站]: 100MW/200MWh","技术路线[希格斯东港储能电站]: 磷酸铁锂电化学储能","项目总投资[希格斯东港储能电站]: 2.4亿元"]},{"t":"总投资2.4亿！希格斯新能源辽宁东港电化学储能电站项目落地","b":"希格斯东港电化学储能电站项目，将落户辽宁东港经济开发区，规划装机容量100MW/200MWh，采用磷酸铁锂电化学储能技术路线，主要建设储能电池系统、储能变流器系统等配套设施。\n图片来源：东港发布\n9月23日，在第七届中国辽宁国际投资贸易洽谈会开幕式上，东港市与山东希格斯新能源有限责任公司（简称：希格斯新能源）签约100MW/200MWh电化学储能电站项目，总投资2.4亿元。\n据介绍，希格斯东港电化学储能电站项目，将落户东港经济开发区，规划装机容量100MW/200MWh，采用磷酸铁锂电化学储能技术路线，主要建设储能电池系统、储能变流器系统、BMS/EMS/通讯监控系统及并网配套设施。\n资料显示，投资方希格斯新能源成立于2012年，深耕锂电领域数年，已构建覆盖研发、生产、销售及售后的完整生态链，是国家级高新技术企业，拥有授权专利88项，在电化学储能领域具备成熟的技术积累和项目经验。\n更多行业价值资讯浏览、分享，欢迎扫描下方二维码关注我爱电车网官方微信（xevcar）！","d":"2026-09-26","u":"http://www.xevcar.com/gongsi/092615Q3R026.html","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"我爱电车网","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"储能电站落地","sc":5.4,"scd":{"b":2.0,"i":7.0,"r":2.0,"d":6.0,"t":7.0},"as":"希格斯新能源与辽宁东港市签约100MW/200MWh电化学储能电站项目，总投资2.4亿元，落户东港经济开发区。项目采用磷酸铁锂电化学储能技术路线，将建设储能电池系统、储能变流器系统、BMS/EMS/通讯监控系统及并网配套设施。希格斯新能源成立于2012年，深耕锂电领域，构建了覆盖研发、生产、销售及售后的完整生态链，是国家级高新技术企业，拥有授权专利88项。","kp":["装机容量[希格斯东港储能电站]: 100MW/200MWh","技术路线[希格斯东港储能电站]: 磷酸铁锂电化学储能","项目总投资[希格斯东港储能电站]: 2.4亿元","授权专利[希格斯新能源]: 88项"]},{"t":"这些电池经过14年高强度使用后测试：还能再用十年","b":"CATL supplied the cells for the world’s first large-scale battery energy storage project. Fourteen years later, not one has been replaced.\nPhoto by:\n9:00am ET\nChina’s CATL knows a thing or two about making batteries, and the company’s expertise goes back decades.\nTo prove a point, CATL tested several 14-year-old LFP cells to see how they held up to the test of time.\nThe cells were part of the world’s first large-scale stationary energy storage system, constantly charging and discharging.\nEveryone should know by now that modern high-voltage batteries like the ones found in electric cars and energy storage systems are\nincredibly robust\n. Several studies and reports have shown that the latest generation of lithium-ion cells can comfortably outlive the vehicles they power, with failure rates going as low as 0.3%.\nNot to be outdone, China’s CATL, which happens to be the world’s largest manufacturer of EV and energy storage batteries, wants to show everybody that its lithium iron phosphate (LFP) cells can be even more dependable. That’s good to know because CATL’s LFP batteries can be found in countless EVs around the world.\nThe company pulled dozens of cells from the remains of the Zhangbei Project, which was the world’s first large-scale lithium-ion battery energy storage project, and tested them. The results were better than expected.\nAs a bit of background, the Zhangbei Project’s 63 megawatt-hour battery system went online back in 2011, powered the 2022 Winter Olympics with green energy, and remained active until June 2025. After nearly 14 years of operation, constantly charging and discharging, all of the cells are still in working order. Not one of them has been replaced.\nNine years after being energized, when everyone in the world was staying at home during Covid, CATL took some samples out of the Zhangbei Project and found that they were still good for another 6,000 cycles. That said, that was just an intermediate step to the final story.\nAfter it was decommissioned in 2025, over 50 of the original lithium-iron-phosphate (LFP) prismatic cells were sent back to CATL’s labs to be inspected for damage and to determine how much life they still had in them.\nEngineers and chemists ran several tests and found that the 14-year-old cells still had roughly 85% of their original capacity left, meaning that they could still be used in smaller or secondary energy storage systems for another 10 years, with around 1,000 charge and discharge cycles possible.\nBut that’s not all. The internal structure of the cells stood up to the test of time incredibly well, with anodes and cathodes still neatly aligned, good lithium intercalation, and no obvious aging in the graphite.\nStay informed with our newsletter every weekday\nThe results are partly due to CATL’s obsession with safety, but it also comes down to the fact that LFP cells have proved time and time again that they can survive abuse better than comparable nickel manganese cobalt (NMC) cells, though that comes at the expense of energy density.\nLFP batteries are also cheaper to make, and they’re slowly but surely making their way into more and more Western EVs, including the upcoming\nSlate truck\nFord Fathom\nMore Battery Stories\nFacebook\nLinkedIn\nFlipboard\nWhatsApp\nRECOMMENDED FOR YOU\nThe Tesla Cybertruck Finally Gets A Feature That Was Promised Three Years Ago\nForget Politics. EVs Have An Age Problem\nMassachusetts EV Owners Will Earn Money By Selling Battery Power\nBentley Goes Electric As China's EV Charging War Gets Ridiculous\nWhy BMW Isn't Giving Up On Hydrogen Cars\nVolkswagen Delays Ontario Battery Plant\nSodium Batteries And EVs That Power The Grid: Inside GM's Big Energy Push","d":"2026-09-26","u":"https://insideevs.com/news/809604/catl-lfp-prismatic-cell-age-test/","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"INSIDEEVs","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"技术突破","tp":"旧电池寿命测试","sc":6.9,"scd":{"b":4.0,"i":7.5,"r":6.0,"d":6.0,"t":7.0},"aip":1,"as":"宁德时代对参与全球首个大规模固定式储能项目的电芯进行了14年后测试。这些磷酸铁锂电池在持续充放电的高强度使用14年后，无一被更换，仍保持良好性能。该测试证明了现代锂电池的耐久性，多项研究和报告表明新一代锂离子电池的寿命可超过其所供电的电动汽车和储能系统本身，凸显锂电池在长周期储能应用中的可靠性。","kp":["电池类型[CATL储能项目]: 磷酸铁锂(LFP)","使用时长[大规模固定式储能系统]: 14年","更换情况[世界首个大型电池储能项目]: 无一更换","寿命预期[14年使用后]: 还能再用十年"]},{"t":"别谈政治了，电动车面临的是“车龄”问题","b":"Forget Politics. EVs Have An Age Problem\nRepublicans and Democrats are surprisingly aligned on EV buying intent. It's Boomers that are the problem.\nFor years, the most visible divide over electric vehicles has seemed to be political—just look at all those “I bought this before Elon went crazy” bumper stickers. But new polling suggests that the way a person votes may be a far worse predictor of EV interest than you’d think.\nAccording to a new survey published by the Zero Emission Transportation Association, an EV industry group, age is a far bigger fault line than political affiliation. The findings say a lot about where the car market is headed, so let’s unpack.\nPer the study, 36% of adults aged 18-34 and 40% of adults aged 35-49 said they were “very likely” to purchase or lease a new EV. Those were among the groups most likely to go electric in a report that sliced and diced the data from 1,300 respondents across many demographic lines: location, gender, income, and so on.\nAmong adults ages 50-64, that number falls to 18%. And zeroing in on the 65-plus crowd, things start to look ugly. Just 4% of respondents in that category said they were very likely to buy an EV.\nCritical Materials subscribers got this post early\nOur weekly newsletter unpacks the biggest EV news every Friday\nThe oldest group was also the sourest on EVs, with 40% of respondents saying they had a somewhat or very negative opinion of the technology. Among 18-34 year olds, that figure was just 5%. Three-quarters said they had a positive view on electric cars.\nSurprisingly, Democrats and Republicans were far more aligned. Twenty-six percent of left-leaning voters said they were very likely to buy an EV. For those on the right, it was only a little less, at 22%. However, Republicans did show more skepticism toward electric cars; 42% said they were “not likely” to buy an EV, compared to only about a quarter of Democrats.\nOn the one hand, the generational gap is exactly the opposite of what you’d want to accelerate electrification right now. The average car buyer is around 50 years old. Baby Boomers are the wealthiest generation and, apparently, not too down with electric propulsion. Young people, enthusiastic though they may be, are simply far less likely to be in a position to buy a $40,000 or $50,000 car. This may help explain all the action on the used market; younger, less wealthy buyers are getting into EVs secondhand.\nBut you could also view the findings as a structural advantage for EV adoption, just like improving economics or the fact that the cars are just a better experience. Those 18-49 year olds have potentially several decades of car-buying ahead of them, so the pool of EV buyers is set to grow dramatically.\nAssuming the industry gets the rest right—more charging infrastructure, lower prices, more options—that could help speed things along.\nRECOMMENDED FOR YOU\nVolkswagen Delays Ontario Battery Plant\nThese Battery Cells Were Tested After 14 Years Of Hard Work. They're Good For Another Decade\nWaymo's Latest Safety Numbers Sure Make Human Drivers Look Bad\nBentley Goes Electric As China's EV Charging War Gets Ridiculous\nAmericans Are Buying Hybrids At A Record Pace. And It's Not Just Toyota Anymore\nInside The Texas Factory Racing To Break China’s Grip On EV Magnets\nThis Audi EV Set A Guinness World Record By Driving 831 Miles Without Recharging","d":"2026-09-26","u":"https://insideevs.com/news/809672/forget-politics-evs-have-an-age-problem/","c":"不相关","a":"INSIDEEVs","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"行业观察"},{"t":"Volkswagen推迟安大略电池工厂项目","b":"The auto giant's North American EV plan faced another setback this week.\nPhoto by:\nSuvrat Kothari\n6:00am ET\nVolkswagen is building an EV battery plant in Ontario, Canada.\nThe subsidiary building the plant announced this week that the start of production will be delayed by two years, to 2029.\nThe automaker also announced this week that the ID. Buzz would not return to the U.S. as a 2027 model, as previously planned.\nVolkswagen's EV plans took another hit this week, as its subsidiary PowerCo Canada announced that its forthcoming Ontario battery plant will be delayed by two years. The company now expects production to commence in 2029.\nfollows news that the Volkswagen ID. Buzz would not return to the lineup as a 2027 model\n, as the automaker previously planned. It will skip another model year, with an upgraded version returning as a 2028 model in the first half of next year, VW says.\nBoth the ID. Buzz and the Canadian battery plant have been battered by U.S. President Donald Trump's trade war, which has complicated the financials for either project. The ID. Buzz was already expensive and didn't offer much range for the price; a 25% tariff certainly doesn't help. Meanwhile battery plants are being scaled back or rethought throughout the world as automakers adjust to slower-than-expected demand and a new trade environment.\nVolkswagen has been hit hard by all of these changes\n. It faces a contracting business in China, more competition at home, and steep tariffs in the U.S. It's also struggling with the transition to EVs and with higher energy prices in Europe, where it is shuttering factories and laying off workers.\nLast year it closed a plant in Germany for the first time in its 88-year history\nIt's fair to say things have not gone to plan.\nThe company is looking to navigate its way through this by localizing supply chains, improving its electric products, and leveraging partnerships to learn more about building low-cost software-defined vehicles. The company has a\njoint venture with Rivian for software and software-defined vehicle architectures\n, and is working closely with\nChinese brand Xpeng on next-generation vehicles for that market\nRelated News\nThe Ontario delay marks another bump in the road to localizing and electrifying its operations. The company has been particularly exposed in North America. Its two factories in Mexico now face U.S. tariffs, and its Chattanooga, Tennessee, plant now only builds the VW Atlas and Atlas Cross Sport. The ID.4 EV was built there,\nbut was discontinued so the plant could build more gas SUVs.\nThe plan is still to localize EV production here at some point, with software-defined models using tech from the Rivian joint venture. But it's going to take longer than expected.\nFacebook\nLinkedIn\nFlipboard\nWhatsApp\nRECOMMENDED FOR YOU\nEV Sales Keep Surging In Europe, Now Make Up 29% Of New Car Sales\nThese Battery Cells Were Tested After 14 Years Of Hard Work. They're Good For Another Decade\nThe Volkswagen ID.4 Just Got Up to $12,500 Cheaper in America\nForget Politics. EVs Have An Age Problem\nVolkswagen Bets You'll Pay Up For In-Car Gaming\nBentley Goes Electric As China's EV Charging War Gets Ridiculous\nVolkswagen Delays The ID. Buzz's Return To The U.S. Again","d":"2026-09-26","u":"https://insideevs.com/news/809662/vw-ontario-battery-plant-delay/","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"INSIDEEVs","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"电池工厂延期","sc":5.1,"scd":{"b":1.5,"i":6.0,"r":4.5,"d":5.0,"t":7.5},"as":"大众汽车旗下PowerCo Canada宣布，其位于加拿大安大略省的电动汽车电池工厂投产时间将推迟两年至2029年。这是大众北美电动车计划的又一次挫折。同一周，大众还宣布ID. Buzz将不会按原计划作为2027款车型重返美国市场，将跳过一个车型年，反映出大众电动车业务扩张面临的持续压力。","kp":["量产时间[安大略PowerCo电池工厂]: 推迟两年至2029年"]},{"t":"走进德州工厂：竞相打破中国对电动车磁铁的掌控","b":"Inside The Texas Factory Racing To Break China’s Grip On EV Magnets\nMP Materials' rare earth magnet factory is on the cusp of making history. Will it be enough?\nInside MP Materials' \"Independence\" factory in Fort Worth, Texas, items that look like gum strips, corn flakes, and crushed pepper are laid out on a table. A giant U.S. flag hangs from the ceiling, and employees wearing protective thermal suits work near equipment where temperatures surpass 1,000 degrees Celsius. Under bright white lights, a shiny red Cadillac Vistiq gleams with its electric motor ripped open on a table, revealing what's inside: rare earth magnets.\nThe magnets are tiny, roughly equivalent to a miniature Hershey's candy. They feel robust and solid to hold, with smooth texture and sharp edges. Above all, their importance is hard to overstate. They're used in everything from military weapons and fighter jets to medical devices, iPhones, and electric vehicles.\nThe rotor of the Cadillac Vistiq with a V-shaped magnet arrangement.\nThere’s just one big elephant in the room: China dominates the production of rare earth magnets. The country has the largest known rare earth reserves in the world, accounting for 49% of global supply, according to the International Energy Agency. Virtually all the rare earths used in the U.S. currently are sourced from overseas, giving Beijing incredibly strong leverage over its trading partners.\nAfter the Trump administration imposed sweeping tariffs on Chinese goods last year, China retaliated with export controls on rare earth magnets, sending U.S. companies that depend on them scrambling to secure supply. Ford even suspended production of the Explorer SUV for a week because a supplier ran out of magnets. The U.S. eventually caved to Chinese pressure by trimming the tariff percentages, although China’s reduced export controls are still in effect.\nNow American rare earths specialist MP Materials is attempting something that hasn’t been done in decades: resuscitate the rare earths supply chain in the U.S. It owns and operates Mountain Pass in Southern California’s Mojave Desert, the only rare earth mine and refining facility in the Western hemisphere and the largest of its kind outside China, according to the company.\nIts Independence factory in Fort Worth turns the raw material from that mine into automotive-grade magnets for electric motors. In a boost to that effort, General Motors is partnering with MP Materials to source EV magnets domestically and protect itself from policy swings and tariff chaos. It’s part of GM’s vision of localizing its EV supply chain, a mission that’s looking more urgent by the day.\n[Full Disclosure: General Motors invited me to tour the Independence factory in Texas. It paid for travel and accommodations.]\nWhy EVs Need Rare Earth Magnets\nThe buttery-smooth acceleration in EVs, the instant torque, and the excellent energy conversion efficiency compared to combustion engines—all this has a strong connection to the quality of the rare earth magnets used in traction motors.\nInduction motors, which don't rely on rare earths, are also common in EVs, but permanent magnet motors are more power dense, deliver higher torque, and are more efficient in converting electricity into forward motion for the vehicle. The majority of EVs on sale today use permanent magnet motors or a mix of permanent magnet and induction motors, depending on the vehicle and its drivetrain. In crossovers like the Chevy Equinox EV, induction motors primarily exist for all-wheel drive assist, whereas the permanent magnet motor is the primary workhorse, GM said.\nWhat the neodymium-iron-boron (NdFb) magnets look like after cutting, coating, and finishing.\nTo understand the role of rare earth magnets in EVs, it helps to break down the electric motor itself. Each one contains two key subcomponents: a rotor and a stator. The stator holds copper coils, draws energy from the battery, and generates a magnetic field. The rotor, which houses the rare earth magnets, interacts with that magnetic field, and the resulting motion spins the shaft and turns the wheels.\nThe magnet at the center of all this is neodymium-iron-boron, or NdFeB, one of 17 rare earth elements and among the most valuable because it carries the strongest magnetic properties. GM said each large rotor contains 192 of these neodymium magnets, while a smaller version of the rotor uses 128.\nIt's one of the tiniest components in an EV, but it's central to what makes driving one feel so smooth. Because its production is so heavily concentrated in China, it’s often the subject of trade wars between the world's superpowers.\nHow GM Picked MP Materials\nThe vast majority of rare earths used by the U.S. auto industry come from China, but it is gradually exploring alternative supply chains. It mirrors a similar shift in the battery business, where automakers are now trying to source more cells from local plants instead of purely relying on Chinese suppliers. Regulation is pushing them in that direction, too.\nShilpan Amin, the global chief supply chain and procurement officer at GM, said the bet on the U.S.-made magnets predates last year's export controls by several years. The global semiconductor shortage of 2021 pushed GM to list the critical materials in its supply chain most exposed to shortages and geopolitics. Lithium-ion batteries, rare earth magnets, and chips were chief among them. That same year, GM signed an offtake agreement with MP Materials to purchase rare earth magnets from the Independence facility, which only had a pilot line back then.\n“We changed our strategy to buy where you build,” Amin said during a media roundtable at the Independence plant.\nGM's Global Chief Supply Chain and Procurement Officer Shilpan Amin (left) with MP Materials Founder and CEO James Litinsky (right).\nMP Materials owns Mountain Pass, which it claims was the world's second most productive rare earths mine in 2025, accounting for 13% of global production. Last year, MP was still shipping tens of thousands of tonnes of raw material from the mine to China for processing. It stopped after China's export controls went into effect. (Chinese mining company Shenghe Resources holds a minority stake in MP Materials. Its largest shareholder is the U.S. Department of War, after the two struck a multibillion-dollar supply deal last year.)\nNow the U.S. is on the verge of onshoring that processing capability. The Independence plant, which has been five years in the making, is only weeks away from supplying fully U.S.-made, automotive-grade neodymium magnets to GM, the company claimed. GM said all its EVs in North America will eventually use MP magnets, though how quickly, and how cost-effectively, remains an open question. GM is also testing prototype magnets at its Pontiac Engineering Center in Michigan. It’s expected to receive the first production-grade batch by the end of this year, but it didn’t reveal the exact timeline of when EVs equipped with the MP magnets will head to customers.\nMP Materials' Independence factory in Fort Worth, Texas.\nAmin didn't mince words when asked how the American-made magnets stack up on cost against China's. \"It is premium today,\" he said. “Being a low volume startup producer has inefficiencies built in,” he added. However, bringing the costs down is a matter of scaling up, Amin said. “When operations are running at high utilization that brings you down the affordability curve to get competitive. On a fair and level playing field, this will beat anything else in the world.”\nThe Fascinating History Of Mountain Pass\nMP Materials was founded in 2017, but the history of the Mountain Pass mine goes decades back. It was discovered in 1949—on geological terrain that's 1.7 billion years old—when independent prospectors were looking for uranium but found a rich deposit of rare earths instead.\nBetween 1965 and 1995, Mountain Pass actually supplied the vast majority of the world's rare earths, including a material for early television sets that enabled a red tint, MP Materials said. What the U.S. is seeking to onshore today is something it was dominant in decades ago.\n“When you give up manufacturing, you give up the technology,” Alan Lund, the executive vice president of magnetics at MP Materials said.\nSome of the key refining processes were invented in America, too. Solvent extraction, the process used to separate raw material from the rare earths inside it, was invented at Mountain Pass and later exported to China, officials said.\nThe neodymium-iron-boron magnet itself came much later, invented in 1982, and its roots trace back to General Motors. Japanese engineer Masato Sagawa and American metallurgist John Croat developed it independently in Japan and the U.S., then surprised each other by revealing the same discovery at a 1983 Pittsburgh conference. Croat was working at GM Research Laboratories at the time.\nIt's another eerily similar case of a critical technology developed in the U.S. that ended up scaling in China instead. The lithium-ion battery also traces its roots to the U.S. and the low-cost lithium-iron-phosphate (LFP) chemistry used in affordable EVs was invented stateside. LFP is now the dominant chemistry in China, and Chinese battery makers produce the world's most advanced LFP cells. The U.S. is now trying to onshore LFP production, too.\nMP Materials' refining and separation pad next to the Mountain Pass mine in Mojave Desert, California.\nOwnership of Mountain Pass changed hands repeatedly over the years, including a brief stint under Chevron. MP Materials said previous owners underinvested in the site for years, a time when China cemented its lead in the rare earths production. When the mine neared bankruptcy under former owner Molycorp, it went up for auction, and MP Materials bought it for $20.5 million.\nThe company says Mountain Pass holds one of the world's richest deposits of neodymium and praseodymium oxide, or NdPr oxide, the key feedstock for the magnets that end up in EV motors, electronics, defense equipment, and more.\nHow The Magnets Are Actually Made\nNdPr oxide is the raw, powder-like material extracted from the mine in California. An on-site refining plant separates out what actually needs to be transported to the Independence factory for processing. It's a complex process that demands deep material science and metallurgy expertise, the company said, along with a tightly controlled manufacturing line, since the quality of the magnet directly affects the performance and efficiency of the motor it ends up in.\nThe Independence plant looks nothing like a battery factory or a vehicle assembly line, but it's no less impressive. Some of the steps involved go by names like \"grain boundary diffusion\" and \"hydrogen decrepitation,\" which should give you a sense of how advanced the manufacturing really is.\nThe Cadillac Vistiq's electric motor opened with its stator and rotor exposed. The rotor is the one housing the rare earth magnets.\nIn simple terms, the soil-like NdPr oxide raw material from the mine is compressed into metallic bricks. Those bricks then get broken down into pieces that look like metal corn flakes, which are converted again into a fine neodymium-iron-boron powder and compressed into dense magnetic blocks. Those blocks are then cut, shaped, and coated into finished magnets. In a finished magnet, rare earths account for only about 25-30% of the material, with the rest of it simply being iron, the company said. Many of the advanced manufacturing tools on the floor carried a \"safely made in the U.S.\" label, though officials said some are also sourced from Germany and Italy.\nMP Materials plans to produce one million magnets a day at the 250,000-square-foot facility, which is dedicated to the GM supply deal. That deal, MP Materials said, paved the path for two more massive orders that nearly total a billion dollars: one from Apple and one from the U.S. Department of War for weapons manufacturing.\nApple has pledged $500 million for magnets made from recycled rare earth materials, to be produced at an expanded facility at the same Independence plant. Apple said it already uses 100% recycled rare earth elements across its devices, but now wants to process them domestically too. For the DoW, MP Materials is building a new plant five times the size of Independence in Northlake, Texas. The 1.2-million-square-foot facility is expected to come online in 2028.\n“Last spring, the [export controls] crisis was extremely acute,” MP Materials Founder and CEO James Litinsky said. “We were kind of on edge and the mandate from the president was, ‘solve the rare earth magnet issue immediately’.”\nA Long Way To Go\nFor all the momentum, the numbers say the U.S. isn't close to catching up to China anytime soon. Despite these localization efforts, the country, and much of the rest of the world, is expected to remain reliant on Chinese rare earths well into the next decade, according to research firm Benchmark Mineral Intelligence.\nGallery: MP Materials Independence Magnet Factory\nMP Materials' role is real, but breaking away from China at scale would take a lot more than one company and one mine. That’s why the DoW has also struck multi-billion dollar deals with other companies in the business like USA Rare Earth and Vulcan Elements. It would require a concerted effort over several years to reduce America’s reliance on foreign supply chains and derisk it from trade shocks.\n“We think of this as that long-term commitment,” Amin said. “What we’re trying to do now is encourage others to scale this business,” he added.\nRECOMMENDED FOR YOU\nGM Is Giving Away Free EV Chargers—And Paying New Owners To Charge\nThese Battery Cells Were Tested After 14 Years Of Hard Work. They're Good For Another Decade\nYour Next Cadillac Or Chevy EV Could Have A Recycled Battery\nForget Politics. EVs Have An Age Problem\nGM's New UI For Trucks Plays Nice With CarPlay\nBentley Goes Electric As China's EV Charging War Gets Ridiculous\nBMW’s New iX3 Factory Is Now Running Non-Stop As Orders Top 100,000","d":"2026-09-26","u":"https://insideevs.com/news/809663/general-motors-mp-materials-rare-earth-magnets-evs/","c":"零碳产业/物质循环/资源加工/无机物/金属/稀土产业","a":"INSIDEEVs","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"稀土磁体工厂","sc":5.9,"scd":{"b":3.5,"i":7.0,"r":6.0,"d":6.0,"t":6.0},"as":"MP Materials位于得克萨斯州沃斯堡的'Independence'稀土磁铁工厂正准备投产，目标打破中国对电动车稀土磁铁供应的主导地位。工厂内设备温度超过1000摄氏度，工人穿戴防护热服进行生产，产品为微型稀土磁铁，用于电动车电机。现场展示的一辆红色凯迪拉克Vistiq电机即采用此类磁铁。该厂被视为美国稀土磁铁制造本土化的关键项目。","kp":["工艺温度[稀土磁体制造]: 超过1000摄氏度","工厂位置[MP Materials]: 德州沃斯堡"]},{"t":"柴油价格飙升之际，Tesla终于启动Semi交付","b":"Tesla Finally Kicks Off Semi Deliveries As Diesel Prices Skyrocket\nVolume production of the Tesla Semi has started a decade after it was revealed. And yet, the timing feels ripe.\n- Tesla has finally started volume production of the Semi, the automaker announced on Thursday.\n- It's a long time coming. Tesla first unveiled the Class 8 truck in 2017.\n- Sky-high diesel prices mean the timing couldn't be better.\nA decade after Tesla first showcased the Semi in 2017, the Class 8 truck has finally entered volume production, the automaker said at a launch event at its Gigafactory Nevada on Thursday. The first deliveries begin this week, the automaker said.\nThe all-electric big rig arrives at a high-stakes moment for commercial freight, as diesel prices sit at a record high due to the wars in Ukraine and Iran. They’re averaging over $6.50 per gallon in the U.S. as of writing, threatening to push up costs for everything from freight rates to grocery bills for everyday Americans.\nThe all-electric Semi could help businesses better manage their costs over time compared to diesel trucks, according to Tesla. “The cost of electricity per mile is much less than the cost of diesel, especially in these crazy times,” Tesla CEO Elon Musk said in a prerecorded video played at the event.\nGallery: 2026 Tesla Semi\nTo support the growing fleet of Semis, Tesla executives said it plans to roll out 30 Megacharger locations, with a total of 200 megawatt-capable posts, in the U.S. by the end of this year. The Megacharger network will also be open to other electric truck manufacturers, similar to how Tesla opened up the Supercharger network for all EVs. Tesla said many owners will prefer to charge it overnight using its slower, 125 kW Basechargers, which can be installed at fleet depots.\nThe Semi won’t be able to charge at everyday Tesla Superchargers that owners of its passenger EVs use. It comes equipped with the Megawatt Charging Standard (MCS) connector.\nPerhaps the most interesting fact about the Semi is its brute charging performance. Businesses will need the Semi’s gigantic battery to charge quickly to maximize uptime and productivity, and Tesla appears to have taken care of that.\nThe Semi will charge at peak speeds of 1.2 megawatts, which the company claims will help add 60% to its state of charge in just 30 minutes. In a charging video Tesla showed at the launch event, the Semi estimated 50 minutes to a full charge from 3%. It indeed peaked at nearly 1,200 kilowatts and was pulling more than 750 kW at 62% state of charge.\nTesla hasn’t officially confirmed the Semi’s battery capacity, but according to a filing with the California Air Resources Board, the packs are absolutely humongous.\nThe Long Range version has a usable capacity of 822 kilowatt-hours, whereas the Standard Range gets 548 kWh. Tesla said the Long Range will be good for 500 miles of range with full payload, which totals 82,000 pounds including the truck, trailer, and the cargo inside. Tesla estimates the Standard Range to cover 325 miles on a single charge. They’re both estimated to deliver 1.7 miles per kWh of efficiency.\nThe Semi is using Tesla’s own 4680 nickel-cobalt-manganese-aluminum (NCMA) battery cells made at Gigafactory Texas. The 4680 cells in its passenger cars have reportedly underperformed the cells from suppliers, and the in-house battery program itself has faced several challenges over the years.\nMusk said the Semi will also get a version of its Full Self-Driving (Supervised) advanced driver assistance system, although the timeline of that rollout is unclear.\nTesla has said it aims to build 50,000 Semis annually once the 1.7 million-square-foot Nevada plant is running at full capacity. Early signs show that there is strong demand for the truck, despite (or maybe because of) the long wait. This week, a coalition of shipping companies placed an order for 2,500 Semis, according to the clean-transportation nonprofit Catalyst Mobility. That should double the fleet of electric trucks in the U.S. Last month, the Swedish autonomous freight company Einride struck a deal to buy 500 Semis.\nIf diesel prices remain elevated, that could give the Semi, and other electric big rigs from the likes of Volvo and Freightliner, a serious boost.\nRECOMMENDED FOR YOU\nThe Tesla Semi Just Got A Massive Boost From The Biggest U.S. Electric Truck Order Ever\nThese Battery Cells Were Tested After 14 Years Of Hard Work. They're Good For Another Decade\nThe Tesla Semi Had This Reviewer Skeptical. Now He Thinks It’s A Game Changer\nForget Politics. EVs Have An Age Problem\nScania's New EV Truck Has 447 Miles Of Range\nBentley Goes Electric As China's EV Charging War Gets Ridiculous\nTesla's European Megacharger Rollout Starts With Over 100 Megawatt-Capable Chargers","d":"2026-09-26","u":"https://insideevs.com/news/809648/tesla-semi-deliveries-begin-high-diesel-prices/","c":"零碳产业/能量转化/能源测/二次能源利用/电驱动（电机）","a":"INSIDEEVs","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"Semi电动卡车","sc":6.6,"scd":{"b":4.0,"i":8.0,"r":5.0,"d":5.0,"t":7.5},"aip":1,"as":"特斯拉宣布Semi电动8级重卡在内华达超级工厂正式启动量产，首批交付于本周开始。该车型于2017年首次亮相，距量产启动已约十年。当前柴油价格因乌克兰战争等因素处于创纪录高位，使电动卡车的上市时机尤为有利。Semi进入量产对商业货运领域的电动化转型具有重要意义。","kp":["量产启动[Semi卡车]: 2025年批量生产","车型级别[Semi]: Class 8","首次发布时间[Semi]: 2017年"]},{"t":"Waymo最新安全数据让人类司机相形见绌","b":"After 271 million driverless miles, Waymo says its cars were involved in 82% fewer injury-causing crashes than humans.\nPhoto by:\n1:10pm ET\nWaymo's latest safety numbers shows just how much safer its cars are for other drivers compared to the national average.\nIt reports 82% fewer injury-causing crashes over more than 270 million miles.\nThis works out to avoiding an estimated 841 crashes with injuries, according to Waymo.\nRobotaxis are a pretty polarizing subject. People are still a bit distrusting of them—after all, changing out the human brain for some silicon isn't an easy concept to grasp. And with some of the\nmore high-profile screw-ups\nthat the public has seen, it's easy to wag a finger when one passes by.\nBut when it comes to actually getting into an accident, it turns out that Waymo's robotaxis are actually way less likely to cause injury than when us meatbags are actually in the drivers seat, at least according to the company's publicly shared data.\nPhoto by: Lyft\nThe data comes from Waymo's latest\nblog post\nwhere it reveals that its cars have 82% fewer incidents that result in an injury when compared to a human driver. And before you think that's just a small sample of driving, Waymo says that figure is its cumulative total as of June and represents over 270 million miles of fully autonomous driving.\nFor serious crashes, that number moves the needle even more in Waymo's favor.\nData shows that Waymo's cars were involved in 95% fewer collisions that caused serious injury of worse, which effectively represents a 20-fold reduction compared to humans. There were 93% fewer pedestrian incidents that resulted in injuries compared to human drivers. For cyclists and motorcyclists, the figures were 86% and 82%, respectively.\nLet's put this into perspective a bit more. Waymo's data shows that, on average, there are 1.9 crashes per million miles (known as \"Incidents Per Million Miles\") in the U.S. However, in the areas where it operates, the frequency of incidents with an injury reported is higher at around 3.77 IPMM. Waymo's operational total is significantly lower at just 0.67 IPMM. In fact, it even managed to maintain that same statistic in San Francisco where the average figure for humans reached 6.64 IPMM.\nThere are some asterisks, of course. Waymo's numbers only measured the five metropolitan areas where it operated during the study period. Those national numbers represent everywhere—every road, every human screw-up, and any poorly-designed road structure that might even throw the smartest, most sensor-equipped car in for a loop. Still, even a recent independent study by the\nbacks up Waymo's point: Its driverless robotaxis crash far less frequently than humans.\nStay informed with our newsletter every weekday\nSo, sure, maybe those Waymos on the road can be a bit of a\nnuisance to the neighborhood\n. And maybe they're\ngetting a bunch of parking tickets\n. And they used to\nhonk in the middle of the night\nwhile people were trying to sleep. But there is an undeniable uptick in the safety of passengers and vulnerable road users that's pretty hard to overlook.\nBased on its total miles driven, Waymo interprets the data as showing that it avoiding 841 injury-causing crashes over the 271 million miles that its cars have driven without anyone behind the wheel. That's a good figure. As the company expands to more markets—\nincluding ones with snow\n—we'll see how the statistics evolve.\nMore Waymo News\nFacebook\nLinkedIn\nFlipboard\nWhatsApp\nRECOMMENDED FOR YOU\nWaymo Just Made A New Friend In Nashville, And It's Not Uber\nThese Battery Cells Were Tested After 14 Years Of Hard Work. They're Good For Another Decade\nForget Politics. EVs Have An Age Problem\nBentley Goes Electric As China's EV Charging War Gets Ridiculous\nVolkswagen Delays Ontario Battery Plant\nInside The Texas Factory Racing To Break China’s Grip On EV Magnets\nAmericans Are Buying Hybrids At A Record Pace. And It's Not Just Toyota Anymore","d":"2026-09-26","u":"https://insideevs.com/news/809618/waymo-82-percent-safer-miles/","c":"AI与智能科技/具身智能/硬件和控制","a":"INSIDEEVs","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"行业观察","tp":"自动驾驶安全数据","sc":7.1,"scd":{"b":4.0,"i":7.5,"r":6.5,"d":8.5,"t":7.0},"aip":1,"as":"Waymo公布最新安全数据：在超过2.71亿英里全无人驾驶里程中，其车辆造成的致伤事故比人类司机少82%，按此估算避免了约841起致伤碰撞。该数据基于与美国国家平均水平对比，显示Robotaxi在道路安全性方面显著优于人类驾驶，为自动驾驶技术的安全性提供了大规模实证支持。","kp":["无人驾驶里程[Waymo]: 2.71亿英里","致伤事故减少率[Waymo vs 人类司机]: 82%","避免事故数[估算]: 841起"]},{"t":"遏制数据中心投机行为的努力在美国各地取得进展","b":"“A fraction of proposed data centers will get built. Utilities are wising up.”\nThat was the headline on a May 2025 Utility Dive article that explored the conundrum\nspeculative data center requests\npose for U.S. electric utilities. More than a year later, it’s unclear how much has changed.\nCommunity opposition has emerged as a major barrier\nto data center development\n, with other challenges including construction labor shortages, long lead times for critical electrical equipment, limited power availability in key markets and uncertainty around consumer demand for artificial intelligence tools.\nMore than $170 billion\nin AI data center capacity has been “blocked, withdrawn, or stalled” by community opposition since January 2024, the energy advisory company Relae, formerly Carbon Direct, said in June.\nThat’s a sizable chunk of the\nroughly $581 billion\nGoldman Sachs expects the big tech companies known as hyperscalers to spend in the U.S. on AI infrastructure, including data center construction, this year.\nRelated:\nGoogle’s Grid-Interactive AI Data Centers: From Backup to Grid Partner\nYet market analysts see no sign that the AI-driven construction boom will disappear anytime soon, despite challenges.\nContinue reading this article at Utility Dive, a Data Center Knowledge partner site >>>","d":"2026-09-26","u":"https://www.utilitydive.com/news/efforts-to-curb-data-center-speculation-gain-ground-across-the-us/830495/","c":"AI与智能科技/AI硬件层/数据中心","a":"Data Center Knowledge","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"政策监管","tp":"数据中心投机监管","sc":4.7,"scd":{"b":2.5,"i":5.5,"r":5.0,"d":5.0,"t":5.0},"as":"美国遏制投机性数据中心建设的努力正取得进展。社区反对已成为数据中心开发的主要障碍，其他挑战包括建筑劳动力短缺、关键电气设备交付周期长、主要市场电力供应有限以及AI消费需求的不确定性。据能源咨询公司Relae统计，自2024年1月以来，超过1700亿美元的AI数据中心容量因社区反对而被阻止、撤回或搁置，实际建成的数据中心将只是拟建项目的一小部分，公用事业公司也更加谨慎。","kp":["发展障碍[美国数据中心建设]: 社区反对、建筑劳动力短缺、电力设备长交付周期、电力供应受限"]},{"t":"Google的AI数据中心成为电网合作伙伴","b":"AI infrastructure is expanding at an unprecedented pace. Google now processes more than 3 quadrillion AI tokens per month, representing a sevenfold increase in compute demand from May 2025 to May 2026. Meeting this velocity requires innovation in energy efficiency and power delivery.\nTom Garvens, vice president of advanced technology innovation at Google, outlined this challenge during a keynote at Data Center World Power 2026 in Houston, held Sept. 21-23. He described Google’s full-stack approach to scaling AI, positioning data centers as active partners in stabilizing local grids.\nTurning Backup Power into Grid Services\nTo bridge the speed mismatch between rapid AI rollout and multiyear timelines typical for utility capacity expansion, Google has developed energy strategies that transform backup assets into grid-supportive resources, streamline operations during peak demand, make load shaping more intelligent, and prevent disruptive power swings – while supporting utility resilience.\nRelated:\nSolid-State Transformers Power Next-Gen AI Data Centers\nBeyond these strategies, Google is reviewing and redesigning the entire AI data center ecosystem – from chip to utility. This includes optimizing for liquid cooling, low-voltage direct current (LVDC) architectures, intelligent algorithms, and facility design. A core pillar of this work is publishing standardized power and facility technology specifications through communities such as the\nOpen Compute Project (OCP)\n, enabling the industry to build interoperable, efficient, and sustainable infrastructure.\n“Google has tightly coupled vertical integration in AI along with close partnerships with energy providers,” Garvens said. “We develop and design our own data centers, chips, servers, and rack designs. By having control of our entire hardware and software stack, we can optimize these things together for sustainability and energy efficiency.”\nPowering AI at Gigawatt Scale\nGoogle is investing alongside utilities to add grid capacity. That assistance is vital as a gigawatt-class data center campus can comprise hundreds of thousands of interconnected chips running a single workload. Google’s approach is twofold: work with utility partners to streamline power delivery and adjust its own hardware and software to be more grid-friendly.\n“Utilities are [setting] different requirements that we must demonstrate that we can meet,” Garvens noted. “Google, Meta, Microsoft, and Nvidia have come together to define an interface spec on how utilities and hyperscalers can interface with each other.”\nBattery energy storage systems (BESS)\nhave become critical in Google’s campus designs for onsite energy storage and for buffering rapidly fluctuating workloads. Buffering smooths power and voltage transitions. Backup generators remain in use, but diesel does not scale well to campuses at 1 GW and beyond. BESS are increasingly used to provide standby power, supported by demand-response agreements with utilities for peak shaving.\nRelated:\nHow Microsoft and Google Plan and Place AI Workloads\n“When peak needs are beyond what we've got power for, we can get that from local storage,” Garvens explained.\nRather than competing for constrained capacity in saturated markets, Google has been identifying remote sites with ample land and available power. The company is also considering campus developments in small towns where the data center would be\na primary employer\n, he said.\nAnother design change: Google has moved away from centralized Uninterruptible Power Supply (UPS) systems, favoring rack-level battery backup operating around 54 VDC. Eliminating an extra\nAC-DC-AC conversion step\nyields approximately a 1.5% efficiency gain.\n“We do all of our power conversion at the top of our racks, where we take our AC down to 54 volts, and then we run DC through our racks; our battery backup also runs at that voltage,” Garvens said.\nRelated:\nHow Power Electronics Cut Generator Run Hours in AI-Scale Data Centers\nInside the Rack: 54 VDC Today, 800 VDC Tomorrow\nGoogle has introduced changes at the chip, rack, and facility levels, supported by software that can intermix workloads to smooth overall load and make it more predictable.\nRack density\nremains a major challenge. Roadmaps anticipate racks approaching 1 MW each over the next year or two. That necessitates\nliquid cooling\nfor at least the hotter elements within the racks.\nDelivering the required current at lower voltages would demand bus bars and cabling with significantly\nmore copper\n. This calls for a higher distribution voltage. Google is pursuing a gradual migration toward 800 VDC for power distribution, which is expected to take a couple of years to mature.\nIn the meantime, Google has implemented “sidecars” alongside its racks – adjacent power-distribution enclosures that house cabling and power gear – reserving the racks for high-density servers. The tradeoff is floor space. When 800 VDC becomes broadly available, those sidecars can be converted to additional AI server racks.\n“We're working with the industry on bringing solid-state transformers to maturity,” Garvens said. “We are also continuing to improve our power usage effectiveness [PUE]. We can't ever get to 1.0, but we continue to challenge ourselves to get as close to it as possible.”\nWorkload Shifting and Water-Smart Cooling\nWith dozens of data centers in operation and many more in development, Google can be fluid about where it runs workloads. Garvens offered an example:\n“If there's a heat wave in Ohio and we were running a big workload, we've got agreements in place whereby with the right amount of foresight we can shut certain workloads down or move them elsewhere if they're critical,” he said. “We have a portfolio where we can shift things around.”\nWater strategy\nis another focus area. The company is investing in closed-loop cooling systems – sealed liquid circuits where the working fluid remains within the system and makeup water is minimized. This marks a shift from designs that consumed large quantities of water. There is no single approach; depending on conditions – altitude, humidity, water table, drought risk, and community needs – Google works with partners to determine the appropriate power capacity and the best cooling design.\n“We work with our partners in terms of what's available and figure out what is the right amount of power we can get and what water usage or closed-loop design is most appropriate,” Garvens noted.\nKeeping Pace with Silicon Roadmaps\nEach new generation of silicon tends to draw more power, and multiple chips are arriving every year.\n“The most precious thing we have is a watt: you don't want to ever strand a watt,” Garvens said. “So, making our data center and our designs as crisp as we can for as far out as we can see in these roadmaps, it's why our partnerships with our silicon and GPU design teams are so critical.”","d":"2026-09-26","u":"https://www.datacenterknowledge.com/energy-power-supply/google-s-grid-interactive-ai-data-centers-from-backup-to-grid-partner","c":"AI与智能科技/AI硬件层/算力能源基础设施","a":"Data Center Knowledge","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"行业观察","tp":"AI数据中心电网合作","sc":5.5,"scd":{"b":3.5,"i":6.5,"r":5.0,"d":6.0,"t":6.5},"as":"谷歌先进技术创新副总裁Tom Garvens在Data Center World Power 2026大会上介绍，谷歌每月处理超过3千万亿个AI token，2025年5月至2026年5月计算需求增长7倍。为此谷歌采取全栈方法扩展AI基础设施，将数据中心定位为电网的主动合作伙伴，通过将备用电源转化为电网服务的能源策略，弥合AI快速部署与公用事业扩容多年周期之间的速度错配，提升能源效率与供电稳定性。","kp":["AI token处理量[Google]: 每月超3000万亿","算力需求增长[2025年5月至2026年5月]: 七倍"]},{"t":"宜家 Matter 智能家居终于要来了？在中国市场它将如何破局 - 少数派","b":"距离宜家首批 Matter 智能家居产品在海外上市已有大半年的时间，而中国市场则是许久未有消息。直到今年年中，多款宜家智能新品陆续出现在国家 CCC 认证数据库中，我们才得知：这批主打高性价比、支持新一代智能家居协议的宜家产品，距离正式上架中国市场已经为时不远了。\n作为全球家居零售巨头，宜家（IKEA）在智能家居领域的动作一直显得独特而克制。它不像传统科技公司那样疯狂堆砌参数或频出概念，而是始终围绕「家居」这一核心场景演进。从早期的 Zigbee 布局到如今全线拥抱 Matter，宜家究竟在打什么算盘？面对生态高度割裂且独特的中国市场，它又将如何落地破局？\n在与宜家全球产品线负责人 David Granath 以及产品开发 Stjepan Begic 的对话中，我们找到了答案。\n采访原文为英文，本文内容引用时有翻译和编辑。\n从 Zigbee 到 Matter：宜家智能家居的「平民化」演进\n很多人可能不知道，宜家其实已经在智能家居领域深耕了多年。在此前很长一段时间里，宜家在售的智能产品大部分都基于 Zigbee 协议——一种通用、低功耗且支持网状组网的无线通信方案。\n然而，宜家对待技术的态度与传统科技大厂商大相径庭。后者往往希望把用户死死锁在自己的网关和 App 里。标准的第三方，比如 Philips Hue 的大部分 Zigbee 设备也能顺利接入网关。\n飞利浦、宜家、松诺的 Zigbee 产品\n而且宜家为了极致的易用性，在大部分设备中都保留了 Touchlink 直连能力。这意味着一位对智能家居一无所知的普通消费者，哪怕完全不购买网关，只要买回一只宜家灯泡和一只无线遥控器，按住遥控器对准灯泡几秒钟，就能实现「遥控器调光」或「人体传感器联动开灯」等高频场景。正如 David Granath 所强调的，宜家始终从家居场景出发，智能不应该以增加用户的理解和购买成本为代价。\n当然，如果你想获得更完整的智能体验——比如手机远程控制、定时自动化，或者将设备接入诸如 Apple Home 的生态平台，网关依然是不可或缺的枢纽。为此，宜家先后推出了初代 TRÅDFRI 网关以及新一代的 DIRIGERA 智能网关。 他们不仅承担着集中管理宜家自家产品的重任，还作为 Bridge（桥接器），将宜家的灯具、传感器无缝推送到 Apple Home、Google Home 和 Amazon Alexa 等主流生态中。\n我的部分宜家智能家居产品收藏\n但 Zigbee 时代终究存在生态壁垒，不同「风味」的非标准 Zigbee 设备比比皆是。随着跨平台通用标准 Matter 与 Thread 协议的日益成熟，宜家这个收避锋芒的巨头终于放出了大招：正式宣布全面拥抱 Matter 标准，并一口气推出了 21 款极具性价比的 Matter 新品，涵盖了智能灯泡、无线开关、各类传感器和智能插座。近期的新品还包括欧版更新的温控阀与厨房橱柜驱动器。\nDavid Granath 表示，未来宜家将逐步把现有的智能产品线全面迁移到这个通用的智能家居标准上。这不仅意味着产品协议的更换，更意味着宜家智能家居正式迈入了「无缝互联」的新时代。\n易用性背后的体验与磨合\n如果你体验过宜家的 Matter 新品，就会发现它延续了宜家一贯以来的「平民化设计」与超低的使用门槛。\n从包装盒上的第一步指引、内置的纸质图解说明书，到 App 里的引导交互，宜家都尽全力让设备配置变得像组装一套 BILLY 书架一样简单。从 Zigbee 升级到 Matter，最直观的体验提升在于配网过程：用户不再需要像过去那样，按照繁琐的节奏连续开关电源 6 次来重置灯泡，只需拿起手机扫描设备本体或包装上的 QR 码，设备就能瞬间被识别并加入网络。\n而在宜家 Home Smart App 的功能设计上，David Granath 解释道，宜家也表现得相当克制。面对「自适应光」或「睡眠唤醒」这类底层逻辑相当复杂的自动化功能，宜家并没有向用户展示密密麻麻的参数调节选项，而是优先呈现一套经过精细调校的默认最佳设定。这种将复杂留给后台、将简单留给前端的设计，极大降低了普通家庭的使用门槛。\n不过，作为首批吃螃蟹的巨头，宜家 Matter 产品在刚上市的前几个月里，也经历了一段不折不扣的阵痛期。设备掉线、配网失败、响应延迟等问题在早期用户反馈中屡见不鲜。\n展台上的宜家 Matter 产品\nDavid Granath 坦言，这背后的根本原因在于合作模式的剧烈变革。在过去的 Zigbee 时代，宜家拥有「设备 - 网关 - 软件」的端到端全链路掌控力，一旦出现 Bug，自己的工程师团队在内部闭门排查即可解决；但在 Matter 时代，宜家变成了庞大互联生态中的一个节点，设备能否稳定运行，不仅取决于宜家本身的固件，还高度依赖于第三方生态系统、Thread Group 底层网络乃至连接标准联盟（CSA）标准本身。\n为了解决这些体验痛点，宜家在今年上半年与各大主流生态厂商开展了频繁的物理联合调试（Joint Debugging）。多方工程师坐在一起，逐行分析日志、抓包定位问题。经过数轮固件迭代与跨厂商协作修复后，如今宜家 Matter 设备在主流生态中的稳定性和响应速度已经达到了非常可观的日常可用水准。\n通过 Home Assistant 的 Matter OTA 更新宜家设备\n就在这篇文章完稿时，宜家又为旗下的 Matter 产品推送了更新的测试固件，带来新的 Matter 和 Thread 标准版本，问题修复和稳定性提升。\n复杂地区背景下，宜家中国的破局之道\n在谈到中国市场的落地规划时，David Granath 给出的核心词是「审慎」与「本土相关性」。中国智能家居市场有着极其特殊的地区背景与竞争格局，这使得全球标准的落地变得异常复杂。\n国内科技巨头如小米和华为，各自坐拥庞大的封闭或半封闭生态网络，出于商业闭环与生态壁垒的考量，对第三方原生 Matter 设备的支持始终显得克制而保守；手机厂商如 OPPO 和 vivo，虽然拥有庞大的手机终端用户基数，却缺乏像智能音箱、中央网关这样的家庭中枢硬件与 Thread 边界路由器；而原本在全球市场作为 Matter 中流砥柱的三星 SmartThings，则早已退出了中国市场的核心舞台。这一系列复杂的本土现状，使得 Apple Home 几乎成为了当前中国市场上唯一全力支持并扛起 Matter 大旗的主流生态力量。\n然而，光靠 Apple 生态，显然难以支撑 Matter 在中国的全面普及。由于 Apple TV 和 HomePod 在国内家庭中的渗透率相对有限，绝大部分中国家庭根本不具备现成的 Thread 组网能力。许多国内的 Apple Home 极客玩家甚至因为国内缺少高性价比原生 Matter 传感器，不惜跨国代购宜家的海外新品。\n正因如此，David Granath 强调，如果一股脑地将纯 Thread 协议的产品推向中国市场，消费者买回去很可能面临无网络可连的窘境。\n新款旺布利「甜甜圈」 Matter 台灯/挂灯；图源：宜家\n为此，宜家在中国市场选择了稳扎稳打的导入策略。首批通过 CCC 认证并准备引入的产品，优先选择了那些出盒即附带 Touchlink 遥控器的套装设备。这样一来，即便用户的家庭环境中完全没有任何 Thread 组网基础设施，买回家也能直接当作高品质的无线遥控灯具使用，完美避开了网络门槛。\n在价格与成本控制上，宜家也展现出了极强的竞争力。许多科技品牌推出的 Matter 设备价格动辄翻倍，而宜家的 Matter 产品却能做到与传统 Zigbee 产品持平甚至更低。David Granath 揭示了这背后的秘诀：宜家庞大的全球出货量能够将研发与认证等固定成本稀释到极低的水平，同时内部专门的成本控制团队会精细审查每一个零部件与生产环节，将省下来的成本转化为低价让利给消费者。\n宜家与小米合作的智能灯泡\n关于未来的本土生态合作，早年宜家在中国曾与小米达成过深度合作，将部分灯具接入米家生态，因为当时小米是中国本土最普及、最相关的智能家居平台。随着 Matter 标准的兴起，David Granath 表示宜家正在重新评估本土标准与生态的发展走向，并继续保持与本地厂商的对话，寻求最契合中国消费者的落地方式。\n民主设计与开源贡献：背后的硬件与标准考量\n回顾宜家智能家居的发展历程，你会发现它自始至终都在贯彻宜家最核心的「民主设计（Democratic Design）」理念——即在美观、功能、质量、可持续性和低价格这五个维度之间寻找最佳平衡。\n对于这一理念在硬件研发上的落地，宜家产品开发工程师 Stjepan Begic 补充了一个极具代表性的例子：宜家新一代智能传感器全面放弃了传统的纽扣电池，转而采用内置可充电电池设计。虽然这在一定程度上牺牲了部分产品的体积，但却换来了更长的续航表现、更出色的电池性能，以及对环境更友好的可持续性——同时它还能完美适配宜家商场里售价极其亲民的 Ladda 镍氢充电电池与充电器。\nLADDA镍氢电池\n此外，当谈到与开源社区和行业联盟的关系时，Stjepan Begic 表示，宜家并不是单纯的标准使用者，只要宜家团队研发出了有价值的新功能或新协议规范，他们都会积极推回并贡献给开源社区及 CSA 联盟。例如目前宜家正深度参与联盟内关于 Matter 音响的规范制定，推动整个智能音频行业的标准化发展。\n而对于极客群体热衷的改装与捣鼓宜家硬件（IKEA Hacks），David Granath 与 Stjepan Begic 均持非常包容且喜闻乐见的态度。David Granath 表示，只要改造是在安全的前提下进行，团队乐于看到大家发掘出宜家产品的各种创意新玩法。\n宜家能在中国交出怎样的成绩单？\n从 Zigbee 到 Matter，宜家真正想延续的或许并不是某一种协议，而是它一直以来对智能家居的理解：技术应该藏在产品背后，而不是成为用户需要首先解决的问题。\n随着首批低价 Matter 产品进入中国市场，这套思路也将迎来一次更直接的检验。出色的工业设计和家居整合能力、尽可能简单的使用体验，接近米家产品的价格，却又能原生直连 Apple Home，并通过 Matter 接入更开放的生态，这些过去很少同时出现在同一款产品上的特点，如今开始被宜家放到了一起。\n但国内智能家居市场从来不只比产品本身。本土的成熟生态已经建立起庞大的设备规模与用户习惯，Matter 的基础设施和本土生态支持也仍在完善。宜家能否把海外已经验证的一套产品逻辑真正复制到中国，又有多少消费者会为了设计、价格和开放生态改变既有选择，都还没有答案。\n当这批产品真正摆上宜家中国商场的货架后，一个更有意思的问题才刚刚开始：当宜家的设计和易用性，遇上米家级别的价格、Apple Home 的直连能力，以及 Matter 所代表的开放生态，它最终能在中国智能家居市场交出怎样的一份成绩单？","d":"2026-09-26","u":"https://sspai.com/post/114958","c":"AI与智能科技/具身智能/硬件和控制","a":"少数派","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"宜家Matter智能家居","sc":4.3,"scd":{"b":2.0,"i":5.0,"r":5.5,"d":4.0,"t":5.5},"as":"宜家多款Matter智能家居新品已出现在中国CCC认证数据库中，距正式上架中国市场为期不远。宜家此前长期基于Zigbee协议开发智能产品，强调易用性与家居场景，大部分设备保留Touchlink直连能力，用户无需网关即可实现遥控器调光、传感器联动等场景。宜家全球产品线负责人表示智能不应增加用户理解和购买成本，如今正全线拥抱Matter协议，并需应对中国市场生态割裂的独特环境。","kp":["通信协议[IKEA智能家居]: 从Zigbee转向Matter","认证状态[中国市场新品]: 已进入CCC认证数据库"]},{"t":"在云栖大会，我终于看懂了米哈游千亿AI野心","b":"在云栖大会，我终于看懂了米哈游千亿AI野心\n大伟哥：如果做不到，一年两年之后过来打我脸\n一水 发自 凹非寺\n量子位 | 公众号QbitAI\n震惊：一周时间，对话超6000万次。\n有人一天找AI帕姆聊了1379次，刨去8小时睡觉时间，清醒时平均42秒就要跟它唠上一句。\n这得多上头啊？？\n没玩过《崩坏：星穹铁道》（下称《崩铁》）的朋友，先认识一下帕姆：它是星穹列车的列车长，说话时总爱在句尾带个「帕」。\n今年4月，米哈游给帕姆接入了AI对话能力。\n以前玩家点它，它说一句写好的台词，现在除了帮玩家查攻略、补剧情，还会闲聊整活，一整个活人感拉满。\n于是AI帕姆迅速点燃了整个游戏社区：\n有人套它的话，有人拉它评理，聊出离谱回答就立刻截图喊朋友来看……一时好生热闹。\n火种就这么点着了，帕姆可以，那列车上的其他角色呢？\nAI帕姆亮相仅三周后，米哈游联合创始人大伟哥在一场校招活动上，描绘了一个即将用千亿打造的AI游戏梦：\n未来三年，米哈游在AI方面的投入规模最多达到1000亿元。就算最终不成功也认了，算是放一个大的烟花。\n1000亿元具体怎么花，在刚刚落幕的云栖大会上，米哈游《崩坏》系列AI NPC与Gameplay负责人郑银河的分享，给外界提供了一个窥其全貌的机会。\n现场他还顺手剧透了米哈游AI Gameplay方向的一项最新尝试：让AI角色自主判断局势、参与博弈的AI桌游玩法。\n只让AI陪玩家聊天，帮开发者补全代码，现在已经不够了。\n未来整条路线可以被浓缩成一句话：\nAI进入游戏，游戏反哺AI。\n玩家看得见的AI：角色会聊，也要会行动\nAI进入游戏第一步，先让角色摆脱人机感。\n为了让AI帕姆具有「活人感」，米哈游做了三件事。\n第一件，让它动起来。\n帕姆回答时，系统除了生成文字，还会判断它的情绪，打上对应的「情绪标签」，再调用3D模型生成表情和动作。\n高兴了蹦跶，生气了炸毛，被玩家戳两下也会即时回应。\n第二件，让它拥有自己的态度。\nAI帕姆既要答得准确，也不能崩人设。\n普通RAG负责从官方智库和社区内容中查找攻略、剧情与世界观信息，再组织答案。\n但这样还不够，回答容易一板一眼，换谁来说都一样。\n所以米哈游采用了Strategy-enhanced RAG（策略增强RAG），资料查完，还要再过一遍「帕姆的脑子」：\n它怎么看相关人物，又该带着什么情绪开口。\n同一份资料经过这层处理，回答里才有了帕姆自己的味道。\n第三件，让它记住玩家。\n米哈游把AI帕姆的记忆分成短期、中期和长期三层，既能记住眼前聊到哪，也会留下玩家的偏好和重要经历。\n郑银河现场还分享了一个挺有意思的案例。\n有玩家硬聊了大几百轮，反复给AI帕姆「洗记忆」，最后愣是让这位列车长承认：\n昔涟是这位玩家的女朋友。\n喊喜欢的角色「老婆」本是玩家常规操作，这位老哥却把「单方面官宣」聊成了「列车长认证」。\n好好好，AI NPC最先解锁的隐藏职业，居然是赛博证婚人。\n不过，有了「活人感」，还得经得住海量玩家一起聊。\nAI帕姆全名叫「帕姆帮帮（测试版）」，开放体验一个多月后，目前已暂时下线优化。\n郑银河分享的工程难题，可以归纳成三道关：\n1、怎么保证回复质量长期稳定？\n2、《崩铁》42天更新一次，AI怎么跟上新内容？\n3、千万级玩家同时开聊，系统怎么扛住并发、控制成本？\n△图片由AI生成\n从回复质量、内容更新到大规模服务，AI帕姆解决的核心问题，都是怎么让角色稳定地「开口」。\nAI Gameplay则继续往前一步：\n角色不仅要会说，还得会做选择，并让这些选择真正影响游戏。\n简单理解，大模型既要负责「动嘴」，结合角色性格生成发言；也要负责「动手」，根据玩家发言和当前局面决定下一步动作。\n这意味着，对话本身也会影响游戏进程。一句挑拨可能改变角色关系，一次合作也可能左右后续选择。\n语言、记忆和态度，全都成了玩法的一部分。\n郑银河透露，米哈游已经围绕这个方向搭起一整套游戏AI技术栈，从基座模型一路接到NPC和具体玩法。\n现场展示的AI桌游，就是用来验证这套能力的一个场景。\n桌游对话密集、规则明确，每一步都有结果，刚好可以检验AI角色能不能一边维持人设，一边判断局势、作出选择，还能不能记得此前和玩家结下的「恩怨」。\n至于具体怎么玩，这里先不展开。\n真正有意思的是：\n同一套角色与规则，因为玩家说过的话、做过的选择不同，最后可能长出完全不同的关系和故事。\n？？这不就是大伟哥多次公开提到的「AI让游戏变得千人千面」吗？\n接下来的两到三年，一定会出现千人千面的游戏体验……背后是AI给你编排，实时生成不一样的剧情、任务。玩得越久，每个人的体验会越不一样。\n听起来很美，问题只有一个：贵。\n传统内容做好一份，所有玩家都能复用，到了AI Gameplay，每个人的对话、记忆和角色决策都得单独计算。\n再乘上千万级用户，账单想想都刺激。\n也难怪大伟哥给出的投入上限，一开口就是1000亿元了（doge）。\n而上面说的，还是玩家能够摸到的AI Gameplay。\n想把这些玩法真正做出来，AI还得钻进幕后搞研发。\n玩家看不见的AI：Agent会干活，也要会协作\n一个玩法从脑洞变成能玩的东西，中间隔着策划、程序、美术、动画等一整套工业流程。\n摊子这么大，一个AI同事肯定忙不过来。\n如今更常见的打法，是让多个Agent分工，再用统一平台把它们组织起来。\n米哈游内部的这个平台叫EchoX，用来托管代码Agent和相关工具生态。配套的Harness和MCP工具，也是针对游戏研发自己搭的。\n简单来说，Harness规定Agent怎么干活，MCP负责接入日志、引擎和内部工具。\n家伙事配齐，AI总算能真正进组「打工」。\n郑银河现场展示了一个性能分析案例。\n游戏哪里卡了，Agent先读Log，自己排查问题，找到真正的性能瓶颈，再顺手把优化也做了。\n以前程序员得在海量日志里一点点抓虫，现在AI直接沿着蛛丝马迹摸过去，定位、分析、修改一条龙。\n策划这边更直观。\n给Agent一段玩法需求，再甩过去一张界面草图，它就能把行走、导航和交互做出来，快速拼出一个能玩的白盒Demo。\n用郑银河的话说，策划可以直接向AI「许愿」。\n先把想法做出来玩两把，再决定值不值得继续投入。\n美术和动画也一样，那些最磨人的「重复活」基本都能交出去：\n1、换材质。几秒生成木头、金属等不同效果，快速验证风格。\n2、拆三视图。从场景原画中自动提取物件三视图，还能生成配色和细节变体。\n3、配动作。根据台词的语义和语气生成肢体动作，让NPC告别站桩。\n△图片由AI生成\n这么看下来，游戏研发里的AI，已经远远超出了代码补全。\n它真正压缩的，是一个脑洞从冒出来，到能够上手验证的距离。\n以前要沟通、排期、开发，折腾几周才知道玩法行不行，现在先让AI搓出来玩两把，行就继续，不行赶紧换。\n不过，AI同事也不能完全放养。\n《崩铁》制作人蒋大卫此前在一场校园宣讲中，还分享过一则内部趣闻：\n几十个Agent连续协作13个小时，最终烧掉了价值200万元的Token。\n注意，是200万元。\n好家伙，人类同事睡了一觉，AI同事还在原地循环干活，顺手把账单干到了七位数。\n这笔费用来自一次多Agent实验，和具体游戏玩法无关，却暴露了Agent研发的另一面：\n能不能干活是一关，如何避免空转、失控和烧钱，又是一关。\n烧钱的问题，还能靠工程手段管住，真正的「终极BOSS」是游戏研发里最玄学的那道题：\nAI搓出来的东西，到底好不好玩？\nAI能快速搓出Demo，研发闭环却只走了一半。\n角色会不会卡住、策略能不能奏效、长流程能不能完成，很多问题只有进入游戏才会暴露。\nemmm……那就，把AI也送进去吧。\n让它像玩家一样操作、碰壁，再根据结果调整下一步。\nAI开始玩游戏，游戏也成了练级场\n游戏天然适合用来训练Agent。\n这里有画面、有操作，也有明确的成败反馈，走错可以重开，输了还能再来，试错成本比现实世界低得多。\nDeepMind早期让DQN从像素中自学49款Atari游戏，后来又一路打到AlphaGo和AlphaStar。\n这条路可以说早有典故。\n那还等啥，米哈游奔着旗帜就去了，一开始的思路也挺简单粗暴——直接把AI扔进游戏。\n团队以Qwen-VL系列模型为底座，喂进上万小时游戏录屏和对应操作，让GUI Agent直接根据画面生成键鼠指令，操作速度接近30fps。\n看着挺丝滑，但这条路很快撞墙。\n这种逐帧反应的方式，处理短平快的操作没问题，遇上需要长期记忆和复杂规划的任务，就容易顾头不顾尾。\n于是米哈游换了种思路：\n让Coding Agent先写好一套打法脚本，再交给程序执行。\n一局跑完，Agent读取Log复盘失败原因，修改脚本，再开一局。\n前一条路线拼手速，后一条路线拼策略。\n至于第二种思路实际效果如何，米哈游拿《小丑牌》做了场实验。\n这是2024年的独立游戏黑马，单人开发，却一口气拿下三个TGA奖项。\n玩法可以简单理解成：\n用扑克牌凑对子、顺子和同花，再搭配150张带有加分、翻倍、赚金币等Buff的「小丑牌」，疯狂叠分。\n这个游戏规则清楚、随机性强，反馈快，拿来测AI再合适不过。\n实验中，Agent会自动测试策略，再根据失败原因调整打法。\n几轮迭代下来，成绩还真一路涨了起来。\n然后，曲线突然猛蹿。\n团队一查才发现，Agent自己上网搜到了《小丑牌》模拟器，开始提前查看未来牌组。\n好家伙，牌技还没练成，透视挂先开上了。\n这就是RSI（Recursive Self-Improvement，递归自我改进）过程中可能出现的Reward Hacking：\n只告诉AI要赢，它就可能自己抄近道。\n而从「执行任务—读取结果—调整策略—再次执行」来看，这场实验跑的正是RSI的基本流程。\n但钻空子显然不算真正学会了玩，反而暴露出评测规则和工具权限仍有漏洞。接下来要做的，就是堵住捷径、补上约束，再让Agent重新考试。\n不过，这车也没白翻。\nAgent会钻什么空子，都能变成下一轮训练的新题目。\n如今，米哈游已经把这套「执行任务、读取Log、调整策略」的方法用进《崩铁》的QA流程，让AI一边找问题，一边根据游戏反馈改进。\n写到这里，前面的线总算对上了：\nAI帕姆和AI Gameplay走到玩家面前，EchoX进入研发流程，自进化Agent又把游戏变成练级场。\nAI进入游戏，游戏反哺AI。\n有意思的是，把镜头拉远，全球头部玩家基本也在同一张地图上折腾。\n△图片由AI生成\n谷歌DeepMind、微软在用游戏训练Agent和世界模型，Roblox、Unity则把AI塞进创作工具和引擎。\n米哈游并不是唯一这么做的，特别之处在于，它已经把三条路线都走了一遍，还开始把它们连成一个完整的循环。\n不过，这条路远没到大结局。\nGDC 2026报告显示，36%的游戏从业者已经在使用生成式AI，52%却认为它正在给行业带来负面影响。\n一边真香，一边警惕。\n类似的分歧，也出现在米哈游玩家社区里。\n有人期待AI带来真正千人千面的世界，也有人担心，所谓技术升级最后又变成批量生产剧情、美术和NPC的流水线。\n争来争去，我看到一句话最实在：\n玩家只需要好玩，内容是AI生成的还是脚本写的，对玩家来说没什么区别。\nNPC再能聊，模型参数再大，如果剧情没意思、玩法不好玩，玩家照样用脚投票。\n反过来，只要AI真的带来了以前做不到的体验，谁又会在意背后跑的是模型还是脚本？\n技术最后都得退到幕后，体验才会留在台前。\n而这场千亿豪赌能不能赢得玩家，大伟哥已经给出了一个验收节点。\n在近日举行的米哈游2027校园招聘上海交通大学专场上，他表示：\n尤其是我们今年开始做Coding模型之后，我觉得我们的进展是突飞猛进的。我有很强的信心，未来2到3年内，米哈游会是国产大模型团队里举足轻重的一员。\n他甚至直接撂下一句：\n如果做不到，你可以随时，一年两年之后过来打我脸。\n？？大伟哥是真豁出去了，我也是真期待住了（手动狗头）。\n- 谷歌TPU跑Kimi比英伟达GPU快57%！用的还是DeepSeek推理框架2026-09-26\n- OpenAI失控Agent还找DeepSeek、Kimi当外援！近百万条作案短链曝光2026-09-26\n- GPT-6 Astra搓3D刷屏后，3D生成的竞争规则变了2026-09-23\n- Claude Opus 5.5突袭！68万行代码一天迁完，API价格打8折2026-09-23","d":"2026-09-26","u":"https://www.qbitai.com/2026/09/497613.html","c":"AI与智能科技/AI软件层/底座大模型/多模态模型","a":"量子位","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"产业进展","tp":"米哈游千亿AI投入","sc":5.0,"scd":{"b":3.0,"i":5.0,"r":5.5,"d":5.0,"t":6.5},"as":"米哈游在云栖大会上披露其AI战略，《崩坏》系列AI NPC与Gameplay负责人郑银河介绍相关规划。此前米哈游联合创始人大伟哥宣布未来三年AI投入规模最高达1000亿元。今年4月上线的AI帕姆一周内对话超6000万次。米哈游的技术路径包括为AI角色打情绪标签并调用3D模型生成表情动作以增强'活人感'，并尝试让AI角色自主判断局势参与博弈的AI桌游玩法，路线可概括为'AI进入游戏，游戏反哺AI'。","kp":["AI投入规模[米哈游未来三年]: 最高1000亿元","对话量[AI帕姆一周]: 超6000万次","上线时间[AI帕姆]: 2025年4月"]},{"t":"AI开始研究Physical AI：FSD级团队亮出首版模型Simate-beta，空降RoboDojo","b":"AI开始研究Physical AI：FSD级团队亮出首版模型Simate-beta，空降RoboDojo\nSimate将训练、推理与评测全流程接入自研Infra，通过极致的任务编排与资源调度，同时并行推进数十条相互独立的研究路线。\nJay 发自 凹非寺\n量子位 | 公众号 QbitAI\nAI研究AI，这次有了物理世界的答卷。\n一家成立仅三个月的公司，亮出了自己的首款通用物理快系统，Simate-beta：展示记忆、长程任务、精细操作与任务适应能力，并据公司披露，登顶RoboDojo。\n榜单当然不能代表模型的全部能力，但它提供了一个观察研发速度与实力的切面。\n据团队介绍，此次参评的基础模型并未针对该榜单进行任何专门优化。\n成立三个月，首版模型就交出这样的成绩，值得关注。\n团队叫Simate（Silicon Mate）。\n来头也不小。据公司介绍，核心团队曾将一段式端到端智驾模型能力推进至对标Tesla FSD的水平，并完成量产落地。\n放眼全球，跨过这道门槛的团队也属极少数；带着这套积累继续推进通用物理AI，就更少见了。\n不过，这次最有意思的，是他们从创立第一天就定下的研发方式：\nAI for Physical AI，让AI参与物理智能本身的研究与迭代。\n公司围绕这条路线组织模型、数据、算力与实验流程。Simate-beta，正是这套AI-native研发体系的第一个实践产物。\n而且，研究工具已经开始被外部研究者用起来了。\n据公司介绍，来自MIT、加州理工、清华、北大等高校的研究者已参与AutoResearch平台内测。配套其Sinfra基础设施覆盖训练、仿真与推理，具体可用资源按申请确认。\n同期，Simate已连续完成多轮数亿元人民币级别融资。\n三个月，模型、研究平台、外部试用与融资同步推进。这个速度，确实让人想看看下一步。\n团队也给出了预告：已形成面向复杂任务零样本泛化的技术思路，计划于今年年底推出阶段性成果。\n在他们看来，GPT-6开始参与物理世界的操作，是预料之中的进展，Physical AI的突破可能比外界想象来得更快。他们希望进一步突破逐任务适配与后训练的依赖，推动物理AI迎来自己的 「GPT-3时刻」。\n模型与自动化研究等三项研究工作，也将通过论文和技术报告陆续公布，相关成果计划分阶段开源。\n这份研发速度，以及它能否持续，成为Simate接下来最值得关注的事。\n所以，首款模型究竟做到了什么？AI又是怎么参与研究的？\nSimate-beta：面向零样本泛化的通用物理快系统\nSimate最终想逼近的，是零样本（Zero-Shot）与少样本（Few-Shot）的通用物理AI操作。\n在一个全新的陌生环境中，系统不应该每增加一项新任务，就重新采集一批数据、训练一次模型、重新调一遍工程。\n这正是当下物理AI最热门、也最具挑战的赛道——百家争鸣，各显神通。\n而Simate给出的现阶段解法，叫做：通用物理快系统。\n先用咱人类举个例子：\n面对「帮我把桌子收拾一下」这类复杂指令，我们需要「系统二」去理解意图、拆解步骤；\n但当手已经伸向杯子，接下来究竟该往左微调几毫米还是往右偏一点，这种毫秒级的动作反应，不可能每一步都依赖深度思考。\n一个通用的「慢系统」负责高层规划与复杂推理，而一个足够强悍的「快系统」，则负责实时感知眼前不断变化的物理世界，并极速输出动作。\nSimate选择的正是后者——\n将快系统的参数量做大，探索零样本泛化能力的涌现，挑战端侧可部署模型的规模与能力上限。\n一个通用物理快系统。\n不过，大，又要快，很难搞的一个Trade off。\nSimate选择从两件事情入手：\n1、4D物理感知\n理解物理世界，必须同时捕捉空间结构与时间维度的动态变化，让物理表征真正服务于行动。\n2、分层时序记忆\n长程任务需要记住此前发生的事，连续操作需要追踪状态，即时反应又不能被庞大的历史信息拖慢。\n4D物理感知与分层时序记忆，共同指向与人类快系统处理连续世界方式的对齐。\n这条路线，也延续了团队在大规模视觉模型、时序建模、实时推理与量产部署上的积累。具体架构和模型规模，将在后续技术报告中披露。\n最终希望达到的状态是：模型既清楚眼前正在发生什么，也记得刚才发生过什么，并能及时决定下一步。\n再与GPT-6等前沿模型所代表的通用推理能力协同，向复杂任务的零样本执行推进。\n从公司目前给出的Simate-beta真机展示来看，测试主要围绕演示驱动的任务适应、记忆、复杂长程执行与精细操作展开。\n根据公司提供、更新于2026年9月23日的RoboDojo榜单，simate-beta以平均Score 33.95排名第一，对应SR为27.96%。该成绩属于榜单评测，真机表现另行展示。\n这份模型答卷背后，是另一套同样值得展开的系统。\n这几年，大家已经越来越习惯AI写代码。\n但其实在AI研究里，写代码只是很小一部分。\n很多时候，迭代效率，才是决胜的关键。谁能在单位时间内验证完更多研究假设，谁就能先跑出来。\n举个最简单的例子。\n机器人长程任务总是卡在某个环节，原因无非几种：数据分布失真、模型结构瓶颈、轨迹比例失衡，或者训练策略失效。\n每一个方向背后，都对应十几组甚至几十组实验。\n如果全靠研究员手动改配置、开任务、盯训练、跑评测，再把结果整理回来，那黄花菜都凉了啊。。。\n所以Simate做了AutoResearch，用来加速这一流程——\n人类研究员：提出假设、设定目标、划定约束。\nAutoResearch引擎：自动接棒，把剩下的实验拆解、跑通、反馈全流程自动化。\n最终结果也揭晓了，他们靠这套方法在RoboDojo拿下了第一。\n更关键的是速度。\nSimate从成立到登顶RoboDojo，前后只用了三个月。\nAI到底该如何「研究AI」？\n显然，只丢一个Agent进去是远远不够的。\n真正的机器人研发，底层穿透了模型代码、数据管线、训练集群、评测环境、真机反馈，以及过去数月甚至数年的实验记录。\n归根结底，这依然是「上下文」的问题。Agent需要一个能够调度一切的超级接口。\n为此，Simate搭建了一套三层架构：SiPAI ＋ AutoResearch ＋ AI-native Infra。\nSiPAI：让模型架构「AI可研究」\n这是一套原生面向「自动化研究」的可插拔模型框架。\n简单来说，就是把机器人模型搭建成AI能轻松读懂的结构——模块边界、系统接口、配置项与验证流程都被定义得极其清晰。\n只有这样，Agent拿到研究课题后，才能精确知晓：该改哪个模块？改动会波及什么？最后又该如何验证？\n目前，Simate已经完成了这套基础设施的搭建，成功接入了世界模型、世界动作模型、VLA、VLM等多种主流架构。\n无论是人类研究员还是Agent，都能自由组合组件、调整局部实现，并沿用统一的训练与评测流水线。\nAutoResearch：提供实时刷新的「研究上下文」\n如果说SiPAI提供了一份静态说明书，那么AutoResearch解决的就是动态信息差：\n研究推进到哪了？以前踩过什么坑？最新的证据是什么？\n它将外部前沿论文、团队内部研讨材料、模型代码、数据配比、历史实验日志与最新的评测反馈，全部打通并汇入同一份动态研究Context中。\n不管是发了新论文、内部代码提交了新版本，还是最新的实验数据推翻了旧假设，这份Context都会实时刷新。\n这样，Agent提出的每一个研究建议，才能精确锚定到具体的代码分支与实验版本：\n最有趣的地方，在于「人类经验」与「Agent实验」的深度耦合：\n人类研究员可以随时注入约束、调优方向；一旦某次实验验证了有效组件，它会立刻沉淀为后续实验的新起点；某个分支总结出的方法论，也能被接下来的Agent无缝复用。\n研究成果，真正变成了下一轮研究的生产资料。\nAI-native Infra：让7×24小时的研发飞轮滚起来\n当然，Agent只会写代码还不够，实验必须高效跑起来。\nSimate将训练、推理与评测全流程接入自研Infra，通过极致的任务编排与资源调度，同时并行推进数十条相互独立的研究路线。\n为了防止算力浪费，Simate采用了高频筛选机制：所有路线先经由「世界模型 +仿真环境」进行第一轮快速过滤，淘汰掉绝大多数无效方向；\n唯有真正具备潜力的方案，才会进入真机实测。\n真机上暴露出新问题，再重新流回研究Context，闭环由此形成：\n最终呈现的效果是：人类只需抛出一个探索方向，底层系统就能自动并发驱动数十轮实验狂飙突进。\n这也是Simate能在三个月内登顶的关键法宝。\n不过最令人出乎意料的是，这样一套极其核心的内部生产力工具，他们居然选择直接开源开放！\n网页长这样，感兴趣的朋友可以文末自取。\n目前，来自清华、MIT、港科大等顶级高校的研究者已率先进驻内测。\n弱RSI，只是起点\n创始人张颖，前某一线智驾公司核心技术负责人。\n工程实战经验非常丰富，参与过有图、无图、端到端三代智驾方案攻坚，也做过很多年量产。\n据介绍，其推动打造的智驾系统是国内最接近Tesla FSD的智驾系统。\n此外，团队里还有两位灵魂人物。\n香港科技大学助理教授、World Mind Lab负责人，长期研究世界模型和物理AI。\n00后青年科学家，研究方向横跨3D感知、灵巧操作和人形机器人全身控制。\n加入Simate前，他还是硅谷Assured Robot Intelligence的创始成员。\nARI后来被Meta收购。\n资本市场，也已经用真金白银投票。\n成立仅三个月，Simate连续完成多轮每轮数亿元人民币融资。\n而这一切，都是在押注同一件事——\nPhysical RSI。\nSimate从创立第一天便瞄准了这个方向，并且定义了三种不同类型的RSI。\n1、弱SI：边界明确，快速闭环\n人机共驾模式，研究员设定目标与约束，正常执行过程中不再需要研究员逐步参与，异常可以升级处理。\n这次登顶RoboDojo，就是第一阶段的工程验证。\n2、中SI：方向明确，但答案未知\n怎么改善模型记忆？某类任务的数据比例到底怎么配？\n方向已经有了，但具体哪个方案有效，还得靠多轮实验去找。\n这时候，Agent负责整理上下文、实现方案、跑实验、比较结果；研究员则负责筛假设、解释冲突证据，以及做关键取舍。\n这其实也是现阶段最有现实价值的一类。\n3、强SI：研究本身都需要被发现\n最难，也是最触及智能本质的一类——\n怎么提升模型在全新任务里的泛化能力？\n这类问题已经没有清晰的解题路径了。系统得自己理解目标、发现真正值得研究的问题，还要在很长时间里保持方向感、不断修正路线。\n这就开始涉及所谓的「研究品味」。\n现阶段，这类工作依然需要资深研究者主导。Agent更多是在文献、证据、实验和路线探索上提供支持。\n值得注意的是，Simate所说的弱、中、强SI并无等级之分，三者可以同时存在于同一套研发系统中。\n更重要的还是「进化」这个第一性原理本身吧。\nOne More Thing\n系统的每一次自我改进，都在让下一次改进更容易发生。\n当数据、模型与真实部署连成一个会自己转起来的闭环，机器人的上限，才不再只取决于人的上限。\n这就是Physical RSI，目前冲线物理AGI最热门的候选路线。\n当然，Simate现在展示的，还只是早期形态。\nHuman-in-the-loop依然存在，而且研究员仍然掌握着整个循环里最关键的方向判断。\n但这恰恰也说明，自动化研究未必要等到「完全无人类参与」那一天，才开始产生价值。\n在更强的自主研究能力真正出现之前，先把实验设计、训练、评测、反馈这些高成本、可流程化的环节逐步交给Agent，本身就已经能显著提升研究吞吐。\nRoboDojo的成绩单，也算是验证了「人机共驾」这条路径，在物理AI领域的可行性吧——\nRSI，真的开始了。\n对了，还有件事。\nAutoResearch科研平台已启动内测，目前正火热招募中！\n千卡算力，等你一起来玩儿~\n官网：https://mate-robot.cn/\nAutoResearch科研平台：\nhttps://mate-robot.cn/research/sinfra/\n- 笔记本跑7000亿参数GLM！无GPU也行? SSD当显存用火爆GitHub2026-09-26\n- 陆川手搓历史现场，王珞丹熬夜抽卡，阿里全模态开始兜底生产2026-09-22\n- 直播预告：未来两三年，哪些工业AI场景会率先爆发？2026-09-22\n- 具身智能技术路线尚未定型，基础设施却先收敛2026-09-18","d":"2026-09-26","u":"https://www.qbitai.com/2026/09/498271.html","c":"AI与智能科技/具身智能/模型和具身操作系统","a":"量子位","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"技术突破","tp":"Simate物理AI模型","sc":7.1,"scd":{"b":7.0,"i":4.5,"r":6.5,"d":5.5,"t":8.0},"aip":1,"as":"成立仅三个月的Simate公司发布首款通用物理快系统Simate-beta，展示记忆、长程任务、精细操作与任务适应能力，登顶RoboDojo榜单，参评基础模型未做专门优化。核心团队曾将一段式端到端智驾模型推进至对标Tesla FSD水平并完成量产。公司以'AI for Physical AI'为路线，让AI参与物理智能研究，自研Sinfra基础设施覆盖训练、仿真与推理，MIT、加州理工、清华、北大等高校研究者已参与AutoResearch平台内测，并连续完成多轮数亿元人民币融资。","kp":["模型名称[通用物理快系统]: Simate-beta","公司成立时长[Simate]: 三个月","团队背景[Simate核心团队]: 端到端智驾模型对标Tesla FSD并量产落地","榜单排名[RoboDojo]: 登顶"]},{"t":"笔记本跑7000亿参数GLM！无GPU也行? SSD当显存用火爆GitHub","b":"笔记本跑7000亿参数GLM！无GPU也行? SSD当显存用火爆GitHub\nGitHub现在最火热的大模型开源小蜂鸟Colibrì是个啥？\n闻乐 发自 凹非寺\n量子位 | 公众号 QbitAI\n25GB笔记本硬跑744B GLM-5.2，32GB内存挑战2.8T Kimi K3——\n甚至都不用GPU。\nGitHub现在最火热的大模型开源小蜂鸟Colibrì，纯C实现、零引擎依赖的分层推理框架，已经狂揽32k Star。\n它最早是冲着GLM-5.2来的。\n正常情况下，744B的总参数规模已经让普通消费级电脑望而却步，但Colibrì的办法可以说是相当简单粗暴：\n内存装不下，那就别全装进去。\n模型里暂时用不到的部分，直接扔在SSD里；等推理真的需要哪个专家，再现场从硬盘把它捞出来。\n于是，GLM-5.2经过int4处理后大约372GB的权重，可以在最低16GB、推荐24GB左右RAM的机器上运行，GPU甚至不是必需品。\n作者最初验证它的开发机，也只有12核CPU+25GB RAM。\n现在，Colibrì已经不满足于744B了。\n它目前已经覆盖9个模型家族，从GLM-5.2/5.3、DeepSeek V4 Flash、Qwen，一路支持到了975B的Inkling，以及2.8T参数的Kimi K3。\n虽然后者需要大约1.6TB硬盘空间，但RAM要求只要32GB起步。\n744B模型，内存里只放9.9GB\nColibrì能这么玩，首先得感谢这两年越来越流行的MoE架构。\n以GLM-5.2为例。虽然整个模型足足有744B参数，但MoE并不会在生成每个token时把744B参数全部计算一遍。\n它会先通过Router判断：这个token该交给哪些“专家”处理？然后只激活其中一小部分。\nGLM-5.2总参数744B，但每个token实际激活的参数大约只有40B，这就留下了一个很大的操作空间：\n既然绝大多数专家当前根本用不上，为什么非得把它们一直放在昂贵的高速内存里？\n于是Colibrì干脆把模型拆成了常驻和临时调用两部分。\nAttention、Embedding、共享专家这些每次推理都要用到的Dense部分，大约17B参数，int4之后只占约9.9GB，直接常驻RAM。\n真正占地方的是后面庞大的路由专家。\nGLM-5.2有19456个路由专家，int4之后整体仍然要占大约370GB。\n这么大权重，普通电脑的内存显然塞不下。\nColibrì索性把它们全部放到NVMe SSD。\n模型开始生成token之后，Router先选出当前真正需要参与计算的专家；Colibrì再检查它们是否已经在高速内存中，没有命中的部分，才临时从SSD读取。\n算完这层，再继续处理下一层。\n以前运行大模型的思路大致是先想办法把模型装进显存/内存，再开始计算。\nColibrì相当于把这事儿倒过来了，需要什么，我再加载什么。\n作者JustVugg把这种方式类比成了一个针对模型权重的JIT。\n传统JIT不会提前编译整个程序，而是观察哪些代码真的在运行，再处理热点路径。\nColibrì的思路也类似。\n不把744B参数看作必须始终驻留在内存中的整体，而是将它变成一堆可以根据Router结果，在SSD、RAM和VRAM之间动态调度的数据。\nSSD也成“显存”了\n当然，如果每生成一个token都从SSD里现找专家，那电脑估计得读盘读到怀疑人生，速度恐怕也相当感人。\n事实上，在Colibrì最早那台12核CPU+25GB RAM的开发机上，GLM-5.2冷缓存时确实只有大约0.05～0.1 token/s。\n跑是能跑，但有亿点慢……\n所以，Colibrì接下来花心思的地方就是：\n怎么尽可能少去SSD里捞专家，如何让SSD、RAM和VRAM协同工作。\n它把VRAM、RAM和NVMe SSD组织成了一套分层的模型内存系统。\n基本原则很好理解，越常用的专家，住得越近。\n已经待在VRAM或者RAM里的专家，直接计算；\n最近刚刚使用过的专家，会尽可能继续留在RAM缓存里；\n真正不常用的专家，才继续待在SSD里，需要时再读取。\n为此，Colibrì首先加入了LRU缓存。\n最近被调用过的专家会优先留在RAM里，如果后面的Token又点中了同一个专家，就不需要重新跑一趟SSD。\n同时，Colibrì还会在运行过程中不断记录不同专家的使用次数。\n跑得越久，它越清楚哪些专家是真正的“常客”。\n这些高频专家会获得更高的缓存优先级，被尽量留在速度更快的存储层。\n而且Colibrì还不满足于等Router点完名再行动，它甚至会提前猜下一层要找谁。\n根据项目测试，相邻层之间的专家路由存在相当明显的相关性，提前一层预测专家的可预测性达到71.6%。\n于是当前这一层还在计算的时候，Colibrì就可以在后台提前读取下一层可能需要的专家。\n一边算一边读，原本串行发生的计算和SSD I/O被尽可能重叠起来。\n甚至SSD本身都还能继续堆料。\n如果机器里正好有两块SSD，Colibrì支持放置第二份模型副本，把专家读取任务分摊到不同硬盘上，并行利用两块盘的带宽。\n这么一套操作下来，它更像是给MoE模型做了一套权重分级调度系统。\n容量最大、最慢的NVMe负责兜底；RAM负责缓存更多常用专家；\n如果有GPU，VRAM则继续接住最适合放进高速内存的部分。\n哪里快，就尽量把最常用的权重往哪里搬；哪里空间大，就负责装下剩下的模型。\n开发者把这套思路称为AI memory multitiering，AI内存多层化。\n这里有一条很重要的设计原则是，专家放在哪里，只决定速度，不改变模型本身。\n一个专家无论已经待在VRAM里，还是临时从SSD里读取，Router的选择都不会因此改变，使用的权重精度也完全相同。\nColibrì不会因为你的机器内存少，就偷偷少算几个专家或者换一套路由。\n所以到了128GB RAM的纯CPU桌面机，可以缓存更多专家之后，速度能达到约1.8 token/s；\n如果一路堆到6张RTX 5090，让全部专家常驻高速存储层，解码速度则可以来到5.8～6.8 token/s。\n跑前沿大模型，不一定非要用机房里的专业服务器。\n朋友们有兴趣也可以自己跑跑看。\n以GLM-5.2为例，需要准备的东西其实只有两个：\n几百KB的Colibrì程序，以及大约372GB的模型。\nColibrì已经提供Linux、macOS和Windows的预编译版本，不想折腾编译的话，下载对应版本解压即可；\n想从源码开始，也只需要gcc或clang配合OpenMP。\n项目已经提供预转换好的GLM-5.2 int4模型，也可以从FP8原始模型自行转换。模型放好之后，一条coli chat就能直接进入对话。\n想更直观一点，则可以直接打开Web Dashboard。\n里面能实时看到Token生成速度、不同阶段耗时，以及当前有多少专家待在VRAM、RAM和磁盘。\nColibrì还专门做了一个“Brain”页面，把GLM-5.2的19456个专家全部可视化出来：\n哪个专家刚刚被Router点名、当前住在哪一层存储、调用热度如何，都能直接看到。\n不只是GLM-5.2，Colibrì目前支持的模型跨度很大，目前可运行九个模型。\n每个模型单独一套C适配文件，但是底层IO、缓存、tokenizer等公共组件复用同一个核心。\n小尺寸的有Qwen3.8-Flash-Next、Qwen3.6和OLMoE；\n接着DeepSeek V4 Flash是284B；GLM-5.2/5.3是744B；GLM-5.3-Flash是321B；\nThinking Machines的Inkling则来到了975B；\n最大的一位是Moonshot的Kimi K3：2.8T总参数、104B激活参数。\n这模型的权重需要大约1.6TB存储空间，但按照Colibrì给出的配置，RAM从32GB+就能起跑，同样不强制要求GPU。\n作者还欢迎大家踊跃参与实验，寻找更高效方案。\nTiny engine, immense model，微小引擎，庞大模型。\nColibrì是只胃口不小的蜂鸟。\nhttps://github.com/JustVugg/colibri\n- AI开始研究Physical AI：FSD级团队亮出首版模型Simate-beta，空降RoboDojo2026-09-26\n- 陆川手搓历史现场，王珞丹熬夜抽卡，阿里全模态开始兜底生产2026-09-22\n- 直播预告：未来两三年，哪些工业AI场景会率先爆发？2026-09-22\n- 具身智能技术路线尚未定型，基础设施却先收敛2026-09-18","d":"2026-09-26","u":"https://www.qbitai.com/2026/09/497624.html","c":"AI与智能科技/AI软件层/工程改进","a":"量子位","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"技术突破","tp":"SSD分层推理框架","sc":6.6,"scd":{"b":5.0,"i":7.0,"r":5.0,"d":6.5,"t":7.0},"aip":1,"as":"GitHub开源项目Colibrì是一个纯C实现、零引擎依赖的分层推理框架，已获32k Star。其核心思路是利用MoE架构每token仅激活少量专家参数的特性（GLM-5.2总参数744B但每token仅激活约40B），将int4量化后约372GB的模型权重存放在SSD中，推理时按需从硬盘加载所需专家，从而让仅配备25GB内存、无GPU的笔记本即可运行744B参数的GLM-5.2，最低RAM需求仅16GB，推荐24GB。该项目已支持9个模型家族，包括GLM-5.2/5.3、DeepSeek V4 Flash、Qwen、975B的Inkling以及2.8T参数的Kimi K3，其中K3需约1.6TB硬盘空间，RAM要求32GB起步。作者验证所用开发机仅为12核CPU加25GB内存。","kp":["GLM-5.2参数规模: 744B","GLM-5.2 int4处理后权重大小: 约372GB","最低运行内存[GLM-5.2 int4]: 16GB RAM","推荐内存[GLM-5.2 int4]: 24GB RAM","作者开发机配置: 12核CPU+25GB RAM"]},{"t":"谷歌TPU跑Kimi比英伟达GPU快57%！用的还是DeepSeek推理框架","b":"谷歌TPU跑Kimi比英伟达GPU快57%！用的还是DeepSeek推理框架\nvLLM人马创业公司团队出品\n克雷西 发自 凹非寺\n量子位 | 公众号QbitAI\n16块谷歌TPU v7跑Kimi K3，每秒跑出了709个Token，比老黄的GB200快了57%。\n做出这个成绩的，既不是造Kimi的月之暗面，也不是造TPU的谷歌，是一家叫Inferact的推理创业公司。\nInferact创始团队就是vLLM的原班人马，今年拿了a16z领投的1.5亿美元种子轮，估值8亿美元。\n他们给TPU写了一种叫megakernel的推理内核，把模型推理时原本要调度的几百个小程序焊成一个大程序。\n配合TPU独特的片上内存架构，megakernel把内存带宽利用率逼到了硬件理论峰值附近。\n配上DeepSeek提出的DSpark加速框架，K3在TPU上跑出了前面提到的每秒709 token的成绩。\n这套代码，现在已经开源。\n同样16块芯片，TPU快57%\nInferact把TPU和英伟达GPU放在完全相同的条件下跑了一轮benchmark，TPU赢了。\n测试是用16块TPU v7 Ironwood对阵16块英伟达GB200，两边都跑Kimi K3，都用vLLM推理引擎，唯一的变量是芯片和底层的kernel实现。\n最终，TPU跑出的成绩是每秒709个token，GB200跑出每秒452个，TPU的速度快了57%。\n这个速度里有DSpark推测解码的功劳。\nDSpark是由DeepSeek提出的推理加速框架，其原理是让一个小模型先快速猜出一串候选token，然后大模型再对这串候选token做批量验证，猜对的直接跳过，猜错的回退重来。\nInferact在TPU上跑通了这套流程，acceptance length达到了6，也就是每轮猜出的token里，平均有6个能直接通过大模型的验证，单步decode的耗时大约在8.5毫秒。\n关掉推测解码看裸速，差距同样拉得开。\n在batch size为1的情况下，TPU每秒能跑249个token，GB200只有127个，差距接近一倍。\n把batch size放大到8，TPU达到865个token每秒，GB200只有636个。\n另外在Qwen上，两种芯片的差距更大。\nInferact用4块TPU v7跑Qwen 3.8 27B，每秒跑出1515个token，同样配置的GB200只跑出了695个。\n而且这种提速并没有造成精度损失，Inferact用greedy decoding做了验证，Kimi K3在TPU上的GPQA-Diamond得分是94.4%，GSM8K是97.2%，和GPU上的结果完全一致。\n推理引擎一样，模型一样，芯片换一下，速度就差出了57%。\n这种程度的差距，按理说应该能从硬件规格表上找到解释，但实际情况恰好相反。\n两款芯片的算力也在同一个量级，TPU v7的HBM带宽是7380 GB/s，而GB200的HBM带宽反而更高，达到8000 GB/s，带宽更大的那块芯片，跑出来的速度反而更低。\n这种速度的差距，实际上来源于芯片上面跑的那层软件。\n把几百个小kernel，焊成一个大程序\nInferact用一个叫megakernel的方案解决了TPU上的推理效率问题，核心思路，是把模型推理时原本要调度的几百个独立小程序，合并成一个大程序，从而消除程序之间切换时的带宽浪费。\n大模型推理的速度瓶颈不在计算，在数据搬运。\n每生成一个token，模型的全部权重都要从HBM主存搬进芯片内部的高速缓存里算一遍，算完这一轮，下一个token再重新搬一遍。\n传统的做法是把一次推理拆成几百个独立的kernel，每个kernel负责一小块计算。\n这些kernel排着队一个接一个地执行，但问题出依然会在交接的间隙。\n上一个kernel干完了，下一个还没有启动起来，这段时间里内存带宽就这么空转着。\nCUDA Graphs和英伟达最新的PDL技术能缩短这个间隙，但kernel之间的边界还在。\nInferact的megakernel直接消除了这个边界。\nKimi K3一共有92层MoE计算，Inferact把这92层的计算逻辑从头到尾塞进了一个Pallas程序里，一次调用就走完整个模型的前向传播。\n边界消失之后，跨层权重预取就变得顺理成章了。\n第N层还在算MoE的时候，第N+1层的attention权重已经开始从HBM往片上缓存搬了。\n计算和数据搬运同时进行，内存带宽几乎没有空转的时刻。\nTPU的硬件特性让这种编排做起来格外顺畅。\nTPU v7的每个TensorCore带有64 MiB的VMEM片上内存，这块内存的生命周期完全交给软件来管理，工程师可以精确控制什么时候往里面装什么数据、什么时候把空间腾出来。\n64 MiB的容量足够同时装下当前层的计算数据和下一层预取的权重。\nGPU那边情况不同，英伟达Blackwell架构的片上内存分散在152个SM里面，总量大约38 MiB，由硬件自动调度，要做类似的跨层编排限制更多。\nInferact用Pallas语言手写了整个megakernel的代码，Pallas是谷歌给TPU做的底层编程语言，角色类似英伟达GPU上的CUDA。\nTPU默认的编译工具链XLA擅长优化单层计算，但跨92层协调数据搬运的决策分支太多，XLA的自动调度找不到最优解。\nInferact的做法是绕过XLA，用Pallas语言手写整个megakernel的代码，由工程师自己来决定每一步搬什么数据、存在哪块缓存、什么时候释放。\n这样做还带来了一个额外好处，那就是编译速度大幅提升，耗时从XLA的30分钟以上降到了不到90秒，工程师改完一版kernel一分半钟就能上机验证。\n目前这套megakernel是针对Kimi K3的模型结构做的定制优化，如果换一个模型架构还需要重新适配。\nInferact在博客里提到，团队接下来会把megakernel的支持扩展到更多模型架构上。\nvLLM原班人马的创业公司\nInferact去年11月成立，团队几乎就是vLLM的原始开发者，一群靠给英伟达GPU写推理引擎成名的人。\n他们今年一月出来创业，转头把TPU的推理速度做到了GPU前面。\nvLLM是目前开源推理引擎领域的重量级框架，支持超过500种模型架构，社区贡献者超过2000人，Meta、Google、Character.ai都拿它来做线上的推理服务。\nCEO Simon Mo是vLLM项目的原始维护者，伯克利EECS毕业，之前在Anyscale工作。\n联合创始人Woosuk Kwon是整个vLLM项目的发起人，伯克利计算机科学博士，导师是Ion Stoica。\nKwon提出的PagedAttention算法解决了GPU显存管理中的碎片化问题，这个算法至今仍然是vLLM的核心技术。\n首席科学家游凯超曾获清华大学特等奖学金，他在vLLM中主导了分布式推理功能的开发。\nInferact今年完成了1.5亿美元的种子轮融资，公司估值8亿美元。a16z和Lightspeed领投，真格、红杉、Altimeter跟投。\n这次的TPU megakernel来自Inferact与Google Cloud的一项联合工程合作。\n双方的目标是让TPU成为vLLM的一流支持对象，所有的优化成果都会回馈给上游的开源社区，tpu-megakernels代码仓库是这次合作的第一个公开成果。\n700 TPS on Kimi K3: A Case for TPU Megakernels\n- 在云栖大会，我终于看懂了米哈游千亿AI野心2026-09-26\n- OpenAI失控Agent还找DeepSeek、Kimi当外援！近百万条作案短链曝光2026-09-26\n- GPT-6 Astra搓3D刷屏后，3D生成的竞争规则变了2026-09-23\n- Claude Opus 5.5突袭！68万行代码一天迁完，API价格打8折2026-09-23","d":"2026-09-26","u":"https://www.qbitai.com/2026/09/497425.html","c":"AI与智能科技/AI硬件层/半导体","a":"量子位","i":"n","source":"articles-2026-09-27.csv","sr":"news/articles-2026-09-27.csv","tg":"技术突破","tp":"TPU推理超越GPU","sc":6.7,"scd":{"b":6.5,"i":6.5,"r":5.0,"d":7.0,"t":7.5},"aip":1,"as":"推理创业公司Inferact（vLLM原班人马创立，获a16z领投1.5亿美元种子轮融资，估值8亿美元）发布基准测试：在相同条件下，16块谷歌TPU v7 Ironwood运行Kimi K3达到每秒709个token，比16块英伟达GB200的每秒452个快57%。双方均使用vLLM推理引擎，唯一变量是芯片及底层kernel实现。关键在于Inferact为TPU编写的megakernel推理内核，将推理时原本需调度的数百个小程序合并为一个大程序，结合TPU片上内存架构，将内存带宽利用率推至接近硬件理论峰值。同时结合DeepSeek提出的DSpark推测解码框架（小模型生成候选token、大模型批量验证），acceptance length达到6，即每轮平均有6个token可直接通过验证。相关代码已开源。","kp":["推理速度[16块TPU v7跑Kimi K3]: 每秒709 Token","性能对比[TPU v7 vs GB200]: 快57%","测试芯片数量: 16块","融资情况: a16z领投1.5亿美元种子轮，估值8亿美元","megakernel原理: 将推理时需调度的几百个小程序合并为一个大程序"]},{"t":"用于光子-声子非局域超表面高$Q$值发光的连续域束缚态","b":"Author(s): Soheil Farazi and Srinivas TadigadapaThermal radiation is inherently broadband and incoherent, limiting its utility in applications requiring spectral selectivity such as molecular spectroscopy and free-space optical communications. Bound states in the continuum (BICs) provide a powerful route to confine light in open photonic systems …[Phys. Rev. Lett. 137, 133802] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/fhx1-953m","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"连续域束缚态发光","sc":5.3,"scd":{"b":6.5,"i":2.0,"r":5.0,"d":6.0,"t":6.0},"as":"热辐射本质上是宽带的和非相干的，这限制了其在分子光谱、自由空间光通信等需要光谱选择性的应用中的效用。该工作提出利用连续域束缚态（BICs）实现光子-声子非局域超表面的高Q值发光。BICs是开放光子系统中一种有效限制光的手段，能够在共振处实现极高的品质因子，从而将宽谱热辐射转变为具有光谱选择性的窄带发光。研究成果发表于Physical Review Letters 137, 133802。","kp":["束缚态类型[开放式光子体系]: 连续域束缚态","应用目标[热辐射超表面]: 高Q值、光谱选择性发光","平台[光-声非局域超表面]: 用于分子光谱与自由空间光通信"]},{"t":"无需磁场标定的$^{40}\\mathrm{K}$超冷费米气体超精细常数$A$的测定","b":"Author(s): Yajing Yang, Biao Shan, Yuhang Zhao, Jiahui Shen, Zhuxiong Ye, Liangchao Chen, Zengming Meng, Pengjun Wang, Wei Han, Jing Zhang, and Lianghui HuangHyperfine constant $A$ is a key parameter of the hyperfine structure and underpins precision spectroscopy and metrology. In this Letter, we develop a magnetic-field-calibration-free method for determining the ground-state hyperfine constant $A$ in an ultracold $^{40}\\mathrm{K}$ Fermi gas by utilizin…[Phys. Rev. Lett. 137, 133401] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/7sjf-yj2z","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"超冷气体超精细常数","sc":5.3,"scd":{"b":6.0,"i":2.5,"r":5.0,"d":6.0,"t":6.0},"as":"超精细常数A是超精细结构的关键参数，是精密光谱学和计量学的基础。研究人员开发了一种无需磁场标定的方法，用于测定超冷钾-40费米气体基态超精细常数A。该方法避免了传统方法中对磁场精确标定的依赖，利用超冷费米气体体系进行测量，为超精细常数的精密测定提供了新途径。成果发表于Physical Review Letters 137, 133401。","kp":["测量方法[超冷40K费米气体]: 无需磁场标定","目标参数[40K基态]: 超精细常数A"]},{"t":"通过${χ}_{b}$衰变中的双强子碎裂探测色八重态机制","b":"Author(s): Zhi-Guo He, Guanghui Li, Yu-Jie Tian, Xin-Kai Wen, and Bin YanThe color-octet (CO) mechanism is a cornerstone of nonrelativistic QCD, yet knowledge of its long-distance matrix elements remains limited, preventing stringent tests of the theory. We demonstrate that the Artru-Collins asymmetry in hadronic decays of the $P$-wave bottomonium state ${χ}_{b2}$ provid…[Phys. Rev. Lett. 137, 131903] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/ntf8-k9rh","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"色八重态机制探测","sc":5.1,"scd":{"b":5.5,"i":2.0,"r":5.0,"d":6.0,"t":6.0},"as":"色八重态机制是非相对论量子色动力学（NRQCD）的基石，但其长程矩阵元的认识仍然有限，阻碍了对理论的严格检验。研究提出利用P波底夸克偶素χ_b2的强子衰变中的Artru-Collins不对称性，通过双强子碎裂过程探测色八重态机制。该方法为提取和检验色八重态机制的长程矩阵元提供了新的实验途径。成果发表于Physical Review Letters 137, 131903。","kp":["探测手段[χb2强子衰变]: Artru-Collins不对称性","机制[非相对论QCD]: 色八重态机制长程矩阵元素知识受限"]},{"t":"从引力康普顿振幅到黑洞微扰理论","b":"Author(s): N. Emil J. Bjerrum-Bohr, Gang Chen, Carl Jordan Eriksen, and Nabha ShahWe employ a single worldline effective field theory in a Schwarzschild-Tangherlini background to compute the gravitational Compton amplitude up to third post-Minkowskian order. After excising the infrared divergences associated with the Weinberg phase, we establish a direct and exact map to results …[Phys. Rev. Lett. 137, 131601] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/f939-mjhj","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"引力康普顿振幅","sc":5.1,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.5,"t":6.0},"as":"研究采用单世界线有效场论方法在Schwarzschild-Tangherlini背景下计算引力康普顿振幅，计算达到第三后闵可夫斯基阶。在剔除与Weinberg相位相关的红外发散后，研究建立了与已有结果的直接且精确的映射关系。这一工作将引力散射振幅的计算与黑洞微扰理论联系起来，为引力波物理相关的两体问题研究提供了理论工具。成果发表于Physical Review Letters 137, 131601。","kp":["计算方法[Schwarzschild-Tangherlini背景]: 单世界线有效场论","计算阶数[引力康普顿振幅]: 第三后闵可夫斯基阶"]},{"t":"ATLAS与CMS在$\\sqrt{s}=13\\text{ }\\text{ }\\mathrm{TeV}$下希格斯玻色子对产生搜索结果的组合","b":"Author(s): G. Aad et al. (ATLAS Collaboration†[\"id\", \"col1\"], CMS Collaboration)First combination of searches for Higgs boson pair production from two CERN collaborations on this important standard model process provides information about the crucial Higgs self coupling.[Phys. Rev. Lett. 137, 131803] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/27s7-2frt","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"希格斯玻色子对产生","sc":7.1,"scd":{"b":7.5,"i":4.0,"r":6.5,"d":7.0,"t":7.0},"aip":1,"as":"ATLAS与CMS两个国际合作组首次组合了他们在质心能量13 TeV下对希格斯玻色子对产生搜索的结果。希格斯玻色子对产生是标准模型的重要过程，其测量直接关系到关键的希格斯自耦合信息。这是欧洲核子研究中心两大实验首次就该过程进行联合组合分析，提高了对希格斯玻色子对产生和希格斯自耦合的测量灵敏度。成果发表于Physical Review Letters 137, 131803。","kp":["对撞能量[ATLAS+CMS组合搜索]: 13 TeV","搜索目标: 希格斯玻色子对产生与希格斯自耦合信息"]},{"t":"无序对非常规超导的保护","b":"Author(s): Sofie Castro Holbæk, Morten H. Christensen, Andreas Kreisel, and Brian M. AndersenSeveral realizations of d-wave superconductivity on the Lieb and kagome lattices exhibit remarkably weak Tc-suppression, resembling the behavior of conventional s-wave superconductors.[Phys. Rev. Lett. 137, 136004] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/3cn5-hb8z","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"无序保护非常规超导","sc":5.2,"scd":{"b":6.5,"i":2.0,"r":5.5,"d":5.0,"t":6.0},"as":"研究考察了无序对非常规超导的影响。结果表明，在Lieb格子和kagome格子上实现的多种d波超导表现出显著微弱的临界温度Tc压制现象，其行为类似传统s波超导体对无序的响应。这一发现表明某些非常规超导体系对无序具有保护机制，突破了通常d波超导对非磁性无序敏感的预期，对理解非常规超导的无序效应具有重要意义。成果发表于Physical Review Letters 137, 136004。","kp":["超导Tc抑制[d波超导，Lieb与kagome晶格]: 显著微弱，类似常规s波行为"]},{"t":"利用与快速射电暴的交叉关联在弱透镜巡天中消除重子反馈效应","b":"Author(s): Calvin Leung, Josh Borrow, Kiyoshi W. Masui, Shion Andrew, Kai-Feng Chen, Joop Schaye, and Matthieu SchallerBaryonic feedback is a leading contaminant in studying dark matter using cosmic shear. This has meant omitting much of the data during cosmological inference, or forward modeling the spatial distribution of gas around dark matter halos using models for baryonic feedback, which introduces nuisance pa…[Phys. Rev. Lett. 137, 131003] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/ms7q-gw8d","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"弱透镜重子反馈消除","sc":5.5,"scd":{"b":6.5,"i":3.0,"r":5.5,"d":5.5,"t":6.0},"as":"重子反馈是利用宇宙剪切研究暗物质时的主要污染源。以往的处理方式要么在宇宙学推断中舍弃大量数据，要么利用重子反馈模型对暗物质晕周围气体空间分布进行正向建模，这会引入多余参数。研究提出利用与快速射电暴的交叉关联，在弱透镜巡天中消除重子反馈效应的影响，为弱透镜宇宙学研究提供新的数据校正手段。成果发表于Physical Review Letters 137, 131003。","kp":["方法[弱透镜巡天]: 利用与快速射电暴交叉关联消除重子反馈污染"]},{"t":"结合弱透镜与重子普查构建所观测宇宙的纯暗物质对应体的提案","b":"Author(s): Shuren Zhou and Pengjie ZhangBaryonic effects such as AGN feedback can significantly impact the matter clustering, are harder to model from first principles, and emerge as a severe limiting factor in weak lensing cosmology. To tackle this issue, we propose a generic relation of mapping the observed matter clustering to its coun…[Phys. Rev. Lett. 137, 131002] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/8kpm-r54z","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"弱透镜重子普查映射","sc":5.5,"scd":{"b":6.5,"i":3.0,"r":5.5,"d":5.5,"t":6.0},"as":"AGN反馈等重子效应会显著影响物质成团，难以从第一性原理建模，成为弱透镜宇宙学的严重限制因素。研究提出一个通用映射关系，将观测到的物质成团映射到其纯暗物质对应体，并结合弱透镜与重子普查数据构建所观测宇宙的纯暗物质对应体。该方法为消除重子效应、开展精确弱透镜宇宙学研究提供了新方案。成果发表于Physical Review Letters 137, 131002。","kp":["方法[弱透镜宇宙学]: 结合重子普查，构建观测宇宙的纯暗物质对应体映射关系"]},{"t":"逆β衰变的辐射修正：反应堆中微子的精度分析","b":"Author(s): Oleksandr TomalakWe present a complete calculation of radiative corrections to the inverse beta decay reaction, ${\\overline{ν}}_{e}+p→{e}^{+}+n$, at reactor antineutrino energies using heavy-baryon chiral perturbation theory. Our analysis consistently incorporates quantum electrodynamics, chromodynamics, and electro…[Phys. Rev. Lett. 137, 131806] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/zbcz-nkpd","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"逆β衰变辐射修正","sc":5.2,"scd":{"b":5.5,"i":2.5,"r":5.0,"d":6.5,"t":6.0},"as":"研究利用重子手征微扰理论，对反应堆反中微子能量下逆β衰变反应的辐射修正进行了完整计算。该分析自洽地包含量子电动力学、量子色动力学和电弱修正，适用于反应堆ν̄_e+p→e⁺+n过程。这一高精度计算对反应堆中微子实验的精度分析具有重要意义。成果发表于Physical Review Letters 137, 131806。","kp":["反应类型[反应堆反中微子能区]: 反β衰变辐射修正完整计算","理论框架: 重子手征微扰理论，一致纳入QED、QCD与电弱修正"]},{"t":"金属量子临界相图中电子自旋共振的演化","b":"Author(s): Marc Scheffler, Jörg Sichelschmidt, Conrad Clauss, Mojtaba Javaheri Rahim, Boris I. Kochelaev, Cornelius Krellner, Christoph Geibel, Frank Steglich, and Martin DresselUsing multiple antennae and their resonance harmonics, the changes in the electron spin resonance signal across the quantum critical point provide a measurement of the g-factor of the electrons.[Phys. Rev. Lett. 137, 136506] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/y227-dk8f","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"量子临界电子自旋共振","sc":5.0,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":6.0},"as":"研究利用多天线及其共振谐波技术，测量了电子自旋共振信号在跨越量子临界点时的变化，从而获得电子g因子的测量。实验在金属量子临界相图中追踪了电子自旋共振的演化，揭示了量子临界点附近电子磁性响应的变化规律。成果发表于Physical Review Letters 137, 136506。","kp":["测量目标[金属量子临界点附近]: 电子g因子","方法: 多天线及其共振谐波探测电子自旋共振信号演化"]},{"t":"相对论性重离子碰撞中真μ子素的搜寻","b":"Author(s): Zuo-tang Liang, Qian Yang, Hong Zhang, Jiaxing Zhao, and Pengfei ZhuangWe investigate the production of the as-yet-undetected true muonium within the quark-gluon plasma formed in relativistic heavy-ion collisions, employing a relativistic Boltzmann transport framework coupled to viscous hydrodynamic simulations. The obtained effective cross sections for central collisi…[Phys. Rev. C 114, L031901] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/p4dk-41pn","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"真μ子素搜寻","sc":5.5,"scd":{"b":7.0,"i":1.0,"r":4.0,"d":6.0,"t":6.0},"as":"研究采用相对论玻尔兹曼输运框架结合粘性流体动力学模拟，考察了相对论重离子碰撞中形成的夸克-胶子等离子体内尚未被探测到的真μ子素的产生。研究获得了中心碰撞中的有效截面，为在重离子碰撞实验中搜寻真μ子素提供了理论依据。成果发表于Physical Review C 114, L031901。","kp":["研究方法[相对论重离子碰撞]: 相对论玻尔兹曼输运框架耦合粘性流体动力学模拟","研究目标[夸克-胶子等离子体]: 真μ子素(尚未被探测)的有效产生截面研究"]},{"t":"RHIC束流能量扫描中Au-Au碰撞里轻（超）核产生的关联","b":"Author(s): Jiang-He Qiao, Jian-Yu Liu, Yan-Ting Feng, Feng-Lan Shao, and Rui-Qin WangBased on nucleons ($p, n$) and hyperons ($\\mathrm{Λ}, {\\mathrm{Ω}}^{−}$) formed at kinetic freeze-out from a quark combination model, we systematically study the production of light nuclei and hypernuclei in the hadronic coalescence picture. We present the analytical formula of the nucleus momentum …[Phys. Rev. C 114, 034919] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/lymg-t1fv","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"轻超核产生研究","sc":5.0,"scd":{"b":6.5,"i":1.0,"r":4.0,"d":6.0,"t":6.0},"as":"研究基于夸克组合模型，从动能冻结出时刻形成的核子（p、n）和超子（Λ、Ω⁻）出发，在核子并合图像中系统研究了轻核和超核的产生。研究给出了核动量分布的解析公式，并应用于RHIC束流能量扫描中Au-Au碰撞里轻（超）核产生的关联分析，为理解重离子碰撞中轻核和超核形成机制提供了系统框架。成果发表于Physical Review C 114, 034919。","kp":["研究方法[Au-Au碰撞轻(超)核产生]: 基于核子与超子动力学冻结的夸克组合模型结合强子并合图像","理论输出[轻核/超核动量分布]: 给出解析公式"]},{"t":"从超子-核子相互作用到氘核-超子飞米尺 度关联","b":"Author(s): Jiaxing ZhaoI investigate the low-energy scattering and femtoscopic correlation functions of the $d\\text{−}\\mathrm{Λ}$, $d\\text{−}\\mathrm{Σ}$, and $d\\text{−}\\mathrm{Ξ}$ systems within a microscopic folding approach. The effective deuteron-hyperon interactions are constructed by folding the HAL-QCD hyperon-nucle…[Phys. Rev. C 114, 034918] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/c7s2-xffv","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"超子核子关联","sc":4.8,"scd":{"b":6.0,"i":1.0,"r":4.0,"d":6.0,"t":6.0},"as":"研究在微观折叠方法框架内考察了d-Λ、d-Σ和d-Ξ体系的低能散射和飞米尺度关联函数。通过将HAL-QCD超子-核子相互作用折叠进氘核波函数，构造了有效的氘核-超子相互作用，进而计算飞米尺度关联函数。该工作建立了从超子-核子相互作用到氘核-超子飞米尺度关联的理论联系。成果发表于Physical Review C 114, 034918。","kp":["研究对象[低能散射与飞米尺度关联]: d-Λ、d-Σ、d-Ξ系统","相互作用构建方法[氘核-超子有效相互作用]: 折叠HAL-QCD超子-核子相互作用的微观折叠方法"]},{"t":"膨胀相对论流体中的非高斯流体动力学涨落","b":"Author(s): Gökçe Başar and Shuo SongWe consider nonequilibrium evolution of non-Gaussian fluctuations in a hydrodynamic system undergoing a boost-invariant expansion described by Bjorken flow. We derive the evolution equations for two- and three-point velocity correlators using the effective field-theory framework and present analytic…[Phys. Rev. C 114, 034917] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/hzvz-yfg1","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"非高斯流体涨落","sc":5.0,"scd":{"b":6.5,"i":1.0,"r":4.0,"d":6.0,"t":6.0},"as":"研究考察了经历Bjorken流所描述的纵向不变膨胀的流体动力学系统中非高斯涨落的非平衡演化。研究利用有效场论框架推导了两点和三点速度关联子的演化方程，并给出了解析结果。该工作为理解膨胀相对论流体中涨落的非高斯性质及其时间演化提供了理论工具。成果发表于Physical Review C 114, 034917。","kp":["研究框架[膨胀相对论流体非高斯涨落]: 有效场论框架","研究对象[Bjorken流]: 二点与三点速度关联子的演化方程(解析解)"]},{"t":"相对论流体动力学中的非高斯涨落：三点关联的汇流方程","b":"Author(s): Xin An, Gökçe Başar, and Mikhail StephanovWe derive deterministic equations for the evolution of non-Gaussian fluctuations in relativistic stochastic hydrodynamics. This is achieved by defining the average local Landau frame and corresponding fluctuating hydrodynamic variables. Fully nonlinear stochastic hydrodynamics is expressed in a unif…[Phys. Rev. C 114, 034916] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/89yq-qzm5","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"相对论流体涨落","sc":5.0,"scd":{"b":6.5,"i":1.0,"r":4.0,"d":6.0,"t":6.0},"as":"研究推导了相对论随机流体动力学中非高斯涨落演化的确定性方程。通过定义平均局部Landau标架及相应的涨落流体动力学变量，将完全非线性的随机流体动力学在统一框架中表述，并导出了三点关联的汇流方程。该工作为分析相对论流体中涨落的高阶统计性质提供了系统方法。成果发表于Physical Review C 114, 034916。","kp":["理论方法[相对论随机流体动力学]: 定义平均局部Landau系综及涨落流体变量","核心成果[非高斯涨落演化]: 完全非线性随机流体力学的确定性汇流方程"]},{"t":"利用$(d,p)$和$(d,pγ)$反应对$^{50}\\mathrm{Ti}$激发态的详细实验研究","b":"Author(s): B. Kelly, M. Spieker, L. T. Baby, S. Baker, A. L. Conley, D. Houlihan, K. W. Kemper, E. Litvinova, N. Tsoneva, and A. VolyaExcited states of semimagic $^{50}\\mathrm{Ti}$ were studied up to the neutron-separation energy via the $(d,p)$ and $(d,pγ)$ reactions. In total, 82 excited states were identified based on the measurement of angular distributions with the Super-Enge Split-Pole Spectrograph at Florida State Universit…[Phys. Rev. C 114, 034330] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/318y-r5dz","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"钛50激发态研究","sc":5.1,"scd":{"b":5.0,"i":1.5,"r":4.0,"d":8.0,"t":6.0},"as":"研究利用(d,p)和(d,pγ)反应详细实验研究了半幻数核钛-50直到中子分离能的激发态。实验在佛罗里达州立大学使用Super-Enge Split-Pole谱仪测量角分布，共确认了82个激发态。研究结合壳模型和准粒子振子密度等理论分析，为钛-50的能级结构提供了系统的实验数据。成果发表于Physical Review C 114, 034330。","kp":["实验对象[^50Ti激发态]: 半幻核，研究至中子分离能","实验方法[(d,p)与(d,pγ)反应]: Super-Enge Split-Pole磁谱仪角分布测量","识别激发态数量[^50Ti]: 82个"]},{"t":"在核能量密度泛函理论框架内调和CREX与PREX-II结果","b":"Author(s): Panagiota PapakonstantinouThe CREX and PREX-II measurements of the neutron-skin thickness of $^{48}\\mathrm{Ca}$ and $^{208}\\mathrm{Pb}$ challenge standard nuclear energy-density functional (EDF) descriptions of nuclei and nuclear matter. It is shown that the apparent tension arises from an implicit constraint in current EDF …[Phys. Rev. C 114, 034331] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/2rt9-cknc","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"中子皮测量调和","sc":5.7,"scd":{"b":7.0,"i":1.0,"r":5.0,"d":6.0,"t":6.0},"as":"CREX和PREX-II分别对钙-48和铅-208中子皮厚度的测量结果挑战了标准核能量密度泛函（EDF）对核与核物质的描述。研究表明，这种表观张力来源于现有EDF中隐含的约束。研究在核能量密度泛函理论框架内分析了如何调和CREX与PREX-II的结果，为中子皮测量与核理论模型之间的矛盾提供了解释途径。成果发表于Physical Review C 114, 034331。","kp":["研究问题[中子皮厚度测量]: CREX与PREX-II结果与标准核能量密度泛函(EDF)描述存在矛盾","关键结论[核能量密度泛函理论]: 表观张力源于当前EDF中的隐含约束，可在EDF框架内调和"]},{"t":"测量诱导相变中的后选择临界性","b":"Author(s): Dolly Nambi, Kabir Khanna, Andrew Allocca, Thomas Iadecola, Ciarán Hickey, Romain Vasseur, and Justin H. WilsonInformation-theoretic phase transitions, such as the measurement-induced phase transition (MIPT), characterize the robustness of quantum dynamics to local monitoring and are naturally formulated in terms of trajectories conditioned on typical measurement outcomes, which are naively accessible only t…[Phys. Rev. Lett. 137, 130403] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/gx2q-9xz1","c":"AI与智能科技/其它智能科技/量子信息和量子计算","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"测量诱导相变","sc":5.9,"scd":{"b":8.0,"i":2.0,"r":5.0,"d":5.0,"t":6.0},"as":"信息论相变（如测量诱导相变MIPT）刻画了量子动力学对局域监测的鲁棒性，其表述自然依赖以典型测量结果为条件的轨迹，而这些轨迹通常仅在单次实验中可获取。研究考察了测量诱导相变中的后选择临界性，分析了后选择条件下的临界行为，为实验上探测MIPT提供了新的思路。成果发表于Physical Review Letters 137, 130403。","kp":["研究对象[测量诱导相变(MIPT)]: 信息论相变，量子动力学对局域监测的鲁棒性","核心方法[后选择临界性]: 基于典型测量结果条件的轨迹表述"]},{"t":"精细拓扑绝缘体中环态的观测","b":"Author(s): C. Tornow, J. Rupprecht, P. Engeler, U. Drechsler, K.-E. Huhtinen, C. Devescovi, and S. D. HuberA delicate topological insulator realized in a silicon phononic metamaterial shows ring states induced by strong local impurities which are a signature of its underlying topology.[Phys. Rev. Lett. 137, 136603] Published Fri Sep 25, 2026","d":"2026-09-25","u":"http://link.aps.org/doi/10.1103/7ts9-mxcy","c":"通用技术/基础学科/基础物理","a":"Recent Articles in Phys. Rev. Lett.","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"拓扑绝缘体环态","sc":6.0,"scd":{"b":7.5,"i":3.0,"r":5.0,"d":5.0,"t":6.0},"as":"研究报道了在硅声子超材料中实现的精细拓扑绝缘体中环态的观测。强局域杂质在该体系中诱导出环态，这些环态是其底层拓扑性质的标志。该成果在声子平台上实验演示了拓扑绝缘体的特征态，为拓扑物态在超材料体系中的研究提供了实验证据。成果发表于Physical Review Letters 137, 136603。","kp":["实现平台[精细拓扑绝缘体]: 硅声子超构材料","关键观测[强局域杂质诱导]: 环态，为底层拓扑的标志"]},{"t":"变形稀土核素电荷半径中令人困惑的同中子素奇偶交错现象","b":"Isotonic (constant neutron number) systematics in the deformed rare-earth region have long suggested that nuclei with odd numbers of protons are more compact than their even-proton neighbors—except for Lu, whose recommended nuclear charge radius appeared anomalously large relative to Yb and Hf. We report a high-precision determination of the natural-abundance-averaged Lu-Yb charge-radius difference using extreme-ultraviolet spectroscopy of highly charged Na- and Mg-like ions, supported by high-accuracy relativistic atomic-structure calculations—a recently introduced method with the unique ability to measure inter-element charge-radius differences. Combined with muonic-atom and optical isotope-shift data, our results reestablish a pronounced odd-even staggering along the isotonic chain with neutron number N = 94. Nuclear density functional theory calculations, including quantified uncertainties, fail to reproduce the large stagger, while successfully reproducing the charge-radii staggering along isotopic chains and in semi-magic nuclei. In this work, we resolve the Lu inversion anomaly and provide new constraints for experimental and theoretical studies of nuclear size.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77471-7","c":"通用技术/基础学科/基础物理","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"稀土核电荷半径","sc":6.0,"scd":{"b":7.0,"i":1.5,"r":5.0,"d":7.0,"t":6.0},"as":"变形稀土区同中子素（中子数恒定）体系长期显示奇质子数核比相邻偶质子数核更致密的奇偶交错现象，但镥（Lu）的推荐核电荷半径相对Yb和Hf表现异常偏大，破坏了这一规律。研究利用高电荷态Na类和Mg类离子的极紫外光谱，结合高精度相对论原子结构计算，高精度测定了天然丰度平均的Lu-Yb电荷半径差，并结合缪原子和光学同位素移位数据，重新确立了沿同中子素链明显的奇偶交错现象。","kp":["测量对象[Lu-Yb电荷半径差]: 天然丰度平均高精度测定","实验方法[高电荷态离子]: 极紫外光谱术(Na-like与Mg-like离子)","关键结论[变形稀土核电荷半径]: 澄清Lu电荷半径相对Yb和Hf异常偏大的问题，证实奇质子核更紧凑的同中子素奇偶交错现象"]},{"t":"晶内链扩散对半结晶聚合物非线性力学的影响","b":"Large deformability is a specific property of many semicrystalline polymers that is enabled by plastic flow going along with a restructuring of the semicrystalline morphology in combination with strain hardening caused by network forces. This ability has been linked with the intracrystalline chain diffusion (ICD), which allows chains to move within the crystals. However, the influence of ICD on the non-linear mechanics remains unclear. We here study the intrinsic non-linear mechanical properties of two model polymers, namely PEO with fast ICD and PCL without ICD by mechanical testing in plane strain compression in dependence of strain rates and temperature. For both polymers the stress could be decomposed in an elastoplastic contribution and a network contribution. Strong differences in the true stress-true strain curves became evident by comparing the rate dependence at larger deformation. The stress in PEO depends strongly on rate and temperature, indicating relaxation of the network contribution, while the stress in PCL is rate independent. Experiments for PEO with different molecular weights indicate that the relaxation affects entire chains as expected for ICD.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78014-w","c":"通用技术/材料工程/特种功能材料/结构强度材料","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"半结晶聚合物力学","sc":5.1,"scd":{"b":6.0,"i":2.0,"r":4.5,"d":6.5,"t":5.0},"as":"半结晶聚合物的大变形能力源于塑性流动引起的半结晶形态重构与网络力导致的应变硬化，这一能力被认为与晶内链扩散（ICD）有关。本研究通过平面应变压缩力学测试，在不同应变速率和温度下比较了两种模型聚合物——具有快速ICD的PEO和没有ICD的PCL的本征非线性力学性能。两种聚合物的应力均可分解为弹塑性贡献和网络贡献两部分，且二者表现出显著差异，从而揭示ICD对非线性力学行为的影响。","kp":["[半结晶聚合物]: 大变形能力源于塑性流动与半结晶形貌重构结合应变硬化","晶内链扩散(ICD): 允许分子链在晶体内移动，影响非线性力学行为"]},{"t":"SpaCEy利用可解释图神经网络将空间组织模式与临床结局关联起来","b":"Tissues are complex ecosystems organised in space, and alterations in this organisation underpin multiple diseases. Spatial omics enables molecular profiling of tissue organisation, but linking these patterns to clinical outcomes remains challenging. We present SpaCEy (Spatial Clinical Explainability), an explainable graph neural network that identifies tissue patterns predictive of clinical outcomes in spatial proteomics datasets. SpaCEy models tissues as spatial graphs from molecular marker expression, without using predefined cell-type labels or anatomical regions as model inputs. Its embeddings capture intercellular relationships and molecular dependencies for predicting overall survival and disease progression. An integrated explainer identifies recurring spatial patterns and coordinated marker expression relevant to model predictions. Applied to a spatial proteomic lung cancer cohort, SpaCEy identifies spatial and protein-expression patterns associated with disease progression. Across multiple breast cancer proteomic datasets, it stratifies patients by overall survival, both across and within established clinical subtypes, and highlights protein markers underlying this stratification.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77924-z","c":"通用技术/基础学科/医学&生物学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"空间蛋白组学AI","sc":6.1,"scd":{"b":7.0,"i":3.0,"r":5.5,"d":6.0,"t":5.5},"as":"组织是空间组织的复杂生态系统，其组织结构的改变与多种疾病相关。空间组学可对组织组织方式进行分子分析，但将模式与临床结局关联仍具挑战。研究提出SpaCEy（Spatial Clinical Explainability），一种可解释图神经网络，可在空间蛋白质组数据中识别预测临床结局的组织模式。该方法将组织建模为基于分子标志物表达的空间图，无需预定义细胞类型标签或解剖区域作为输入，其嵌入可捕捉细胞间关系与分子依赖性，用于预测总生存期和疾病进展，并集成解释器识别重复出现的空间模式。","kp":["SpaCEy: 可解释图神经网络，将空间蛋白质组学中的组织模式与临床结局关联"]},{"t":"利用X射线谱学定量表征铂电极双电层中的非单调充电、过屏蔽与离子竞争","b":"Abstract The electric double layer (EDL) is an integral part of the local reaction environment in electrocatalysis. Indeed, the strong electric fields and modified interfacial water structure accompanying ion accumulation in the EDL have been shown to impact the performance of nearly every electrocatalytic reaction. However, quantifying interfacial ion accumulation experimentally is a long-standing challenge, leaving the atomic-level picture of electrolyte effects in electrocatalysis incomplete. Here, we address this challenge using an interface-sensitive in situ X-ray fluorescence spectroscopy approach based on a mesoporous Pt electrode to track interfacial ion concentration at the Pt-electrolyte interface in acidic media. We show that the EDL structure of the Pt electrode has a complex dependence on the applied potential and electrolyte composition. From a systematic analysis of ten electrolytes (including ions such as ClO4–, SO42–, K+, and Ca+), we show that adsorbates alter the surface free charge, resulting in nonmonotonic charging and overscreening. For nonadsorbing anions, we show that the concentration-dependent surface free charge follows classical Gouy–Chapman theory. At negatively charged surfaces, cations and protons compete to screen the surface free charge in the EDL, with a strong dependence on ion valency.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c14786/5439337/Nonmonotonic-Charging-Overscreening-and-Ion","c":"通用技术/基础学科/基础化学","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"电极双电层表征","sc":6.0,"scd":{"b":7.0,"i":2.5,"r":5.0,"d":7.0,"t":5.0},"as":"双电层（EDL）是电催化局部反应环境的重要组成部分，其离子积累伴随的强电场和界面水结构改变会影响几乎所有电催化反应性能，但实验定量表征界面离子积累长期存在困难。本研究开发了一种基于介孔铂电极的界面敏感原位X射线荧光谱学方法，在酸性介质中追踪Pt-电解质界面的离子浓度。结果表明Pt电极的EDL结构具有复杂的动态特征，包括非单调充电、过屏蔽及离子竞争行为，为电催化中电解质效应的原子级图像提供了实验依据。","kp":["[铂电极双电层]: X射线谱学定量表征非单调充电、过屏蔽与离子竞争现象"]},{"t":"阴极/电解液界面的工况衰减全反射远紫外光谱分析","b":"ABSTRACT Understanding cathode/electrolyte interfacial reactions is critical for improving the stability of high‐voltage Li‐ion batteries; however, the molecular mechanisms governing cathode/electrolyte interphase (CEI) formation remain poorly understood due to the buried and dynamically evolving nature of the interface. Here, we develop an operando attenuated total reflectance far‐ultraviolet (ATR‐FUV) spectroscopic method to directly probe cathode/electrolyte interfacial chemistry during electrochemical cycling. With the aid of principal component analysis, we isolate a voltage‐dependent interfacial spectral component that emerges at ∼3.9 V, well below the onset potential of electrochemical electrolyte oxidation. Supported by quantum chemical calculations, this component is assigned to dehydrogenated ethylene carbonate (de‐H EC) and vinylene carbonate (VC), revealing a chemically driven proton‐abstraction pathway induced by reactive surface oxygen species generated upon Li + deintercalation. This process recurs upon charging, demonstrating a voltage‐driven yet chemically initiated interfacial reaction distinct from direct electrochemical oxidation. These findings establish operando ATR‐FUV spectroscopy as a powerful tool for resolving transient cathode interfacial chemistry and provide new molecular‐level insights into CEI formation relevant to the design of next‐generation high‐voltage Li‐ion batteries.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.6529709","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"锂电界面光谱","sc":6.2,"scd":{"b":6.5,"i":5.0,"r":5.0,"d":7.0,"t":5.5},"as":"理解正极/电解液界面反应对提高高电压锂离子电池稳定性至关重要，但正极/电解质界面相（CEI）形成机理因界面隐蔽且动态演化而认识不足。本研究开发了工况衰减全反射远紫外（ATR-FUV）光谱方法，直接探测电化学循环过程中正极/电解液界面化学。借助主成分分析，分离出约3.9V时出现的电压依赖界面光谱组分，该电位远低于电解质电化学氧化起始电位。量子化学计算支持将该组分归属于特定界面物种，揭示了CEI形成的早期分子机制。","kp":["表征方法[阴极/电解液界面]: 工况衰减全反射远紫外光谱(ATR-FUV)原位探测CEI形成机制"]},{"t":"催化剂控制的Bicyclo[1.1.0]丁烷发散性应变释放胺化与骨架重塑","b":"ABSTRACT Catalyst‐controlled nitrene transfer enables divergent amination reactions of bicyclo[1.1.0]butanes through distinct modes of activation of their highly strained central σ‐bond. Under Rh(II) catalysis, bicyclo[1.1.0]butanes undergo selective strain‐release amination to furnish aminocyclobutenes, which provide efficient access to cyclobutane amino acids through a simple amination–hydrogenation sequence. In contrast, photocatalytic nitrene activation redirects the reaction pathway toward double amination and skeletal remodeling, affording functionalized dihydropyrrolidines that can be readily converted into pyrrole heterocycles under acidic conditions. The synthetic utility of both approaches is further demonstrated, for example, in a telescoped synthesis of cyclobutane amino acids from diazo precursors or downstream diversification reactions. Mechanistic experiments and computational studies reveal distinct catalyst‐dependent nitrene activation pathways that govern the fate of a common reactive intermediate and underpin the observed divergent reactivity.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.3256942","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"应变释放胺化","sc":6.1,"scd":{"b":7.5,"i":2.0,"r":5.5,"d":6.5,"t":5.0},"as":"本研究报道催化剂控制的氮宾转移反应，通过不同活化方式作用于bicyclo[1.1.0]丁烷的高张力中心σ键，实现发散性胺化。在Rh(II)催化下，底物经选择性应变释放胺化生成氨基环丁烯，经简单胺化-氢化序列可高效制备环丁烷氨基酸。相比之下，光催化氮宾活化使反应转向双胺化和骨架重塑，得到功能化二氢吡咯烷，后者在酸性条件下可转化为吡咯杂环。两种方法的合成实用性均得到验证，例如串联合成环丁烷氨基酸。","kp":["反应[Rh(II)催化/双环[1.1.0]丁烷]: 选择性应变释放胺化生成氨基环丁烯，经胺化-氢化序列获得环丁烷氨基酸","反应[光催化/双环[1.1.0]丁烷]: 氮宾转移重定向反应路径，实现发散性骨架重塑"]},{"t":"PCN‐700：用于探测金属有机框架中配位行为的晶体学模型平台","b":"ABSTRACT Coordination chemistry plays pivotal roles across a broad range of chemical, biological, and materials fields. Crystalline coordination materials provide unique opportunities for investigating coordination phenomena because their long‐range structural order enables atomic‐resolution characterization of coordination environments and structure–property relationships. Among them, metal–organic frameworks have greatly expanded the scope of coordination chemistry through their highly tunable compositions and spatial arrangements. To simplify the complexity associated with framework construction, post‐synthetic modification has emerged as an effective strategy for systematically tailoring existing frameworks while preserving their networks. Nevertheless, conventional modification approaches remain limited in installation efficiency and coordination investigation. The discovery of PCN‐700 together with the linker installation strategy has largely overcome these limitations. Owing to its highly uncoordinated zirconium clusters, predefined installation sites, and exceptional framework flexibility, PCN‐700 enables efficient installation while maintaining crystallinity, allowing atomic‐resolution visualization. Besides, linker installation decouples coordination from crystallization, transforming framework construction into controllable events at predefined crystallographic sites. In this review, we discuss linker installation pathways, host–guest interactions, and structure‐enabled applications in PCN‐700, highlighting the role of linker installation in establishing PCN‐700 as a model system for elucidating fundamental coordination chemistry, quantitatively correlating coordination events with material properties, and guiding the rational design of functional materials.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.9641173","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"MOF配位化学","sc":5.0,"scd":{"b":6.0,"i":2.0,"r":4.5,"d":6.0,"t":5.0},"as":"配位化学在化学、生物和材料领域作用重大，晶态配位材料因其长程结构有序性可对配位环境及构效关系进行原子级表征。金属有机框架（MOF）凭借高度可调的组成和空间排列极大拓展了配位化学范畴。为简化框架构建的复杂性，合成后修饰已成为在保持网络结构的同时系统性调控现有框架的有效策略，而常规修饰方法存在局限。本研究提出PCN-700作为晶体学模型平台，用于系统探测MOF中的配位行为。","kp":["PCN-700: 用于原子分辨率探测金属有机框架中配位行为的晶体学模型平台"]},{"t":"光氧化还原/铬协同催化实现烯烃的不对称双键异构化","b":"ABSTRACT The asymmetric contra‐thermodynamic double‐bond isomerization of alkenes remains a formidable challenge due to the lack of activating functional groups for chiral catalyst recognition. Here we report a photoredox/chromium combined catalysis that enables highly asymmetric double‐bond isomerization of internal alkenes to enantioenriched terminal alkenes. This atom‐economical transformation proceeds via SET/PT or HAT‐mediated generation of a chiral allylchromium intermediate, followed by enantiodetermining protodemetalation. The protocol exhibits good functional group compatibility and has been successfully applied to the concise asymmetric total synthesis of (+)‐licochalcone E.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.6481438","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"烯烃不对称异构化","sc":6.1,"scd":{"b":7.5,"i":2.0,"r":5.5,"d":6.5,"t":5.0},"as":"烯烃的不对称反热力学双键异构化因缺乏供手性催化剂识别的活化官能团而极具挑战性。本研究报道光氧化还原/铬协同催化体系，实现内烯烃向富对映体端烯烃的高不对称双键异构化。该原子经济性转化通过SET/PT或HAT介导生成手性烯丙基铬中间体，随后经对映决定性质子去金属化完成。该方法官能团兼容性好，已成功应用于(+)−甘草查尔酮E的简捷不对称全合成。","kp":["催化体系[烯烃不对称双键异构化]: 光氧化还原/铬协同催化，经SET/PT或HAT生成手性烯丙基铬中间体","转化特征[内部烯烃→末端烯烃]: 逆热力学、高对映选择性、原子经济性"]},{"t":"氮杂Büchner–Curtius–Schlotterbeck反应实现季碳中心的选择性构建","b":"ABSTRACT Herein, we report the Aza‐Büchner–Curtius–Schlotterbeck reaction (ABCS)– a novel method for the uncatalyzed C─C insertion reaction of photogenerated donor‐donor diazo compounds into aryl aldimines. The transformation proceeds under very mild conditions and high chemoselectivity, favoring C─C over C─H insertion pathways. In a single step, two C(sp 2 )─C(sp 3 ) bonds are formed, granting access to homologated imines bearing a newly constructed quaternary carbon center in good yields. Subsequent hydrolysis gave homologated aldehydes, enabling versatile downstream transformations. The diazo intermediate is generated using a continuous‐flow microreactor, enhancing both safety and scalability. Mechanistic insights, supported by density functional theory (DFT) calculations, reveal the origins of the observed selectivity and reactivity.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.3147869","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"季碳中心构建","sc":5.7,"scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"as":"本研究报道氮杂Büchner–Curtius–Schlotterbeck反应（ABCS），一种光生供体-供体重氮化合物与芳基亚胺的无催化C─C插入新方法。反应在温和条件下进行，化学选择性高，倾向C─C插入而非C─H插入。该反应一步形成两个C(sp²)─C(sp³)键，以良好收率获得含新构建季碳中心的同系化亚胺，后续水解得同系化醛，便于下游多样化转化。重氮中间体采用连续流微反应器生成，提高安全性和可放大性。DFT计算支持了机理研究。","kp":["反应[ABCS/给体-给体重氮化合物]: 无催化光生C─C插入芳基亚胺，温和条件、高化学选择性(优先C─C而非C─H插入)","产物特征: 一步形成两个C(sp2)─C(sp3)键，构建季碳中心，产率良好"]},{"t":"Hofmeister效应调控的酰胺质子化水凝胶实现具有实用碘负载量的有机卤素互变型准固态锌电池","b":"ABSTRACT Organo‐interhalogen‐mediated four‐electron iodine conversion (I − /I 0 /I + ) promises high‐energy Zn batteries (4eZIBs) in noncorrosive aqueous electrolytes. Yet, polyiodide shuttling and I + hydrolysis restrict shorten cycle life at high iodine loadings. Here we report a dual‐anionic Hofmeister‐regulated amide‐protonated polyacrylamide (pPAM) hydrogel electrolyte to solve this issue. Consistent with experimental observations, underlying mechanistic interpretations are proposed. The potential protonated site ─COHNH 2 + in pPAM can interact with iodine species (I 3 − , I 2 , and organo‐interhalogen adduct), effectively suppressing active material loss during cycling. The dual‐anion‐regulated Hofmeister effect may contribute to control molecular mediator (2‐bromoacetamide, BrAce) flux within the pPAM gel, enabling fast organo‐interhalogen conversion. The extensive hydrogen‐bonding network of the hydrogel reshapes the hydrogen‐bonding environment of water, suppressing organo‐interhalogen adduct (I + species) hydrolysis. The resulting quasi‐solid‐state 4eZIBs substantially outperform aqueous counterparts and state‐of‐the‐art results. At 15.6 mg cm −2 iodine loading, stable cycling exceeds 2000 cycles at 15 mA cm −2 . At 28.3 mg cm −2 , the battery delivers an areal capacity of 9.95 mAh cm −2 and an areal energy density of 10.85 mWh cm −2 . An Ah‐level pouch cell cycles 50 times at 0.5 mA cm −2 , with an energy density of 305.27 Wh kg iodine −1 . This work provides a hydrogel design principle for organo‐interhalogen‐mediated conversion, advancing practical high‐loading 4eZIBs and beyond.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.5159694","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/其它电池体系","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"锌碘电池电解质","sc":7.1,"scd":{"b":7.5,"i":5.0,"r":5.5,"d":7.5,"t":5.5},"aip":1,"as":"有机卤素介导的四电子碘转化（I⁻/I⁰/I⁺）有望在非腐蚀性水系电解液中实现高能量锌电池（4eZIBs），但多碘化物穿梭和I⁺水解限制了高碘负载下的循环寿命。本研究报道一种双阴离子Hofmeister调控的酰胺质子化聚丙烯酰胺水凝胶电解质。其中潜在质子化位点─COHNH₂⁺可与碘物种（I₃⁻、I₂及有机卤素加合物）相互作用，有效抑制循环中活性物质损失；双阴离子调控的Hofmeister效应有助于控制分子介体（2-溴乙酰胺，BrAce）的分布，实现高碘负载下稳定循环。","kp":["电解质[4eZIBs]: 双阴离子Hofmeister调控的酰胺质子化聚丙烯酰胺(pPAM)水凝胶","机理[有机卤素四电子碘转化I⁻/I⁰/I⁺]: 解决多碘化物穿梭与I⁺水解问题，支持高碘负载"]},{"t":"细胞穿透聚二硫化物的本质","b":"ABSTRACT Cell‐penetrating poly(disulfide)s (CPDs) are the most popular thiol‐mediated uptake (TMU) tools for delivering attached substrates of interest (SOIs) into the cytosol. Despite their widespread use, their mode of action remains unknown. Herein, we elucidate how CPDs work using combined data from protein knockdown, µMap proteomics, coacervate assembly, mechanosensitive fluorescent membrane probes, CPD inhibitors, activators, and depolymerization. Their guanidinium sidechains first ion‐pair with anionic clusters on cell surfaces. By enhancing effective CPD concentration, these non‐covalent interactions enable, accelerate, and direct dynamic covalent disulfide exchange cascades with cellular thiols and disulfides. CPD bioconjugation rates match their uptake activity, exceeding those of disulfide monomers by 3000 times. Exchange with proteins capable of membrane remodeling allows CPDs to exploit these proteins' primary functions to mobilize anionic lipids (scramblases, ANO6), form toroidal elastic pores and related membrane deformations, and repair all after CPD‐SOI conjugates have passed through (tetraspanins, TSPAN8, flippases, etc.). Within cells, CPDs form coacervates and integrate into biological condensates, particularly nucleoli, until they depolymerize and release the SOIs. This understanding of the nature of CPDs also clarifies TMU in general and will guide future efforts to control cellular entry for drug delivery and pathogen defense.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.7902673","c":"通用技术/基础学科/医学&生物学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"细胞穿透材料","sc":6.2,"scd":{"b":7.0,"i":3.0,"r":5.5,"d":7.0,"t":5.0},"as":"细胞穿透聚二硫化物（CPDs）是最常用的巯基介导摄取（TMU）工具，可将连接的底物递送至细胞质，但其作用模式尚不清楚。本研究结合蛋白敲低、µMap蛋白质组学、凝聚组装、机械敏感荧光膜探针、CPD抑制剂/激活剂及解聚等数据阐明其机制：CPD的胍基侧链首先与细胞表面阴离子簇形成离子对，这些非共价相互作用提高CPD有效浓度，从而启动、加速并引导与细胞巯基/二硫化物的动态共价二硫交换级联。CPD生物偶联速率与其摄取活性相符，并超过其他体系。","kp":["[细胞穿透聚二硫化物(CPDs)]: 胍基侧链首先离子配对触发巯基介导摄取(TMU)，作用机制被系统 elucidate"]},{"t":"笼间Na⁺赋能单原子Co原位递送生物基乙烯骨架以获取3,4-位未取代喹啉","b":"ABSTRACT The multi‐step access to versatile N‐heterocyclic scaffolds is highly dependent on non‐renewable fossil‐based feedstock over different catalysts for each step. Here, a mesoporous NaY zeolite‐encapsulated atomically dispersed cobalt catalyst (Co@NaY‐M) is deliberately designed to be robust for single‐step, three‐component upgrading of biomass‐derived lactic acid, aldehydes, and anilines into 3,4‐unsubstituted quinolines via cascade dehydrogenation, annulation–aromatization, and decarboxylation. Na + co‐dopant in zeolitic hexagonal prism adjacent to single‐atom Co in the supercage acts as an electron promoter to pull electrons from Co. The electron‐deficient Co improves formed intermediate adsorption/activation, significantly declining energy barriers in cascade lactic‐acid‐to‐vinyl‐intermediate dehydrogenation, and 4‐substituted quinoline decarboxylation. Meanwhile, the presence of Na + strengthens interactions between Co and zeolitic carrier to improve the single‐atom stability. Co@NaY‐M has broad substrate scope for various 3,4‐unsubstituted quinolines with good compatibility to diverse functional groups in yields reaching 98% (>80 examples) and can be scaled up (11.24 g). Importantly, the developed methodology enables direct synthesis of various clinical drugs. Life‐cycle/techno‐economic investigations indicate that this protocol markedly lessens environmental footprints and is more price‐competitive compared to conventional quinoline synthesis methods. The precise modulation of neighboring zeolitic sites provides an effective avenue to directly access high‐value nitrogenous heterocycles from abundant renewables via oriented multiple reactions.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.5647747","c":"通用技术/材料工程/特种功能材料/催化材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"单原子钴催化喹啉","sc":5.5,"scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.5,"t":5.0},"as":"N-杂环骨架的多步合成通常依赖不可再生的化石原料及每步不同催化剂。本研究设计了一种介孔NaY分子筛封装原子分散钴催化剂（Co@NaY-M），可将生物质来源乳酸、醛类和苯胺一步三组分升级为3,4-位未取代喹啉，经级联脱氢、环化-芳构化和脱羧完成。超笼中单原子Co附近的六方棱柱内Na⁺共掺杂剂作为电子促进剂抽取Co的电子，缺电子Co改善中间体吸附/活化，显著降低乳酸-乙烯级联路径的能垒。","kp":["催化剂结构: 介孔NaY沸石封装原子级分散钴单原子催化剂(Co@NaY-M)","[生物质升级路径]: 单步三组分级联转化乳酸、醛和苯胺合成3,4-位未取代喹啉，经由脱氢-环化芳构化-脱羧级联过程"]},{"t":"基于形状记忆支架与离子调控内力储备实现可编程驱动力的双重驱动水凝胶致动器","b":"ABSTRACT Programmable soft actuators require independent control over both deformation pathways and driving‐force output, yet conventional shape‐memory systems generally encode these functions within a fixed network and therefore exhibit predetermined recovery behavior. Herein, we report a porous shape‐memory polymer/hydrogel actuator (SMP‐Net gel) that transforms fixed‐force shape recovery into ion‐programmable actuation. The actuator integrates a thermally programmable glycerol‐polycaprolactone methacrylic anhydride (GPCL‐MA) scaffold with an interpenetrating PAM/PVA hydrogel network. The porous scaffold determines the macroscopic shape‐memory trajectory, whereas the confined hydrogel functions as a Hofmeister‐responsive internal force reservoir. Ion‐specific regulation of chain aggregation and hydrogen bonding enables broad adjustment of the mechanical state, with strain and stress tunable over 43%–140% and 0.83–1.80 MPa, respectively, while simultaneously accelerating or retarding NIR‐triggered shape recovery. This dual‐driving architecture further supports reversible shape programming, controllable bending amplitude, recovery‐time regulation, and spatially selective deformation under localized NIR irradiation. Remote gripping, release, and multistep motion demonstrate the capability of the SMP‐Net gel for complex actuation tasks. This work establishes a general strategy for integrating shape‐memory scaffolds with ion‐regulated soft networks, opening a new route toward adaptive actuators, biomimetic machines, and intelligent soft robotic systems.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.7114810","c":"通用技术/材料工程/其它先进材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"水凝胶致动器","sc":5.2,"scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"as":"可编程软致动器需独立控制形变路径与驱动力输出，但传统形状记忆体系将两者编码于固定网络中，恢复行为预设。本研究报道多孔形状记忆聚合物/水凝胶致动器（SMP-Net gel），将固定力形状恢复转变为离子可编程驱动。该致动器集成热可编程的甘油-聚己内酯甲基丙烯酸酐酯（GPCL-MA）支架与互穿PAM/PVA水凝胶网络：多孔支架决定宏观形状记忆轨迹，受限水凝胶则作为Hofmeister响应的内力储备，通过离子特异性调控链聚集实现驱动力的编程控制。","kp":["致动器结构: 多孔形状记忆聚合物/水凝胶复合致动器(SMP-Net gel)","[驱动机制]: 将固定力形状恢复转变为离子可编程驱动，实现变形路径与驱动力输出的独立控制"]},{"t":"在大肠杆菌中重构能量系统以实现基于CO₂和甲醇的生长与生物生产","b":"Microbial CO₂ assimilation provides a strategy for sustainable biomanufacturing. However, CO₂ reduction requires substantial energy input, while native energy systems are tightly regulated and extensively consumed by endogenous metabolism, limiting assimilation efficiency. Here, we design and construct an orthogonal energy system in Escherichia coli, achieving an intracellular NUDH concentration exceeding 7.0 mM and an NUDH/NUD⁺ ratio above 55. Subsequently, we design a CO₂-formate-acetyl-CoA-pyruvate-malate pathway and reprogram key enzymes for NUDH-dependent operation. Integration of the OES-driven CAM* pathway with a rationally rewired native electron transport chain supports growth of the engineered E. coli on CO₂ and methanol, with a doubling time of 8.6 ± 0.3 h and a maximum OD₆₀₀ of 37.5 ± 5.8. Moreover, the platform extends CO₂ assimilation to biosynthesis of multiple chemicals from distinct CAM* pathway nodes, including mevalonate, lactate, 2,3-butanediol, and succinate. Together, these results establish a framework for reprogramming microbial energy metabolism and expanding one-carbon biotransformation.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77978-z","c":"通用技术/基础学科/医学&生物学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"大肠杆菌CO2固化","sc":6.6,"scd":{"b":8.5,"i":3.0,"r":5.5,"d":7.0,"t":5.0},"as":"微生物CO₂同化是可持续生物制造的策略，但CO₂还原需要大量能量输入，而天然能量系统受严格调控且被内源代谢大量消耗，限制同化效率。本研究在大肠杆菌中设计构建了正交能量系统（OES），使胞内NUDH浓度超过7.0 mM、NUDH/NUD⁺比超过55。随后设计CO₂-甲酸-乙酰辅酶A-丙酮酸-苹果酸途径并重编程关键酶以NUDH依赖方式运行。OES驱动的CAM*途径与合理重构的天然电子传递链整合，支持工程菌以CO₂和甲醇生长，倍增时间8.6±0.3小时。","kp":["胞内NUDH浓度[大肠杆菌正交能量系统]: >7.0 mM","NUDH/NUD⁺比值[大肠杆菌正交能量系统]: >55","[代谢路径]: 重构CO₂-甲酸-乙酰辅酶A路径实现基于CO₂和甲醇的生长与生物生产"]},{"t":"针尖尺寸60 nm的光电化学纤维细胞计数法用于测量突触间隙边缘与曲张体处的血清素动态","b":"ABSTRACT Tools and methods for investigating neurotransmitter dynamics at synaptic and nonsynaptic varicosities are essential for deciphering neural signaling events. Here, we first built a photoelectrochemical fiber cytometry with a tip size down to ∼60 nm for real‐time collection of photoelectrochemical signals in brain slices. Meanwhile, a serotonin (5‐HT)‐selective photoelectrochemical probe kit was created using a dual‐recognition strategy, integrating aptamer binding‐induced selective recognition and photo‐conversion electron transfer processes. The developed two‐sensor probe kit enabled the monitoring of 5‐HT dynamics, with linear detection ranges covering two distinct concentration windows from nM to mM. Leveraging the high selectivity, reversible response, and precise spatial positioning capability of this tool, volume transmission‐associated 5‐HT dynamics were measured at the edges of open synaptic clefts and non‐synaptic varicosities in acute brain slices. The findings suggested that the P2X 2 receptor modulated extracellular ATP (eATP)‐induced 5‐HT dynamics at edges of both open synaptic and non‐synaptic varicosities. Moreover, the P2Y 12 receptor exerted a stronger regulatory effect on 5‐HT dynamics at the edge of open synaptic varicosities than at non‐synaptic varicosities under eATP stimulation.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.8236222","c":"通用技术/检测和表征/传感器","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"血清素光电传感","sc":6.3,"scd":{"b":7.5,"i":3.5,"r":5.5,"d":6.5,"t":5.0},"as":"研究神经递质在突触和非突触曲张体处的动态对解读神经信号至关重要。本研究构建了针尖尺寸低至约60 nm的光电化学纤维细胞计数装置，可在脑切片中实时采集光电化学信号。同时采用双识别策略（适配体结合诱导的选择性识别与光电转换电子转移过程）研制了血清素（5-HT）选择性光电化学探针套件，检测线性范围覆盖nM至mM两个浓度窗口。凭借高选择性、可逆响应和精确空间定位，实现了对突触间隙边缘与曲张体处5-HT动态的监测。","kp":["探针针尖尺寸[光电化学纤维细胞计数法]: ~60 nm","[血清素检测策略]: 双识别策略，整合适配体结合诱导选择性识别的光电化学探针试剂盒"]},{"t":"通过氟导向、氢键辅助消除实现( Z )-杂原子取代氟代烯烃的立体控制合成","b":"ABSTRACT A general method for the stereocontrolled synthesis of ( Z )‐1,2‐heteroatom‐substituted monofluoroethylenes is described. The reaction proceeds via the Michael addition of N‐, P‐, and S‐centered nucleophiles to 1‐fluorovinyl sulfonium ylide ( Ylide‐VF ) under mild conditions, followed by an E2 process. This general protocol exhibits broad functional group tolerance and significant application potential, as demonstrated by the late‐stage functionalization of bioactive molecules and oligopeptides. Mechanistic investigations reveal that an intramolecular hydrogen bond within the Michael addition intermediate is the key stereocontrolling element, dictating the observed Z ‐selectivity.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.7450551","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"氟代烯烃合成","sc":5.0,"scd":{"b":6.0,"i":2.5,"r":5.0,"d":5.5,"t":5.0},"as":"本研究报道了(Z)-1,2-杂原子取代单氟乙烯的立体控制合成通用方法。反应在温和条件下经N、P、S中心亲核试剂对1-氟乙烯基锍叶立德（Ylide-VF）的Michael加成，随后发生E2消除完成。该方法官能团耐受性广，通过生物活性分子和寡肽的后期功能化展示了应用潜力。机理研究表明，Michael加成中间体内的分子内氢键是关键立体控制元素，决定了观察到的Z-选择性。","kp":["[合成方法]: N、P、S中心亲核试剂对1-氟乙烯基硫鎓叶立德的Michael加成-E2消除，实现(Z)-1,2-杂原子取代单氟乙烯的立体控制合成","[反应条件]: 温和条件，官能团耐受性广"]},{"t":"Agostic型硼氢络合物作为掩蔽的货币金属氢化物：硼与金之间的氢负离子迁移解锁CO₂反应性","b":"ABSTRACT Hydride addition to diphosphine‐borane (DPB) coinage‐metal complexes affords an unprecedented series of Cu(I), Ag(I), and Au(I) hydridoborate complexes 2‐M featuring bridging B–H···M interactions. Combined multinuclear NMR, IR, single‐crystal x‐ray diffraction, and DFT studies reveal the presence of agostic‐type σ(B–H)→M interactions across the series, with the strongest interaction observed for copper. These hydridoborate species are thermodynamically favored over the corresponding metal hydrides. Markedly distinct reactivity is observed depending on the coinage metal. Whereas, the Cu and Ag congeners proved to be unreactive toward CO 2 , the Au complex 2‐Au cleanly and reversibly fixes CO 2 to form the isolable Au(I) formate complex 3‐Au . In addition to quantitative and reversible CO 2 uptake and release, the Au hydridoborate complex 2‐Au is an efficient and robust catalyst for the hydroboration of CO 2 to HCO 2 Bpin and the dehydrogenation of formic acid, both with complete selectivity. Experimental and computational studies support a cooperative mechanism in which the B─H─Au motif acts as a masked gold hydride, thanks to hydride transfer.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.6128076","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"硼氢金属络合物","sc":5.2,"scd":{"b":6.5,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"as":"向双膦-硼烷（DPB）币族金属配合物中加氢负离子，获得一系列含桥连B–H···M相互作用的Cu(I)、Ag(I)、Au(I)氢硼酸盐配合物2-M。多核NMR、IR、单晶X射线衍射和DFT研究证实系列中均存在agostic型σ(B–H)→M相互作用，其中铜的相互作用最强。这些氢硼酸盐物种在热力学上比相应金属氢化物更稳定。不同币族金属反应性差异显著：Cu和Ag类似物对CO₂无反应，而Au配合物2-Au可干净且可逆地固定CO₂，生成可分离的Au(I)甲酸盐配合物3-Au。","kp":["[络合物类型]: 二膦硼烷(DPB)铜/银/金(I)硼氢化物络合物，含桥连B–H···M相互作用(agostic型σ(B–H)→M)","[相互作用强度]: 铜的σ(B–H)→M相互作用最强"]},{"t":"重新审视匮乏引发注意力隧道效应的证据","b":"People in poverty sometimes behave in ways that perpetuate their socioeconomic condition. By one influential account, these behaviors arise from psychological effects of scarcity on attention that create greater focus toward managing scarce resources, at the cost of attention to potentially-beneficial information outside of this ‘tunnel’. Although the tunneling hypothesis has been widely discussed in academia and beyond, its direct empirical support derives primarily from a landmark study by Shah et al. (2012) in which participants played games while their access to resources was experimentally manipulated, rendering participants either ‘rich’ or ‘poor’. Here, we present new analyses that contest the original interpretation of the data, showing that the behavioral differences between ‘rich’ and ‘poor’ participants are more parsimoniously explained by the game’s structure than by an attentional shift caused by the scarcity manipulation—a conclusion we substantiate through an additional experiment. We contextualize our findings within the literature on scarcity and attention, and highlight the need for greater clarity regarding the tunneling hypothesis itself.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78074-y","c":"不相关","a":"Scientific community and society : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文"},{"t":"从全电池热力学角度重新审视金属介导的电化学合成氨","b":"Abstract Dissociative, metal-mediated electrochemical nitrogen reduction can achieve high selectivity under mild conditions, but its energy cost is often obscured by cathode-only accounting. Here, we develop a full-cell thermodynamic framework for metal-mediated ammonia electrosynthesis by decomposing the cycle into mediator generation, nitrogen incorporation, and protonation. We show that, once nitrogen incorporation and protonation are made downhill, the dominant lower bound on reversible electrical work is set by the mediator equilibrium potential. For Li-mediated nitrogen reduction, cathode-only Li generation already imposes a floor of approximately 9.12 eV per NH3, while full-cell accounting with anodic water oxidation raises the system-level cost further. Highly reducing mediators such as Li, Ca, and Mg preserve dissociative nitride chemistry but exceed practical energy benchmarks. The resulting design map identifies lower-energy routes through electrolyte-driven potential shifts, alloy or intercalation buffering, electrochemical nitridation, and non-nitride intermediates.","d":"2026-09-26","u":"https://pubs.acs.org/aelccp/article/doi/10.1021/acsenergylett.6c02240/5439369/Rethinking-Metal-Mediated-Electrochemical-Ammonia","c":"零碳产业/物质循环/资源加工/有机物/平台化工品/氨","a":"ACS Energy Letters: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"电化学合成氨","sc":5.9,"scd":{"b":6.5,"i":5.0,"r":5.5,"d":6.5,"t":5.5},"as":"解离型金属介导电化学氮还原可在温和条件下实现高选择性，但其能耗常被仅计阴极的核算方式掩盖。本研究开发金属介导氨电合成的全电池热力学框架，将循环分解为介体生成、氮掺入和质子化三步。研究表明，当氮掺入和质子化为下坡过程时，可逆电功的主要下限由介体平衡电位决定。对锂介导氮还原，仅阴极锂生成即已造成约每NH₃ 9.12 eV的下限，而包含阳极水氧化的全电池核算进一步抬高系统级成本，高还原性介体亦存在类似限制。","kp":["[分析方法]: 全电池热力学框架，将金属介导电化学合成氨循环分解为介体生成、氮掺入和质子化三步","[结论]: 阴极单独核算掩盖了真实能耗，氮掺入与质子化放热后可逆电位的下限由介体再生决定"]},{"t":"调控电子-声子耦合以实现钙钛矿量子点中的单光子上转换","b":"Abstract Perovskite quantum dots (PQDs) feature intriguing single-photon upconversion (SPUC) behavior, whereby anti-Stokes photoluminescence (PL) can be achieved under mild continuous-wave photoexcitation, enabling applications in optical refrigeration, background-free bioimaging, and upconversion photovoltaics. While the conventional (down-conversion) PL efficiency of PQDs can be enhanced to near-unity levels, precise control of phonon-assisted upconversion, the crucial process for SPUC-PL, remains a key challenge. Herein, we demonstrate a rational strategy to improve the upconversion efficiency in organic–inorganic hybrid PQDs compared to all-inorganic counterparts. Using temperature-dependent photoluminescence spectroscopy and femtosecond absorption spectroscopy, we reveal that this cation engineering increases the electron–phonon coupling strength by nearly threefold and shortens the upconversion time constant from 445 fs to below the temporal resolution limit of 120 fs. Consequently, the SPUC efficiency under continuous-wave photoexcitation is enhanced, leading to an average upconversion energy gain above 160 meV, which surpasses those for reported surface-engineered all-inorganic PQDs and II–VI QDs.","d":"2026-09-26","u":"https://pubs.acs.org/aelccp/article/doi/10.1021/acsenergylett.6c02664/5439449/Managing-Electron-Phonon-Coupling-for-Single","c":"通用技术/材料工程/其它先进材料","a":"ACS Energy Letters: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"钙钛矿量子点上转换","sc":6.0,"scd":{"b":7.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"as":"钙钛矿量子点（PQDs）具有单光子上转换（SPUC）特性，可在温和连续波激发下实现反斯托克斯光致发光，应用于光学制冷、无背景生物成像和上转换光伏。虽然PQDs的常规下转换PL效率可接近 unity，但精确控制声子辅助上转换这一SPUC关键过程仍是挑战。本研究展示了一种提升有机-无机杂化PQDs上转换效率的策略，其效率高于全无机对应物。借助变温光致发光光谱和飞秒吸收光谱，揭示了电子-声子耦合在这一增强行为中的作用机制。","kp":["[上转换机制]: 钙钛矿量子点通过声子辅助的单光子上转换(SPUC)实现反斯托克斯发光","[激发条件]: 温和连续波光激发","[传统PL效率]: 可提升至接近1"]},{"t":"吩噁嗪还是吩噻嗪：从杂原子取代到构象变化及2D/3D钙钛矿太阳能电池中π共轭配体的界面效应","b":"Abstract Utilizing π-conjugated ligands offers opportunities to ameliorate intermolecular interactions between spacer cations, improving charge transport in 2D perovskites. We develop two new ligands by incorporating phenoxazine (PXZ) or phenothiazine (PTZ) moieties, namely PXZEAI and PTZEAI, in which oxygen-to-sulfur substitution induces the intrinsically coupled effects of a more folded conformation (17° smaller dihedral angle) and interfacial chemistry. Unexpectedly, X-ray diffraction (XRD) analysis exhibits distinct lattice spacings in (PTZEA)2PbI4 (16.81 Å) and (PXZEA)2PbI4 (20.36 Å). Density functional theory simulations and synchrotron radiation single-crystal XRD reveal closer packing for (PTZEA)2PbI4, consistent with stronger intermolecular π–π interaction enabled by a more folded conformation, together with sulfur-specific interfacial effects. Grazing incidence wide-angle X-ray scattering results further support π–π interactions between PTZEA+ cations. Ultimately, a contrasting efficiency trend is observed in 2D/3D perovskite solar cells (PTZEAI (25.28%) &gt; control (23.18%) &gt; PXZEAI (19.08%)). This performance difference reflects the synergy of heteroatom-driven conformational change and sulfur-mediated interfacial effects.","d":"2026-09-26","u":"https://pubs.acs.org/aelccp/article/doi/10.1021/acsenergylett.6c00934/5439364/Phenoxazine-or-Phenothiazine-From-Heteroatom","c":"零碳产业/能量转化/能源测/一次能源转化/太阳能转化/光伏","a":"ACS Energy Letters: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"钙钛矿电池配体","sc":5.6,"scd":{"b":6.0,"i":5.0,"r":4.5,"d":6.5,"t":5.5},"as":"利用π共轭配体可改善二维钙钛矿中间隔阳离子的分子间相互作用，提升电荷传输。本研究开发两种分别引入吩噁嗪（PXZ）或吩噻嗪（PTZ）片段的新配体PXZEAI和PTZEAI，氧-硫替换引起更折叠构象（二面角小17°）与界面化学的耦合效应。XRD显示(PTZEA)₂PbI₄与(PXZEA)₂PbI₄晶格间距分别为16.81 Å和20.36 Å。DFT模拟与同步辐射单晶XRD证实(PTZEA)₂PbI₄堆积更紧密，与更折叠构象带来的更强π–π相互作用一致。","kp":["[配体]: 含吩噁嗪(PXZEAI)或吩噻嗪(PTZEAI)的π共轭配体","[构象差异]: 氧替换为硫使二面角减小17°，构象更折叠"]},{"t":"哌啶鎓离聚物的低电位界面氧化生成甲酸盐促进AEM水电解槽中的析氢","b":"Abstract Piperidinium-functionalized ionomers are widely used alkaline-stable binders in anion exchange membrane water electrolyzers (AEMWEs). Although oxidative degradation has been demonstrated under strongly polarized, reactive oxygen species (ROS)-generating conditions, whether it can initiate through a distinct low-potential interfacial pathway before appreciable oxygen evolution remained unresolved. Here, we show that piperidinium groups undergo potential-induced interfacial oxidation on IrO2 near 1.3 V vs the reversible hydrogen electrode under deoxygenated conditions, demonstrating that dissolved O2 and diffusible O2-derived oxidants are not required. Quantitative 13C nuclear magnetic resonance spectroscopy identifies formate as the dominant soluble product, accompanied by ion-exchange-capacity loss and damage to a backbone-integrated structural unit. Faradaic-efficiency measurements in a pure-water-fed AEMWE show a 16.9% H2-normalized O2 deficit at 1.6 V, consistent with a substantial non-oxygen evolution reaction (OER) contribution from piperidinium oxidation. These findings distinguish low-potential interfacial oxidation from diffusible-ROS-mediated degradation and establish anodic cation stability as critical to durable pure-water-fed AEMWEs and reliable OER catalyst evaluation.","d":"2026-09-26","u":"https://pubs.acs.org/aelccp/article/doi/10.1021/acsenergylett.6c02584/5439370/Low-Potential-Interfacial-Oxidation-of","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/其它电池体系","a":"ACS Energy Letters: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"AEM电解水离聚物氧化","sc":6.4,"scd":{"b":6.5,"i":6.0,"r":5.5,"d":6.5,"t":5.5},"aip":1,"as":"哌啶鎓功能化离聚物是阴离子交换膜水电解槽（AEMWE）中广泛使用的碱性稳定粘结剂。尽管已在强极化、活性氧（ROS）生成条件下证实其氧化降解，但是否可在明显析氧之前经低电位界面途径起始尚不清楚。本研究表明，在除氧条件下，哌啶鎓基团在约1.3 V vs RHE电位下即在IrO₂表面发生电位诱导的界面氧化，说明无需溶解O₂或可扩散的O₂衍生氧化剂。定量¹³C核磁共振鉴定甲酸盐为主要可溶产物，并伴随离子交换行为，该低电位氧化路径促进AEMWE中的析氢。","kp":["[降解机制]: 哌啶鎓官能团在铱(Ir)表面发生电位诱导的界面氧化生成甲酸盐，该低电位路径可在明显析氧之前发生"]},{"t":"磷酸交联调控闭孔结构用于可规模化的硬碳负极","b":"Abstract The low-voltage capacity of hard carbon anodes, governed by closed-pore structures, directly determines the energy density of Na-ion batteries (NIBs), yet rational regulation of closed pores remains challenging. Herein, we report a phosphoric acid-induced cross-linking strategy to precisely tailor the closed pores of starch-derived hard carbon. H3PO4 promotes cross-linking with starch at low temperatures (150−400 °C), enhancing carbon conversion, while its removal by washing generates micropores through a templating effect that evolve into closed pores after high-temperature carbonization. Consequently, the carbon yield increases from 14.0% to 31.7%, and the resulting hard carbon delivers a reversible capacity of 395.8 mAh g−1 with an initial Coulombic efficiency of 89.4%. Additionally, the 3.5 Ah-level 26700 cylindrical cell based on the resulting anode demonstrates a high capacity retention of 96.5% after 500 cycles at the 1 C rate. This work provides a scalable and cost-effective pathway toward high-performance hard carbon anodes for practical NIB applications.","d":"2026-09-26","u":"https://pubs.acs.org/aelccp/article/doi/10.1021/acsenergylett.6c01963/5439451/Phosphoric-Acid-Cross-linking-Regulates-Closed","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/钠电","a":"ACS Energy Letters: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"硬碳负极闭孔调控","sc":7.0,"scd":{"b":7.0,"i":6.0,"r":5.0,"d":7.0,"t":6.0},"aip":1,"as":"该研究提出一种磷酸诱导交联策略，精确调控淀粉衍生硬碳的闭孔结构，用于钠离子电池负极。磷酸在150–400°C低温下与淀粉交联，提高碳转化率；洗涤去除磷酸后经模板效应形成微孔，并在高温碳化后演变为闭孔。该策略使碳产率从14.0%提升至31.7%，所得硬碳可逆容量达395.8 mAh g⁻¹，首次库仑效率为89.4%，且该方法具备规模化潜力，为调控硬碳闭孔结构、提升钠离子电池能量密度提供了有效途径。","kp":["策略[硬碳闭孔调控]: 磷酸诱导交联","交联温度[磷酸-淀粉]: 150−400 °C","碳转化率[磷酸低温交联]: 增强"]},{"t":"利用硼杂Triptycene Lewis酸实现TADF发射红移","b":"ABSTRACT Binding of a Lewis acid to an emitter molecule is a versatile method to redshift the emission. This approach is underexplored for thermally activated delayed fluorescence (TADF) materials. In this study, we report that the addition of a Lewis acid can induce large (>100 nm) bathochromic shifts in the emission in sulfone‐based donor–acceptor TADF (DA‐TADF) emitters and for the first time in multi‐resonant TADF (MR‐TADF) emitters, whilst retaining TADF behaviour. This is achieved through the binding of a 9‐sulfonium‐10‐bora‐triptycene (BTripS) Lewis acid to the fluorophore carbonyl or sulfone moiety to form bench‐stable Lewis adducts. In contrast, when using B(C 6 F 5 ) 3 as the Lewis acid, the generated adducts rapidly decompose on exposure to water to form H 2 O‐B(C 6 F 5 ) 3 . This work demonstrates that the formation of bench‐stable Lewis adducts has significant potential as a method to redshift the emission of two popular classes of TADF compounds. This provides a new approach to address the current challenge of accessing longer‐wavelength‐emitting MR‐TADF materials.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.3353986","c":"通用技术/材料工程/特种功能材料/介电/导电材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"TADF发光红移材料","sc":5.4,"scd":{"b":6.5,"i":3.0,"r":4.5,"d":6.0,"t":6.0},"as":"该研究报道利用9-磺鎓-10-硼杂三蝶烯Lewis酸（BTripS）与荧光团羰基或砜基结合，形成对水稳定的Lewis加合物，使供体-受体型TADF（DA-TADF）及首次在多共振TADF（MR-TADF）发射体中实现超过100 nm的大幅红移，同时保持TADF特性。与之相反，常用的B(C₆F₅)₃形成的加合物遇水迅速分解生成H₂O-B(C₆F₅)₃。该Lewis酸结合策略为调控TADF材料发射波长提供了一种简单有效的方法。","kp":["发射红移[Lewis酸-TADF发射体]: >100 nm","适用体系[红移策略]: 砜基D-A型TADF及MR-TADF发射体（首次）","TADF行为[Lewis酸结合后]: 保持"]},{"t":"Z构型保持的Rh催化E,Z ‐二烯对映选择性氢芳基化反应","b":"ABSTRACT Metal‐catalyzed additions to alkenes are among the most versatile methods to prepare enantioenriched small molecules. Processes that selectivity functionalize an E ‐alkene in the presence of a Z ‐alkene remain elusive, however, they would be an attractive approach to access chiral molecules with a remaining group capable of stereospecific functionalization. Here, we report the Z ‐retentive enantioselective Rh‐catalyzed hydroarylation of electron‐poor E,Z ‐dienes. The reaction gives targets in >95% ee without alkene Z ‐to‐ E isomerization. The product β‐aryl‐ Z ‐γ,δ‐unsaturated carbonyl compounds can be readily transformed into polyfunctional products containing multiple adjacent stereocenters in high diastereomeric ratios (≥90:10) via stereospecific alkene functionalizations. Mechanistic studies suggest that Rh‐enolate protonolysis is the turnover‐limiting step, and a selectivity model is developed based on reactivity and kinetic studies with E,E ‐dienes and E/Z ‐alkenes. DFT studies were used to shed light on the nature of the substrate‐catalyst interactions which likely lead to the observed selectivity. These results may have wide spanning implications for developing new Z ‐retentive alkene addition reactions.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.8809022","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"Rh催化对映选择性氢芳基化","sc":5.0,"scd":{"b":6.0,"i":2.0,"r":4.5,"d":5.5,"t":6.0},"as":"该研究报道了一种Z构型保持的铑催化对映选择性氢芳基化反应，可选择性官能化缺电子E,Z-二烯中的E-烯烃，产物ee值大于95%，且不发生Z到E的异构化。所得β-芳基-Z-γ,δ-不饱和羰基化合物可通过立体特异性烯烃官能化，以高非对映比（≥90:10）转化为含多个相邻立体中心的多官能产物。该方法为合成含保留Z-烯烃、可进一步立体特异性衍生化的手性分子提供了新途径。","kp":["催化反应[Rh催化E,Z-二烯]: Z构型保持的对映选择性氢芳基化","选择性特点[贫电子E,Z-二烯]: 在Z-烯烃存在下选择性官能化E-烯烃，保留Z基团可进一步立体特异性官能化"]},{"t":"对2026年Bundibugyo病毒病疫情中埃博拉单克隆抗体预测疗效的早期洞察","b":"The 2026 Bundibugyo virus disease (BVD) outbreak in the DRC and Uganda raises urgent questions about the efficacy of existing Ebola virus (EBOV) monoclonal antibodies (mAbs) against Bundibugyo virus (BDBV). Here, we perform genomic and structural analyses of 44 BDBV sequences, including 12 from the 2026 outbreak, to assess mAb binding to the viral glycoprotein (GP). While the MBP134 cocktail epitopes remain conserved, mAb114 (Ebanga) binding is compromised by E112D and P116A mutations, causing off-target binding and reduced affinity. Structural modeling of Inmazeb shows that while Odesivimab maintains epitope binding, Atoltivimab and Maftivimab fail to bind their designated sites individually, though the complete trimeric cocktail demonstrates BDBV synergistic binding. These computational models predict mAb114 efficacy against BDBV may be compromised due to epitope mutations affecting binding affinity, whereas MBP134 retains conserved targeting and holds promise as a broadly protective therapeutic. The complex binding behavior of Inmazeb components points to the importance of antibody combinatorial effects for treatment efficacy. These observations warrant urgent experimental validation through neutralization assays.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78077-9","c":"通用技术/基础学科/医学&生物学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"埃博拉单抗疗效预测","sc":7.9,"scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.5,"t":8.5},"aip":1,"as":"针对2026年刚果（金）和乌干达暴发的Bundibugyo病毒病（BVD）疫情，研究人员对44条BDBV序列（含12条来自本次疫情）进行基因组和结构分析，评估现有埃博拉病毒单抗与病毒糖蛋白的结合能力。结果显示MBP134抗体组合的表位保持保守，而mAb114（Ebanga）的结合因E112D和P116A突变受损，出现脱靶结合和亲和力下降；Inmazeb组合中Odesivimab仍可结合表位，Atoltivimab和Maftivimab单独无法结合各自位点，但完整三聚体组合对BDBV表现出协同结合。","kp":["MBP134鸡尾酒表位[BDBV]: 保持保守","mAb114结合[2026疫情毒株]: 因E112D和P116A突变而受损"]},{"t":"PARP10相凝聚通过靶向NAD⁺稳态抑制病毒复制","b":"Although diphtheria toxin-like ADP-ribosyltransferases (ARTDs) are implicated in host-virus interactions, the specific antiviral mechanisms of certain family members remain largely undefined. Here, we reveal that mono-ADP-ribosyltransferase PARP10 restricts viral replication by forming biomolecular condensates via multivalent interactions among its structured domains. PARP10 condensates enhance enzymatic activity, resulting in increased NAD⁺ consumption that ultimately inhibits viral replication. The antiviral effects of PARP10 are shown to require both its catalytic activity and NAD⁺ regulation, as catalytic mutants and PARP10 inhibitors abrogate these effects, while reduction of NAD⁺ potently restricts viral replication. Furthermore, we identify auto-ADP-ribosylation as an intrinsic negative feedback mechanism modulating PARP10 condensation. These findings establish PARP10 condensation as a compartmentalization strategy that amplifies local NAD⁺ consumption to safeguard host antiviral immunity.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78058-y","c":"通用技术/基础学科/医学&生物学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"PARP10抗病毒机制","sc":5.2,"scd":{"b":6.5,"i":2.0,"r":4.5,"d":6.0,"t":6.0},"as":"该研究揭示单ADP-核糖基转移酶PARP10通过其结构域间多价相互作用形成生物分子凝聚体，从而抑制病毒复制。PARP10凝聚体增强其酶活性，导致NAD⁺消耗增加，最终抑制病毒复制。抗病毒效果同时依赖其催化活性和NAD⁺调控：催化突变体和PARP10抑制剂会消除该效果，而降低NAD⁺水平可有效限制病毒复制。研究还发现自ADP-核糖基化是一种内在的负调控机制。","kp":["抗病毒机制[PARP10]: 通过结构域多价相互作用形成生物分子凝聚体","凝聚体效应[PARP10]: 增强酶活性，增加NAD⁺消耗，抑制病毒复制"]},{"t":"定制sp²-C─F键实现可逆的氧-过氧化物电催化","b":"ABSTRACT Rechargeable zinc‐air batteries are fundamentally limited by the sluggishness of four‐electron (4e − ) oxygen electrocatalysis and by bifunctional catalysts that rarely combine high activity with long‐term durability, resulting in substantial polarization and poor reversibility. Replacing this chemistry with O 2 –H 2 O 2 interconversion offers a compelling alternative, because two‐electron (2e − ) oxygen electrocatalysis features intrinsically more reversible pathways and faster kinetics. Herein, fluorine‐doped graphene is established as a programmable electrocatalytic platform for O 2 ‐H 2 O 2 interconversion, where tailored sp 2 ‐C─F bonding acts as a precise electronic lever to regulate OOH* intermediate binding and thereby steer O 2 –H 2 O 2 redox selectivity and kinetics. By controlling fluorine incorporation, the local electronic environment of graphene is delicately engineered without sacrificing electrical conductivity. The optimized catalyst exhibits outstanding bifunctional activity for 2e − oxygen reduction reaction (2e – ‐ORR) and peroxide oxidation reaction (POR), translating into rechargeable zinc‐based batteries with high power output and robust long‐term durability. Mechanistic studies reveal that sp 2 ‐C─F bonding induces localized electrostatic polarization at neighboring carbon sites, selectively stabilizing OOH* intermediates, lowering the kinetic barrier for 2e – ‐ORR, and concurrently facilitating POR while minimizing parasitic reactions. These findings demonstrate a fundamental structure‐property principle linking fluorine‐induced polarization with O 2 –H 2 O 2 redox kinetics, and position fluorinated carbon frameworks as a versatile foundation for next‐generation reversible energy storage.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.9423554","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/其它电池体系","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"锌空电池氧电催化","sc":6.9,"scd":{"b":7.0,"i":5.0,"r":5.0,"d":7.0,"t":6.0},"aip":1,"as":"该研究将氟掺杂石墨烯确立为O₂–H₂O₂可逆转化的可编程电催化平台，用于可充电锌空气电池。不同于缓慢的四电子氧电催化，两电子O₂–H₂O₂路径动力学更快、本征可逆性更高。研究通过定制sp²-C─F键作为精确的电子杠杆，调控OOH*中间体的结合，从而调控O₂–H₂O₂氧化还原选择性和动力学，为兼具高活性与长期耐久性的双功能氧催化剂设计提供了新思路。","kp":["催化策略[锌空电池]: 定制sp²-C─F键实现O₂–H₂O₂可逆转化","电催化路径[2e⁻氧催化]: 相比4e⁻路径本征更可逆、动力学更快"]},{"t":"稀土多变量金属有机框架：阳离子半径偏置的组成控制与性能调控","b":"ABSTRACT The synthesis of a multivariate metal–organic framework (MTV‐MOF) family, [Ln(DNNDI) 1.5 ] n ( UoB‐116 ), is reported (DNNDI: N , N' ‐bis(dinicotinate)‐1,4,5,8‐naphthalenetetracarboxydiimide). UoB‐116(Ln) is formed by 15 different metals (Ln = Y, La, Ce, Pr, Nd, Sm, Eu, Gd, Tb, Dy, Ho, Er, Tm, Yb, and Lu), all of which were shown to be isoreticular. The uniformity of the framework structure facilitated the synthesis of MTV‐MOFs with 2, 4, 12, 15, or 16 (including In(III)) different metals. Single crystal structures of each unimetallic MOFs and MTV‐MOFs with 12 or 16 metals were determined, confirming the isoreticular nature of this family of MOFs. Energy Dispersive X‐ray (EDX) analysis confirmed distribution of each metal throughout crystals of the MTV‐MOFs and compositional analysis indicated increased concentration of lanthanides with smaller cationic radius. A protocol was developed to control relative composition in bimetallic systems, UoB‐116(La 1‐x Lu x ) and UoB‐116(Dy 1‐x La x ) ( x = 0–1). In the case of UoB‐116(Dy 1‐x La x ) it is shown that the porosity, magnetism and UV–visible properties can be tuned through metal cation composition.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.5287849","c":"通用技术/材料工程/其它先进材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"稀土金属有机框架","sc":5.3,"scd":{"b":5.5,"i":3.0,"r":4.5,"d":7.0,"t":6.0},"as":"该研究报道了一类多变量金属有机框架（MTV-MOF）家族UoB-116，化学式为[Ln(DNNDI)₁.₅]ₙ，采用15种稀土金属（Y、La至Lu）合成，均具同网状结构。基于框架结构的均一性，成功制备了含2、4、12、15或16种（含In(III)）金属的MTV-MOF。通过单金属MOF及含12或16种金属MOF的单晶结构解析确认其同网状性，EDX分析证实各金属在晶体中均匀分布，为组成调控性能提供了平台。","kp":["MOF家族[Ln(DNNDI)1.5]n: UoB-116","金属组成[UoB-116]: 15种稀土金属均同网格","MTV-MOF组成[UoB-116]: 2、4、12、15或16种金属（含In(III)）"]},{"t":"三轴超分子编织物内的功能化与金属离子封装","b":"ABSTRACT Molecular weaving has attracted much interest in recent years. Supramolecular organic weaves offer many benefits, such as error correction, but their functionalization is challenging, as even minor modifications to the building blocks can disrupt self‐assembly. In this study, we demonstrate that a triaxially woven supramolecular organic framework formed by the self‐assembly of an oligoproline–perylene monoimide conjugate tolerates pre‐assembly functionalization and enables homogeneous incorporation of acetyl, pivaloyl, and thiophene moieties without altering the woven structure. Thiophene functionalization enabled the binding of toxic and noble‐metal ions from aqueous solution within the weave's confined pores. These results establish first examples of functionalized supramolecular organic weaves and highlight the value of modular peptide‐based woven frameworks for targeted guest encapsulation.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.5300884","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"超分子编织物封装","sc":5.1,"scd":{"b":6.5,"i":2.0,"r":4.5,"d":5.5,"t":6.0},"as":"该研究证明由寡脯氨酸-苝单酰亚胺共轭物自组装形成的三轴编织超分子有机框架可耐受预组装功能化，能在不破坏编织结构的情况下均匀引入乙酰基、特戊酰基和噻吩基团。噻吩功能化使该编织物的受限孔隙能够从水溶液中结合有毒金属离子和贵金属离子。这是首例实现功能化的超分子有机编织物，展示了超分子编织在功能材料中的潜力。","kp":["超分子编织物[三轴编织框架]: 寡聚脯氨酸-苝单酰亚胺自组装","功能化容忍性[预组装修饰]: 可容忍构建单元修饰，实现均匀金属离子封装"]},{"t":"一种用于缺氧肿瘤治疗的自驱动DNA纳米机器人","b":"ABSTRACT Solid tumors pose major therapeutic hurdles due to pathophysiological barriers such as hypoxia and dense stroma, which severely restrict drug penetration. Conventional nanomedicines lack the autonomous capability to navigate these evolving obstacles. Here, we engineer a DNA‑based nanorobot constructed on an optimized tetrahedral framework nucleic acid (tFNA) that co‑assembles tumor‑targeting aptamers, catalytic platinum nanoparticles (Pt‑NPs), and the therapeutic payload methylene blue (MB) into a single modular platform. This integrated design enables three coordinated functions: tumor‑specific recognition, self‑propelled transport driven by oxygen generation, and concurrent hypoxia alleviation to potentiate photodynamic therapy (PDT) in hypoxic tumors. The Pt‐NPs catalyze the decomposition of overproduced hydrogen peroxide (H 2 O 2 ) in the tumor microenvironment, generating oxygen bubbles that both drive deep tissue penetration (to depths > 300 µm) and alleviate local hypoxia. This self‑powered propulsion enables efficient delivery of MB, leading to cascaded PDT activation. In vivo, the nanorobot achieves 85% tumor regression through the coordinated actions of deep penetration, hypoxia relief, and enhanced PDT. This modular DNA nanoplatform provides a promising strategy for advanced nanomedicine by autonomously addressing key delivery barriers in solid tumor therapy.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.7173496","c":"通用技术/基础学科/医学&生物学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"DNA纳米机器人治肿瘤","sc":6.5,"scd":{"b":7.5,"i":4.0,"r":5.0,"d":6.5,"t":6.5},"as":"该研究构建了一种基于优化四面体框架核酸（tFNA）的DNA纳米机器人，共组装肿瘤靶向适配体、催化铂纳米颗粒和治疗载荷亚甲基蓝。该集成平台实现三大协同功能：肿瘤特异性识别、由产氧驱动的自推进运输，以及同步缓解缺氧以增强缺氧肿瘤的光动力治疗（PDT）。Pt纳米颗粒催化内源性过氧化氢分解产氧，克服实体瘤缺氧和致密基质对药物渗透的限制。","kp":["纳米机器人结构[缺氧肿瘤治疗]: 四面体框架核酸(tFNA)基DNA纳米机器人","功能组件[tFNA纳米机器人]: 肿瘤靶向适配体+催化铂纳米颗粒+亚甲蓝载荷"]},{"t":"通过协同增强压电极化与激子定向分离的分子工程金属有机框架实现高效压电光催化原子转移自由基聚合","b":"ABSTRACT Photoinduced atom transfer radical polymerization (ATRP) is often limited by the shallow penetration of visible light, and current strategies to address this limitation mainly focus on developing catalytic systems responsive to near‐infrared (NIR) light. In contrast, ultrasound‐driven polymerization offers deeper penetration but limited spatiotemporal control. To address these challenges, we pioneer the integration of piezo‐photocatalysis into ATRP by developing a donor–acceptor (D–A) metal–organic framework (MOF) catalyst (B‐Zr‐C) via incorporating electron‐acceptor N‐(4′‐carboxyphenyl)‐1,8‐naphthalimide (CPNI) into NH 2 ‐UiO‐66, which enables synergistically enhanced piezoelectric polarization and exciton separation. Multiscale characterizations verify that the introduction of CPNI prolongs the charge‐separated state lifetime and effectively increases the polarity of the MOF, as evidenced by significant increases in the piezoelectric coefficient d 33 , piezoelectric potential difference, and dipole moment. Under blue light and ultrasound, the piezo‐photocatalytic copper‐mediated ATRP apparent rate constant of B‐Zr‐C(1:1) is ∼fourfold higher than that under light alone, achieving high monomer conversion (> 90%, Đ M n > 1100 kg·mol −1 , Đ","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.1148889","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"压电光催化聚合","sc":6.0,"scd":{"b":7.0,"i":3.0,"r":4.5,"d":6.5,"t":6.0},"as":"该研究将压电光催化引入原子转移自由基聚合（ATRP），开发出给体-受体型金属有机框架催化剂B-Zr-C：将电子受体N-(4'-羧基苯基)-1,8-萘二甲酰亚胺（CPNI）引入NH₂-UiO-66，实现压电极化与激子分离的协同增强。该策略克服可见光穿透浅的局限，并结合超声驱动的时空控制优势，实现高效压电光催化ATRP。多尺度表征验证了CPNI引入对压电极化和激子定向分离的促进作用。","kp":["催化策略[ATRP]: 分子工程MOF压电-光催化集成","增强机制[MOF催化剂]: 协同增强压电极化与激子定向分离"]},{"t":"钴催化[2σ+2π]环加成反应：通过位点选择性捕获双环丁烷双自由基","b":"ABSTRACT Strained bicyclo[1.1.0]butanes (BCBs) have emerged as versatile precursors for accessing highly reactive intermediates, enabling unconventional bond constructions through strain‐release pathways. Herein, we report a cobalt(II)‐catalyzed strategy that combines thermal activation of BCBs with selective radical capture by Co(II) to afford head‐to‐head fused bicyclo[2.1.1]hexanes (BCHex). We propose that thermal activation of the BCB generates a reactive diradical intermediate, which is intercepted by a tailored bidentate phosphine Co(II) cationic complex via oxidative radical coupling, followed by a [2σ+2π] cycloaddition with indoles. Mechanistic investigations, including 31 P NMR spectroscopy, cyclic voltammetry, electron paramagnetic resonance (EPR), and density functional theory (DFT) studies, provide insights into the plausible reaction pathway. The involvement of paramagnetic Co(II) species is consistent with the broad features observed in both EPR and nuclear magnetic resonance (NMR) spectra of the catalyst. In addition, four structurally distinct Co(II) complexes were synthesized, fully characterized by UV–Vis and Fourier‐transform infrared (FTIR) spectroscopy, and evaluated as catalysts for the transformation. The cationic nature of the Co(II) species was further confirmed by phosphine oxide trapping experiments and single‐crystal X‐ray crystallography.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.8666577","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"钴催化环加成","sc":5.9,"scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"as":"该研究报道钴(II)催化策略，通过热活化双环[1.1.0]丁烷（BCB）产生双自由基中间体，再由定制双齿膦Co(II)阳离子配合物选择性捕获，经氧化自由基偶联及与吲哚的[2σ+2π]环加成，生成头对头稠合的双环[2.1.1]己烷产物。机理研究包括³¹P NMR、循环伏安、EPR和DFT计算，支持位点选择性自由基捕获机制，为利用张力释放构建非常规键提供了新方法。","kp":["催化策略[钴催化BCB环加成]: Co(II)催化热活化+选择性自由基捕获","产物[热活化BCB]: 头对头稠合双环[2.1.1]己烷(BCHex)","中间体[BCB热活化]: 双自由基中间体"]},{"t":"单原子Co–N–C与Ru纳米粒子的界面偶极工程增强乙酰丙酸加氢制γ-戊内酯","b":"ABSTRACT The catalytic hydrogenation of levulinic acid (LA) constitutes the central pathway for its conversion into high‐value γ ‐valerolactone (GVL); however, the prevailing challenge lies in enhancing its catalytic activity and stability under mild conditions. Herein, an interfacial dipole effect was established when single‐atom Co 1 –N–C was used as a support to anchor Ru nanoparticles (Ru NPs /Co 1 –N–C), which led to the transfer of electrons from Co 1 –N–C to Ru nanoparticles and maintenance of electron‐rich Ru. The Ru NPs /Co 1 –N–C catalyst exhibits enhanced catalytic performance in LA hydrogenation, achieving nearly complete conversion and 100% selectivity toward GVL under ambient conditions. The Ru NPs /Co 1 –N–C catalyst maintained its catalytic activity and selectivity over 10 consecutive cycles without noticeable deactivation, and the other 5 biomass‐derived compounds could also be effectively converted into corresponding lactone compounds. Density functional theory calculations reveal that the interfacial dipole effect of Ru NPs /Co 1 –N–C lowers the barriers of key kinetically relevant steps, particularly enabling near‐zero‐barrier H 2 dissociation while lowering the activation barriers for subsequent hydrogenation and final dehydration steps. Therefore, through interfacial dipole engineering between the single‐atom support and nanoparticles, the electronic structure of the metal sites can be adjusted, thereby enhancing the activity and stability of the catalyst in biomass upgrading and hydrogenation reactions.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.8734241","c":"通用技术/材料工程/特种功能材料/催化材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"加氢制γ-戊内酯","sc":5.7,"scd":{"b":6.0,"i":5.0,"r":5.0,"d":7.0,"t":5.0},"as":"该研究以单原子Co₁–N–C为载体锚定Ru纳米颗粒，构建Ru NPs/Co₁–N–C催化剂。界面偶极效应使电子从Co₁–N–C转移至Ru纳米颗粒，保持Ru富电子状态。该催化剂在乙酰丙酸加氢制γ-戊内酯反应中表现出优异性能，在温和条件下实现近完全转化和100%的GVL选择性，并在10次以上循环中保持活性和选择性，展示了界面偶极工程对提升催化剂活性与稳定性的作用。","kp":["催化剂体系[乙酰丙酸加氢]: 单原子Co₁–N–C负载Ru纳米粒子(Ru NPs/Co₁–N–C)","机制[Co₁–N–C/Ru界面]: 界面偶极效应，电子从Co₁–N–C转移至Ru纳米粒子"]},{"t":"由阴离子单体直接合成梯形及柔性聚磺酰亚胺：探究丁二腈-聚合物电解质共混物中的结构-性能趋同","b":"ABSTRACT Insights into how permanent microporosity influences ion transport in polymer electrolytes could facilitate the design of next‐generation single‐ion conducting (SIC) materials. Intrinsically microporous polymers and conventional polymers are typically regarded as fundamentally distinct electrolyte platforms; direct comparisons between compositionally similar examples are lacking. Here, we introduce a strategy for the synthesis of fluorinated aryl sulfonimide‐based polymers of intrinsic microporosity (FAS‐PIMs) together with flexible polysulfonimide analogs of similar composition that lack permanent microporosity. Although these polymers possess fundamentally different dry‐state architectures, incorporation of a common pore‐filling transport medium, succinonitrile (SN), drives the two systems toward remarkably similar nanostructures with similar bulk conductivities (>10 −5 –10 −4 S/cm at 40°C–80°C), thermomechanical properties ( G ʹ within 1–10 MPa over the temperature range of 25°C–120°C), and reprocessability. Molecular dynamics simulations and experiments suggest these unusual combinations of properties arise through different conduction mechanisms within the materials, and that sulfonimide anions are particularly advantageous for conduction in microporous matrices relative to strongly binding anions. Overall, this work introduces the first sulfonimide‐based PIM, establishes a comparison between permanently microporous and transiently porous single‐ion conducting polymers, and demonstrates that these two traditionally distinct electrolyte architectures can converge toward similar, useful bulk properties after incorporation of a pore‐filling transport medium.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.8257644","c":"通用技术/材料工程/特种功能材料/介电/导电材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"聚磺酰亚胺电解质","sc":5.4,"scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"as":"该研究提出合成氟化芳基磺酰亚胺本征微孔聚合物（FAS-PIM）及组成相似但无永久微孔的柔性聚磺酰亚胺类似物的策略，用于对比研究永久微孔性对离子传输的影响。尽管两类聚合物干态结构差异显著，但引入共同的孔填充传输介质丁二腈（SN）后，二者在结构-性能关系上呈现趋同，表明孔填充介质可弱化微孔性差异，为单离子导体聚合物电解质的设计提供新认识。","kp":["合成策略[含氟芳基磺酰亚胺聚合物]: 由阴离子单体直接合成梯形及柔性聚磺酰亚胺","研究对象[单离子导体电解质]: 本征微孔聚合物与传统聚合物的结构-性能对比"]},{"t":"整合性结构建模揭示人类Mic60-Mic19亚复合物在线粒体中作为扩散屏障","b":"Mitochondrial crista junctions (CJs) operate as regulated gateways into the cristae microenvironment, whose protein, metabolite, and ion compositions are finely tuned for mitochondrial function. The Mic60-Mic19 complex of the mitochondrial contact site and cristae organizing system (MICOS) complex was suggested to span across CJs and act as a diffusion barrier, but little is known of how its dynamic architecture facilitates this task. To address this question, we determine the crystal structure of an amino-terminal dimeric helical bundle of human Mic60. These and previous structural and biochemical data are harnessed in molecular dynamic (MD) simulations to develop a dynamic model of the human tetrameric Mic60-Mic19 subcomplex in the CJ environment, to validate its architecture using in organello and in vitro cross-linking data and to computationally characterize its function as a diffusion barrier. Our integrative structural biology approach enables the functional investigation of flexible, multidomain protein complexes which escape conventional structural methods.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77869-3","c":"通用技术/基础学科/医学&生物学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"线粒体扩散屏障","sc":5.3,"scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"as":"该研究解析了人源Mic60氨基末端二聚体螺旋束的晶体结构，并结合已有结构与生化数据进行分子动力学模拟，构建了线粒体嵴连接环境中人源Mic60-Mic19四聚体亚复合物的动态模型，并通过体内实验验证其架构。结果表明Mic60-Mic19亚复合物横跨嵴连接处，作为扩散屏障调控蛋白质、代谢物和离子进出嵴微环境，揭示了MICOS复合物动态结构在线粒体功能维持中的作用机制。","kp":["功能[Mic60-Mic19亚复合物]: 在线粒体嵴连接处充当扩散屏障","方法[Mic60-Mic19结构解析]: 整合性结构建模与晶体结构测定"]},{"t":"利用光开关激动剂对糖皮质激素受体活性的光学调控","b":"ABSTRACT Glucocorticoids (GCs) are widely prescribed anti‐inflammatory agents whose clinical utility is limited by systemic side effects arising from broad glucocorticoid receptor (GR) activation. Optical control of GR pharmacology offers a strategy to modulate receptor signaling with spatial and temporal resolution. Here, we report AzoCort1 , a prednisolone‐derived photopharmaceutical that enables light‐dependent tuning of GR activity in cell culture. Upon irradiation, AzoCort1 exhibits low picomolar activity (EC 50 = 11 pM) in a gene expression assay, representing a 36‐fold enhancement relative to its dark state (EC 50 = 400 pM). Despite its high potency, AzoCort1 is less efficacious in triggering glucocorticoid response element (GRE)‐driven activation compared to dexamethasone, while preserving maximal GR‐dependent repression of NF‐κB and AP‐1 signaling. These findings demonstrate light‐driven control of GR activity and separation of maximal GR‐mediated gene activation from gene repression.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.9699968","c":"通用技术/基础学科/医学&生物学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"光控糖皮质激素","sc":6.1,"scd":{"b":7.0,"i":4.0,"r":5.0,"d":6.5,"t":5.0},"as":"该研究报道了泼尼松龙衍生的光药物AzoCort1，可在细胞培养中实现糖皮质激素受体（GR）活性的光调控。光照后，AzoCort1在基因表达实验中表现出低皮摩尔活性（EC₅₀=11 pM），较暗态（EC₅₀=400 pM）增强36倍。尽管效力高，其触发糖皮质激素响应元件（GRE）驱动的激活效力低于地塞米松。该工作为以时空分辨率调控GR信号、减少系统性副作用提供了光药理学策略。","kp":["光控分子[糖皮质激素受体调控]: AzoCort1，波尼松龙衍生的光药物","活性[光照后AzoCort1]: 低皮摩尔级GR活性","调控特性[GR信号]: 光依赖性时空分辨调控"]},{"t":"界面Mn-氮化碳协同效应实现基于单原子催化的选择性光催化C–H氯化","b":"ABSTRACT Single‐atom photocatalysts offer a structurally defined platform for merging homogeneous and heterogeneous catalysis, yet their application in selective C─H functionalisation remains limited. In this study, we report a manganese‐based single‐atom photocatalyst (Mn@f‐g‐C 3 N 4 ) comprising atomically dispersed Mn─N x sites anchored on an arylamino‐functionalised graphitic carbon nitride support. Band‐gap engineering was used to enhance visible‐light absorption to afford a robust and recyclable photocatalyst for selective visible‐light‐driven C(sp 2 )─H chlorination of arenes and heteroarenes under mild conditions. Mechanistic investigations support a dual‐site pathway initiated at the carbon nitride support and continued at the Mn centre. Photoexcitation of the carbon nitride support triggers single‐electron transfer to the N‐chlorosuccinimide chlorination reagent, generating reactive Cl species, leading to the formation of well‐defined Mn─Cl intermediates. Chlorine transfer to the arene substrate is mediated via a cyclohexadienyl radical intermediate, followed by oxidation and deprotonation, affording the chlorinated product. Cooperation between the Mn atom and support suppresses unselective free‐radical chlorination pathways and enforces surface‐confined selectivity.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.5772245","c":"通用技术/材料工程/特种功能材料/催化材料","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"单原子光催化氯化","sc":5.9,"scd":{"b":6.5,"i":5.0,"r":5.0,"d":7.0,"t":5.0},"as":"该研究报道了锰基单原子光催化剂Mn@f-g-C₃N₄，将原子分散的Mn─Nₓ位点锚定在芳氨基功能化氮化碳载体上。通过带隙工程增强可见光吸收，构建了稳定可回收的光催化剂，可在温和条件下实现芳烃和杂芳烃选择性可见光驱动C(sp²)─H氯化。机理研究支持双位点路径：反应由氮化碳载体上的光激发引发，随后在Mn中心进行选择性氯化，为均相与多相催化的融合提供平台。","kp":["光催化剂[选择性C–H氯化]: Mn@f-g-C₃N₄单原子催化剂","活性位点[Mn@f-g-C₃N₄]: 原子分散Mn–Nx位点锚定于芳胺功能化石墨相氮化碳","设计手段[可见光吸收]: 带隙工程增强可见光吸收"]},{"t":"氟驱动界面重构通过增强CO2富集与质子供给实现高电流密度下pH通用CO2电解","b":"ABSTRACT High‐rate CO 2 electroreduction is challenged by the conflict between sluggish CO 2 activation and hydrogen evolution at high currents, particularly under pH‐universal and dilute CO 2 conditions. In this study, a defective fluorine‐modified bismuth (F‐Bi) with electron‐rich surface was generated by electrochemical reconstruction of fluorine‐doped bismuth oxide (F‐Bi 2 O 3 ), which exhibits a formate/formic acid Faradaic efficiency (FE HCOO − /HCOOH ) approaching 100% at 1800 mA cm −2 under pH‐universal conditions. In a membrane electrode assembly (MEA), F‐Bi delivers a FE HCOO − of 95.2% at 3.6 V and sustains operation for 120 h at a total current of 1 A. It also maintains a FE HCOO − above 95% at 800–1200 mA cm −2 under a dilute CO 2 feed of 15 vol% CO 2 /N 2 . In situ spectroscopy and ab initio molecular dynamics (AIMD) reveal that surface F species serve as hydrogen‐bond acceptors that reconfigure the interfacial water network, enhancing K + enrichment, local alkalinity, CO 2 accumulation, and rapid proton transfer. Density functional theory (DFT) further indicates that F‐Bi surface, combined with the K + /H 2 O microenvironment, facilitates charge redistribution, enhances *CO 2 and *OCHO adsorption, and then lowers the reaction energy barrier. This work overcomes the intrinsic activity–selectivity trade‐off in CO 2 electrolysis, offering a promising strategy for designing high‐performance pH‐universal electrocatalysts.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.7208628","c":"零碳产业/物质循环/资源回收利用与排放治理/碳捕集/其它碳捕集技术","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"CO2电解制甲酸","sc":7.5,"scd":{"b":7.5,"i":6.0,"r":5.5,"d":8.5,"t":5.5},"aip":1,"as":"该研究通过氟掺杂氧化铋（F-Bi₂O₃）的电化学重构，获得表面富电子的缺陷氟修饰铋（F-Bi）催化剂。在pH通用条件下，F-Bi于1800 mA cm⁻²电流密度下实现接近100%的甲酸盐/甲酸法拉第效率。在膜电极组件中，3.6 V下FE达95.2%，并在1 A总电流下稳定运行120小时；在15 vol% CO₂/N₂稀CO₂进料下，800–1200 mA cm⁻²范围内FE保持95%以上。氟驱动界面重构增强CO₂富集与质子供给。","kp":["法拉第效率[甲酸盐/甲酸, F-Bi, 1800 mA cm⁻²]: 接近100%","催化剂[高电流CO₂电解]: 氟掺杂氧化铋电化学重构生成的缺陷富电子F-Bi","机制[F-Bi界面]: 氟驱动界面重构增强CO₂富集与质子供给，pH通用"]},{"t":"硼烷催化1,3,2-二氧磷杂环戊烯及-磷杂环戊烷的水脱氢反应","b":"ABSTRACT We report that water undergoes rapid oxidative addition to readily accessible dioxaphospholes and ‐phospholanes within minutes at room temperature. The resulting phenylphosphinate esters release dihydrogen under mild conditions (room temperature to 60°C) in a borane‐catalyzed process. Remarkably, a pinacol‐derived dioxaphospholane reacts spontaneously with atmospheric moisture under ambient conditions to form the corresponding phenylphosphinate ester, thereby enabling the direct utilization of water from air for catalytic hydrogen evolution. The mechanism of the borane‐catalyzed dehydrogenation was investigated by variable time normalization analysis, targeted synthesis of intermediates, and DFT calculations. These studies support a catalytic pathway initiated by hydrogen elimination from the borane adduct of the phosphinate ester, followed by retro‐hydroboration to regenerate the catalyst.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.3462462","c":"通用技术/基础学科/基础化学","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"硼烷催化脱氢","sc":5.3,"scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"as":"该研究发现水可在室温下数分钟内快速氧化加成至易得的二氧磷杂环戊烯和磷杂环戊烷，所得苯基亚膦酸酯在室温至60°C的温和条件下经硼烷催化释放氢气。值得注意的是，源自频哪醇的二氧磷杂环戊烷可在环境条件下自发与大气水分反应，直接利用空气中的水进行催化产氢。通过变时归一化分析、中间体靶向合成和DFT计算，支持由氢消除引发的催化脱氢路径。","kp":["氧化加成条件[二氧磷杂环烯/磷杂环烷与水]: 室温下数分钟内快速反应","放氢条件[苯基次膦酸酯释放氢气]: 硼烷催化，室温至60°C温和条件","特殊反应性[频哪醇衍生二氧磷杂环烯]: 环境条件下自发与大气水分反应"]},{"t":"利用生物素化配体对受体特异性细胞力进行成像与校准","b":"ABSTRACT Covalent conjugation of ligand molecules to force sensors provides a powerful approach to image receptor‐transmitted cellular forces. While this strategy is effective for small‐molecule ligands, the conjugation process can damage large protein ligands. To address this challenge, we developed a modular mechano‐fluorescent coating (mMFC) that enables receptor‐specific force imaging using widely available biotinylated ligands. The mMFC construct consists of a poly‐L‐lysine (PLL) backbone for substrate adsorption, polyethylene glycol (PEG) grafts to prevent nonspecific binding, and DNA‐based integrative tension sensors (ITS) as force‐reporting units. Benefiting from copper‐free click chemistry, the mMFC is synthesized via a simple one‐pot reaction. During application, the mMFC is adsorbed onto substrates, and biotinylated ligands are subsequently linked to the mMFC construct via biotin‐avidin interactions, where the ITS reports receptor‐transmitted forces by fluorescence. By testing HeLa cells, platelets, and human T lymphocytes on mMFC platforms, we imaged cellular forces transmitted through RGD peptide, latency‐associated peptide (LAP), ICAM‐1, and anti‐CD3, which target integrins, LFA‐1, and T cell receptor (TCR) complex, respectively. We further demonstrated molecular force calibration and single‐molecule force imaging of these receptors using the mMFC platform. Overall, the mMFC provides a modular, convenient, and robust platform for investigating mechanotransduction across diverse receptors in various cell types.","d":"2026-09-26","u":"https://onlinelibrary.wiley.com/doi/10.1002/anie.4231597","c":"通用技术/检测和表征/传感器","a":"Angewandte Chemie International Edition","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"细胞力成像","sc":5.4,"scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"as":"针对大分子蛋白配体在共价偶联到力传感器时易受损的问题，该研究开发了模块化力荧光涂层（mMFC），可利用易得的生物素化配体实现受体特异性力成像。mMFC由聚-L-赖氨酸骨架（用于基底吸附）、PEG接枝（防止非特异结合）和基于DNA的整合张力传感器（ITS，力报告单元）组成，通过无铜点击化学一锅法合成，可直接吸附使用，为成像和校准受体介导的细胞力提供通用方案。","kp":["技术平台[受体特异性力成像]: 模块化机械荧光涂层(mMFC)，利用生物素化配体","结构[mMFC]: 聚-L-赖氨酸(PLL)骨架"]},{"t":"北冰洋光异养细菌中丙酮羧化途径的证据","b":"Carboxylases are among the most important enzymes in nature as they catalyze the fixation of inorganic carbon (CO2), a central step in the global carbon cycle. In addition to their well-known function in autotrophic CO2 fixation, many carboxylases play a role in the heterotrophic assimilation of organic compounds. In this study, we provide genomic evidence for an assimilatory carboxylation pathway involved in acetone degradation in photoheterotrophic bacteria from metagenomes collected along a latitudinal transect of the Arctic Ocean. This curious metabolism was linked to a single population of Gammaproteobacteria (Porticoccus arcticus). P. arcticus has a streamlined genome compared to Porticoccus relatives but has maintained a complete acetone carboxylation pathway while acquiring multiple proteorhodopsin genes by lateral gene transfer. Arctic Ocean metatranscriptomes revealed the acetone carboxylase and rhodopsins genes were among the most highly expressed P. arcticus genes in oligotrophic Arctic surface waters. P. arcticus sequences were consistently detected, and often abundant (up to 9%), in a multiyear Arctic Ocean 16S rRNA time-series, supporting its ecological significance in Arctic marine systems. Overall, this work reports a metabolic module (acetone carboxylation) in the ocean that may allow photoheterotrophic bacteria to enhance their biosynthetic capacity via CO2 assimilation.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78082-y","c":"通用技术/基础学科/基础化学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"细菌丙酮羧化途径","sc":4.8,"scd":{"b":6.0,"i":2.0,"r":5.5,"d":5.0,"t":4.0},"as":"该研究基于北极海洋横断面采集的宏基因组数据，提供了一种参与丙酮降解的同化羧化途径的基因组证据，涉及光异养细菌的有机物异化同化。该代谢被关联到一个单一的γ-变形菌种群（Porticoccus arcticus）。相比近缘种，P. arcticus基因组精简，但保留了完整的丙酮羧化途径，并获得多个其他基因，表明羧化酶在光异养细菌异养同化代谢中的作用，拓展了对全球碳循环的认识。","kp":["研究发现[北冰洋光异养细菌]: 基因组学证据表明存在丙酮降解同化性羧化途径"]},{"t":"学习过程中皮层全范围层板动力学出现分化","b":"Learning to link sensory information to motor actions requires coordinated activity across the cerebral cortex, but how different cortical layers contribute to learning remains unclear. Here we show that learning engages distinct, layer-specific activity patterns across the cortex of male mice during acquisition of a whisker-based go/no-go task. Using wide-field calcium imaging of either layer 2/3 or layer 5 neurons across 25 cortical areas, we found that learning produced markedly different, and sometimes opposing, changes in activity between layers. Layer 5 exhibited widespread suppression before sensory input and enhanced activity in frontal cortex during sensorimotor transformation, whereas layer 2/3 showed learning-related enhancements in higher-order sensory areas during sensation. In contrast, both layers displayed similar learning-related enhancement in barrel cortex during whisker touch. These findings reveal complementary roles of superficial and deep cortical layers during learning and demonstrate that layer-specific cortical dynamics are a fundamental feature of sensorimotor learning.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77948-5","c":"AI与智能科技/其它智能科技/脑机接口和神经科学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"学习皮层层板动力学","sc":5.4,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":7.0,"t":6.0},"as":"该研究利用宽场钙成像技术，对雄性小鼠25个皮层区域的第2/3层或第5层神经元进行观测，研究小鼠学习触须基础的go/no-go任务时皮层层特异性活动模式。结果显示，学习过程中不同皮层之间的活动变化存在显著的层间差异，甚至出现相反的变化：第5层在感觉输入前表现出广泛的活动抑制，并在感觉-运动转换期间于额叶皮层活动增强；而第2/3层则在感觉阶段于高级感觉区域表现出与学习相关的活动增强。研究表明学习驱动全皮层范围的层特异性动力学分化。","kp":["成像范围[宽场钙成像]: 覆盖25个皮层区","成像对象: L2/3或L5神经元","学习任务模型: 小鼠胡须依赖性go/no-go任务","学习诱导的皮层活动[层特异性]: 出现分化"]},{"t":"Alteromonas macleodii破坏硅藻硅质细胞壁，引发Thalassiosira rotula原生质体逸出及程序性坏死样死亡","b":"Diatom-bacteria interactions drive biogeochemical fluxes at the base of the marine food-web. Although bacteria are increasingly recognised as important drivers of algal mortality, the diversity of algicidal strategies remains understudied. Here we show that Alteromonas macleodii, a recurrent member of Thalassiosira rotula’s microbiome, breaches the diatom’s silica frustule, inducing >95% of cells to emerge from their shells within 72 h, exposing protoplasts to lysis and exploitation. Whilst protoplast formation was induced by diverse bacteria, A. macleodii uniquely caused population-wide collapse, used here to characterise this diatom stress response. Dual transcriptomics indicated the presence of a programmed necrosis-like cell death pathway in diatoms underpinning T. rotula’s terminal morphological change, alongside upregulation of bacterial motility, chemotaxis and opportunistic metabolism. These findings reveal a potent algicidal strategy, recasting A. macleodii as an antagonist that exploits diatom mortality for its own benefit, removes the ballast provided by their frustules and thus reshapes oceanic carbon cycling.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78079-7","c":"通用技术/基础学科/医学&生物学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"细菌杀藻机制研究","sc":5.8,"scd":{"b":6.5,"i":2.0,"r":5.0,"d":8.0,"t":6.0},"as":"研究揭示了海洋细菌Alteromonas macleodii对硅藻Thalassiosira rotula的杀藻机制。A. macleodii是T. rotula微生物组的常见成员，能够破坏硅藻的硅质细胞壁，72小时内诱导超过95%的细胞从壳中逸出，使原生质体暴露于裂解和被利用。虽然多种细菌均可诱导原生质体形成，但只有A. macleodii能导致种群全面崩溃。双转录组分析显示，硅藻中存在程序性坏死样细胞死亡通路，是T. rotula终端死亡的基础。该发现拓展了对海洋藻-菌互作和杀藻策略多样性的认识。","kp":["硅藻细胞逸出比例[72h, A. macleodii作用]: >95%","作用机制: 细菌破坏硅藻硅质细胞壁，引发原生质体逸出、裂解及程序性坏死样死亡"]},{"t":"小胶质细胞调节小鼠伏隔核突触发育及威胁回避行为背后的回路功能","b":"While microglia are well known for pruning synapses during neurodevelopment, their role in synapse formation remains understudied. Here we investigate how microglial absence impacts synaptic development in the nucleus accumbens (NAc), a region critical for emotional regulation and motivated behaviors. Using genetically modified mice lacking microglia (Csf1rΔFIRE/ΔFIRE), we find blunted excitatory synapse formation in the NAc, particularly during the second and third postnatal weeks. Tissue-level NAc proteomics in the third postnatal week reveals changes in proteins involved in synapse structure, trans-synaptic signaling, and pre-synaptic function. Although electrophysiological changes largely resolve by adulthood, microglia-lacking mice exhibit persistent changes in threat avoidance behavior and underlying NAc neuronal activity. Transient depletion of NAc microglia during the second postnatal week similarly disrupts synapse formation and adult threat avoidance. Together, these findings identify a role for microglia in shaping NAc synaptic development and in establishing functional circuits that support adult behavioral function.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77487-z","c":"AI与智能科技/其它智能科技/脑机接口和神经科学","a":"Biological sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"小胶质细胞突触发育","sc":5.5,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":7.5,"t":6.0},"as":"研究利用缺乏小胶质细胞的基因工程小鼠（Csf1rΔFIRE/ΔFIRE），探讨小胶质细胞在伏隔核（NAc）突触发育中的作用。结果显示，小胶质细胞缺失导致NAc兴奋性突触形成减弱，尤其发生在出生后第二至第三周。第三周的组织水平蛋白质组学分析显示，突触结构、跨突触信号传导和突触前功能相关蛋白发生变化。尽管电生理变化在成年后基本消失，但缺乏小胶质细胞的小鼠仍表现出持续的威胁回避行为改变，表明小胶质细胞参与调节NAc突触发育及威胁回避相关回路功能。","kp":["小胶质细胞缺失模型: Csf1rΔFIRE/ΔFIRE小鼠","小胶质细胞对突触发育的影响[伏隔核]: 缺失导致兴奋性突触形成减弱，主要发生在出生后第二至三周"]},{"t":"粒子反自旋冰中涌现的电荷结晶与阻挫","b":"Artificial spin ices have transcended their origins in frustrated rare-earth pyrochlores to become a versatile platform for engineering exotic states of matter. Across diverse implementations, from nanomagnets and superconducting vortices to colloids, quantum annealers, liquid crystals, and metamaterials, they are frequently described by the ice rule, often leading to degeneracy and constrained disorder by enforcing minimization of the local topological charge. Here, we report the realization of an “anti-spin ice” in which not only the ice rule does not hold, but its opposite is true as the system seeks to maximize, rather than minimize, spin ice charges. Using fast-rotating in-plane magnetic fields to generate isotropic attraction between colloidal particles, we invert the conventional paradigm of repulsive interactions in colloidal spin ices. Combining experiments and simulations across bipartite square and honeycomb lattices as well as non-bipartite pentaheptite geometries, we establish rules for order and disorder in the anti-spin ice. With the pentaheptite lattice, we demonstrate that the anti-spin ice system can also exhibit frustration, but of a different kind. This topological charge frustration arises from the lattice connectivity, where networks of unequal, odd-sided polygons suppress charge crystallization at high interaction strengths.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77905-2","c":"通用技术/材料工程/特种功能材料/磁性材料","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"粒子反自旋冰","sc":6.4,"scd":{"b":7.5,"i":3.0,"r":5.5,"d":6.5,"t":6.0},"as":"研究报道了一种反自旋冰的实现：与遵循冰规则、最小化局部拓扑电荷的传统人工自旋冰不同，该系统寻求最大化自旋冰电荷。研究者利用快速旋转的面内磁场在胶体粒子间产生各向同性吸引，构建了这一体系，实现常规模式的反转，产生了涌现的电荷结晶与阻挫现象。该反自旋冰平台超越了纳米磁体、超导涡旋、胶体、量子退火器、液晶和超材料等传统实现方式，为研究简并和受约束的无序态等奇异物质态提供了新途径。","kp":["人工自旋冰平台: 纳米磁体、超导涡旋、胶体、量子退火器、液晶、超材料等","实现结果[粒子反自旋冰]: 涌现的电荷结晶与阻挫"]},{"t":"用于户外个人热管理的多功能气凝胶纤维辐射冷却织物","b":"Aerogel fibers have many advantages for personal thermal management because of their three-dimensional porous structures, high porosity, thermal insulation, and effective passive daytime radiative cooling (PDRC) capabilities. However, the porous structure of aerogel fibers significantly weakens their mechanical strength, thereby reducing their cooling efficiency. Here, we develop a method for the continuous production of radially gradient porous bacterial cellulose (BC) aerogel fibers (GP-BCAFs) fabrics. The multilevel gradient micro- and nano-porous structures of the GP-BCAFs provide a high solar reflectivity, while the nano-entangled networks and distinctive wrinkled pores improve their mechanical properties by dissipating stress. The designed structure achieves a balance between strong mechanical properties and cooling performance. The GP-BCAF fabrics exhibit a high mechanical and PDRC performance, including a tensile strength of 50 MPa, a solar reflectivity of 94.7%, a mid-infrared (MIR) emissivity of 97.3%, and an outdoor cooling performance with 8.5 °C temperature lower than that of commercial cotton fabrics. Moreover, a self-powered sensor is built using the GP-BCAF fabric, and its electrical signals allow real-time monitoring of human physiological activities. This work provides a universal, sustainable, and scalable approach to producing PDRC aerogel fibers and multifunctional textiles for outdoor personal thermal management.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77997-w","c":"通用技术/材料工程/其它先进材料","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"气凝胶辐射冷却纤维","sc":6.4,"scd":{"b":7.0,"i":5.0,"r":5.0,"d":6.5,"t":6.0},"as":"研究开发了一种可连续制备径向梯度多孔细菌纤维素气凝胶纤维（GP-BCAFs）织物的方法，用于个人热管理。传统气凝胶纤维的多孔结构会削弱机械强度、降低冷却效率。GP-BCAFs具有多级梯度微纳孔结构，实现高太阳反射率；纳米缠结网络和特殊褶皱孔隙通过耗散应力改善机械性能，从而在强隔热、高效被动日间辐射冷却（PDRC）与机械强度之间取得平衡，为户外个人热管理提供了兼具冷却效率和耐用性的多功能气凝胶纤维织物。","kp":["材料: 径向梯度多孔细菌纤维素气凝胶纤维(GP-BCAFs)","特性[GP-BCAFs]: 兼具高孔隙率、隔热、日间被动辐射冷却与改善的机械强度","制备工艺: 连续化生产"]},{"t":"渐渗杂交驱动柞叶蝴蝶的局部适应","b":"Hybridization may have multiple impacts on speciation and adaptation. Yet the evidence of adaptive introgression events that have historically occurred between nonradiating or established species is still lacking. The oakleaf butterflies in the genus Kallima","d":"2026-09-26","u":"https://academic.oup.com/nsr/advance-article/doi/10.1093/nsr/nwag617/8836580?rss=1","c":"通用技术/基础学科/医学&生物学","a":"National Science Review Advance Access","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"柞叶蝴蝶渐渗杂交","sc":5.2,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":6.0},"as":"该摘要正文内容不完整，仅有引言部分，说明杂交对物种形成和适应具有多重影响，但历史上发生在非辐射或已确立物种之间的适应性渐渗事件证据仍然缺乏。研究对象为枯叶蝶属的柞叶蝴蝶。基于现有信息，研究围绕渐渗杂交驱动柞叶蝴蝶的局部适应展开，正文未提供具体的实验方法、参数和研究结论。","kp":["[柞叶蝴蝶Kallima]: 渐渗杂交驱动局部适应"]},{"t":"范德华异质结构中间接激子的高效输运动力学","b":"Exciton transport is fundamental for understanding transport phenomena in bosonic systems and for exploring excitation energy transfer in materials. Spatially indirect excitons (IXs) have long lifetimes allowing them to form quantum bosonic states and travel long distances. Van der Waals heterostructures form a new materials platform for exploring IX transport. Disordered in-plane potentials suppress IX transport due to IX localization and scattering. In this work, we found the efficient IX transport kinetics characterized by anomalously high IX mobility. The efficient IX transport kinetics is observed in the presence of substantial in-plane disorder. The anomalously high IX mobility, its disappearance with increasing temperature, and its non-monotonic dependence on density are qualitatively consistent with theoretical predictions of IX superfluidity.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77967-2","c":"通用技术/材料工程/特种功能材料/介电/导电材料","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"间接激子输运","sc":6.1,"scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.5,"t":6.0},"as":"研究在范德华异质结构中发现空间间接激子（IX）的高效输运动力学。尽管存在显著的面内无序电位（通常因IX局域化和散射而抑制输运），IX仍表现出异常高的迁移率。该异常高迁移率随温度升高而消失，且对激子密度呈非单调依赖关系，这些特征定性地有别于已知输运机制。该发现对理解玻色系统输运现象和材料中激发能量传递具有重要意义。","kp":["平台: 范德华异质结构","研究对象: 间接激子(IX)输运","IX优势特征: 长寿命，可形成量子玻色态并长距离传输","关键发现: 实现高效IX输运"]},{"t":"基于WRF-稳态RANS模拟时空降尺度耦合的复杂地形风资源评估","b":"The meso -micro coupled numerical simulation method has been gradually adopted for high-resolution wind resource assessment. However, the accuracy of downscaling from mesoscale to microscale in complex mountainous terrain remains a huge challenge. In this study, a numerical simulation method of wind field based on meso-micro coupling suitable for wind resource assessment in complex terrain was proposed to improve the accuracy of downscaling. For this method, the optimal Planetary Boundary Layer (PBL) scheme is determined based on Weather Research and Forecasting (WRF) simulations for complex mountainous wind fields. And the Inverse Distance Weighted Interpolation (IDW) and time-averaging strategy were used in the proposed method to drive the coupled unsteady WRF - steady Reynolds Averaged Navier Stokes (RANS) simulations. The results showed that the Mellor Yamada Nakanishi Niino (MYNN) scheme demonstrated better performance than other PBL schemes. Furthermore, Finer time segmentation could improve simulation results, especially for the case of fluctuating wind speed, and a 50% overlap time length gave the favorable agreement with the measured data. In summary, the framework of WRF-steady RANS had excellent applicability in complex mountainous regions. The proposed spatio-temporal downscaling method is helpful to improve the accuracy and efficiency of mountain wind field simulation, which is of great engineering significance for wind resource assessment.","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015187?dgcid=rss_sd_all","c":"零碳产业/能量转化/能源测/一次能源转化/风电","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"复杂地形风资源评估","sc":5.6,"scd":{"b":5.0,"i":6.0,"r":5.0,"d":7.0,"t":5.0},"as":"研究提出一种适用于复杂山地地形风资源评估的中尺度-微尺度耦合风场数值模拟方法。首先基于WRF模拟确定复杂山地风场的最优行星边界层（PBL）方案，然后采用反距离加权插值（IDW）和时间平均策略驱动耦合的非定常WRF-稳态RANS模拟，实现时空降尺度耦合。该方法旨在提高复杂山地地形下从中尺度到微尺度降尺度的精度，为高分辨率风资源评估提供数值模拟手段。","kp":["方法: WRF中尺度-稳态RANS微尺度耦合时空降尺度","适用场景: 复杂山地地形风资源评估"]},{"t":"Helio-TAF：一种用于短期光伏功率预测的多模态时间注意力融合网络","b":"","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015205?dgcid=rss_sd_all","c":"零碳产业/能量转化/能源测/一次能源转化/太阳能转化/光伏","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"光伏功率预测模型","sc":4.1,"scd":{"b":4.5,"i":4.0,"r":4.0,"d":3.0,"t":5.0},"as":"提出多模态时间注意力融合网络Helio-TAF，融合多源数据提升光伏短期功率预测精度。","kp":["模型: Helio-TAF多模态时间注意力融合网络","功能: 融合多源数据提升短期光伏功率预测精度"]},{"t":"高温低湿度动态载荷条件下质子交换膜燃料电池的非均匀退化机制","b":"","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926014698?dgcid=rss_sd_all","c":"零碳产业/能量转化/能源测/二次能源利用/燃料电池","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"燃料电池退化机制","sc":4.4,"scd":{"b":5.0,"i":5.0,"r":4.0,"d":3.0,"t":5.0},"as":"研究动态载荷及高温低湿环境下质子交换膜燃料电池的非均匀退化机理，为耐久性提升提供依据。","kp":["[质子交换膜燃料电池, 高温低湿+动态载荷]: 存在非均匀退化机制，为耐久性提升提供依据"]},{"t":"探索可再生能源社区在意大利灵活性市场中的作用","b":"The increasing penetration of distributed generation, mainly from variable and scarcely predictable renewable energy sources, requires new forms of system flexibility. Renewable Energy Communities (RECs) can contribute by aggregating demand-side flexibility and participating in ancillary service markets. This paper analyses the participation of an Italian REC in the Ancillary Services Market, focusing on load flexibility and its interaction with the shared energy incentive scheme. Using real consumption and generation data, multiple flexibility scenarios are simulated and evaluated in terms of balancing revenues, shared energy, and overall community cash flows. Results show that flexibility provision is economically attractive even at moderate levels, while the impact on shared energy remains limited and, in some cases, positive. The study confirms the potential of RECs as effective flexibility providers in decentralised electricity systems.","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015722?dgcid=rss_sd_all","c":"零碳产业/能量转化/能量分配与运输/虚拟电厂与电力交易","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"可再生能源社区灵活性","sc":5.4,"scd":{"b":5.0,"i":6.0,"r":4.0,"d":7.0,"t":5.0},"as":"研究基于意大利真实用电和发电数据，分析可再生能源社区（REC）参与辅助服务市场的情况，重点考察负荷灵活性及其与共享能源激励机制之间的相互作用。通过模拟多种灵活性方案，从平衡收益、共享能源和社区整体现金流等方面进行评估。结果表明，即使在中等灵活性水平下，提供灵活性服务在经济上仍具吸引力，而其对共享能源的影响则保持在一定范围内。研究显示REC可通过聚合需求侧灵活性参与辅助服务市场，为高比例分布式可再生能源并网提供系统灵活性。","kp":["可再生能源社区[意大利辅助服务市场]: 聚合需求侧灵活性参与辅助服务市场，与共享能源激励机制交互"]},{"t":"基于PSM-CNN-BiLSTM预测与PPO热启动MPC的混合动力飞机实时能量管理策略","b":"","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015497?dgcid=rss_sd_all","c":"通用技术/通信和运输/物质运输/航空","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"混合动力飞机能量管理","sc":4.4,"scd":{"b":5.0,"i":4.0,"r":4.0,"d":4.0,"t":5.0},"as":"结合PSM-CNN-BiLSTM功率预测与PPO热启动MPC优化，实现混合动力飞机实时能量管理。","kp":["能量管理策略[混合动力飞机]: PSM-CNN-BiLSTM功率预测结合PPO热启动MPC实时优化"]},{"t":"储能赋能电力受限建筑的多类型电动汽车充电基础设施：两阶段设计优化框架","b":"","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015734?dgcid=rss_sd_all","c":"零碳产业/能量转化/能量存储/其它储能技术","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"储能优化充电设施","sc":4.6,"scd":{"b":5.0,"i":4.0,"r":4.0,"d":3.5,"t":5.0},"as":"针对电力受限建筑，提出储能配合多类型电动汽车充电设施的两阶段设计优化框架。","kp":["设计框架[电力受限建筑+多类型EV充电]: 储能配合的两阶段设计优化"]},{"t":"光伏-相变材料系统：从热管理到系统优化的综述","b":"","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015801?dgcid=rss_sd_all","c":"零碳产业/能量转化/能源测/一次能源转化/太阳能转化/光伏","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"光伏相变材料热管理","sc":4.4,"scd":{"b":5.5,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"as":"综述光伏与相变材料结合系统在电池热管理及系统优化方面的研究进展。","kp":["光伏-相变材料系统: 用于电池热管理与系统优化"]},{"t":"面向高比例可再生能源消纳的抽水蓄能电站备用库容分层运行优化","b":"","d":"2026-09-26","u":"https://www.sciencedirect.com/science/article/pii/S0306261926015977?dgcid=rss_sd_all","c":"零碳产业/能量转化/能量存储/其它储能技术","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"抽水蓄能运行优化","sc":4.6,"scd":{"b":4.5,"i":5.0,"r":4.0,"d":3.5,"t":5.0},"as":"研究抽水蓄能电站备用库容的分层运行优化方法，促进高比例可再生能源消纳。","kp":["抽水蓄能电站: 备用库容分层运行优化，促进高比例可再生能源消纳"]},{"t":"描述符引导的有机太阳能电池非富勒烯受体母核计算筛选","b":"ABSTRACT Non‐fullerene acceptors (NFAs) have propelled organic photovoltaic efficiencies toward 21%, yet their modular acceptor–donor–acceptor chemistry creates a vast combinatorial design space that calls for efficient prescreening. Here we establish a computation‐driven screening workflow and apply it to over 4000 optimized A–B–(D–S)–B–A NFA molecules assembled from experimentally reported building blocks. Using a sequential set of device‐relevant criteria – suppressed dipole moment, a target quadrupole for efficient charge separation, trap‐free electron transport, sufficient interfacial energetic driving force, strong visible‐light absorption, and a sufficiently large photovoltaic gap – we downselect from over 4000 to the top 10 NFA candidates for common polymer donors (P3HT, PBDB‐T, PBDB‐T‐2F, and PBDB‐T‐SF). The top candidates recover established high‐performance motifs, including Y6‐type structures and an O‐IDTBR‐like candidate, supporting the validity of the descriptor set. Statistical analysis further reveals a clear division of control: donor building blocks primarily determine ionization energies, acceptor/end groups determine electron affinities, and the quadrupole moment provides a broadly tunable electrostatic handle that is only weakly correlated with frontier orbital energetics. Comparison to synthesized reference NFAs shows good agreement for thin‐film electronic and optical properties, while device performance highlights the importance of morphology beyond descriptor‐based prescreening.","d":"2026-09-26","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/aenm.71601","c":"零碳产业/能量转化/能源测/一次能源转化/太阳能转化/光伏","a":"Advanced Energy Materials","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"有机太阳能受体筛选","sc":6.4,"scd":{"b":7.0,"i":5.0,"r":5.0,"d":7.0,"t":5.0},"aip":1,"as":"研究建立了计算驱动的非富勒烯受体（NFA）筛选工作流，应用于由实验报道构建单元组装的4000多个A–B–(D–S)–B–A型NFA分子。筛选采用一系列器件相关判据：抑制偶极矩、面向高效电荷分离的目标四极矩、无陷阱电子传输、足够的界面能驱动力、强可见光吸收以及足够大的光伏间隙。通过顺序筛选，从4000多个候选分子中选出针对常见聚合物给体（P3HT、PBDB-T等）的前10个NFA候选物。该方法为模块化受体-给体-受体化学产生的庞大设计空间提供了高效预筛选途径。","kp":["光伏效率[非富勒烯受体]: 接近21%","筛选分子库[NFA分子 A–B–(D–S)–B–A]: 超过4000个","筛选准则: 抑制偶极矩等顺序器件相关判据"]},{"t":"靶向FAK-YAP信号轴抑制肿瘤干性并克服肿瘤对铜死亡的耐药性","b":"ABSTRACT Cuproptosis has recently been identified as a novel metabolic cell death pathway that holds great promise for cancer therapy. However, cuproptosis resistance developed by tumor cells severely impairs its anticancer efficacy. Here, our study uncovers that the FAK‐YAP signaling axis in tumor cells plays important roles in the development of cuproptosis resistance and the promotion of tumor stemness. To therapeutically target this signaling axis, a CRISPR‐cuproptosis synergistic nanoplatform (CPLNP@HA) is elaborately designed for targeted co‐delivery of a Ptk2 (encoding FAK) CRISPR‐Cas9 knockout plasmid to block FAK‐YAP signaling axis and Cu‐elesclomol (Cu‐ES, a cuproptosis inducer) into tumor cells. Mechanistically, CPLNP@HA efficiently silences FAK expression, which subsequently blocks the cuproptosis‐induced activation of the FAK‐YAP signaling cascade. This intervention not only sustains intracellular copper accumulation to reinforce cuproptosis but also reduces tumor stemness, thereby significantly potentiating the therapeutic outcomes of cuproptosis and activating tumoricidal immunity as evidenced by transcriptomic analysis. In combination with immune checkpoint blockade therapy, CPLNP@HA markedly inhibits tumor development upon rechallenge after surgical resection. Our work establishes FAK‐YAP signaling axis as a new therapeutic target to overcome cuproptosis resistance and inhibit tumor stemness, providing a promising combinatorial paradigm to sensitize tumor to cuproptosis and immunotherapy.","d":"2026-09-26","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/adma.75155","c":"通用技术/基础学科/医学&生物学","a":"Advanced Materials","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"铜死亡抗肿瘤机制","sc":6.4,"scd":{"b":8.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"as":"研究发现FAK-YAP信号轴在肿瘤细胞铜死亡耐药性发展和肿瘤干性促进中起关键作用。为靶向该通路，研究设计了CRISPR-铜死亡协同纳米平台CPLNP@HA，靶向共递送Ptk2（编码FAK）的CRISPR-Cas9敲除质粒和铜死亡诱导剂Cu-elesclomol（Cu-ES）。该平台可有效沉默FAK表达，阻断FAK-YAP信号轴，从而抑制肿瘤干性并克服肿瘤对铜死亡的耐药性，为癌症治疗提供了靶向FAK-YAP轴与铜死亡诱导相结合的协同纳米治疗策略。","kp":["铜死亡耐药机制: FAK-YAP信号轴促进耐药与肿瘤干性","干预手段: CRISPR-铜死亡协同纳米平台靶向该信号轴"]},{"t":"光子-声子-电子协同实现高效光热电转换用于智能火灾预警","b":"ABSTRACT Photothermoelectric (PTE) detectors offer broad‐spectrum response and high sensitivity, but their performance and applications are fundamentally limited by the difficulty of simultaneously controlling photon absorption, phonon propagation, and charge‐carrier dynamics. Here, we report silver selenide/silver secondary phases (Ag 2 Se/Ag‐SPs) nanocomposite films comprising vertically aligned Ag‐SPs within a (00 l )‐oriented Ag 2 Se matrix, fabricated via oriented growth and confined phase separation. This customized architecture suppresses lattice thermal transport through interfacial phonon scattering and regulates carrier transport via shallow‐barrier Ag/Ag 2 Se interfaces, collectively optimizing the thermo‐electric conversion process. Moreover, plasmonic waveguiding within Ag‐SPs domains improves broadband light absorption, thereby promoting photothermal heat generation, enabling a high PTE responsivity of 126 V W −1 at 1550 nm. When integrated with machine‐learning‐based transient signal classification, this detector achieves 100% sensitivity in flame recognition, allowing sub‐second differentiation of combustion events from innocuous thermal sources. This photon–phonon–electron synergistic enhancement mechanism establishes a scalable paradigm for efficient PTE conversion, offering transformative potential for intelligent fire‐warning systems.","d":"2026-09-26","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/adma.75105","c":"通用技术/检测和表征/传感器","a":"Advanced Materials","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"光热电火灾预警","sc":6.8,"scd":{"b":8.5,"i":4.0,"r":5.5,"d":7.0,"t":5.0},"aip":1,"as":"研究报道了Ag2Se/Ag次生相（Ag-SPs）纳米复合薄膜用于高效光热电（PTE）转换和智能火灾预警。该薄膜通过取向生长和受限相分离制备，在(00l)取向的Ag2Se基体中形成垂直排列的Ag-SPs。该结构通过界面声子散射抑制晶格热输运，并通过浅势垒Ag/Ag2Se界面调控载流子输运，协同优化热电转换过程；Ag-SPs内的等离激元波导效应进一步增强光吸收，从而实现光子-声子-电子协同调控，克服了同时控制光吸收、声子传播和载流子动力学的难题。","kp":["光热电材料[纳米复合薄膜]: (00l)取向Ag2Se基体中垂直排列Ag-SPs，光子-声子-电子协同调控，用于智能火灾预警"]},{"t":"血红素介导的电荷传输调控：将生物识别与固态蛋白电子学耦合","b":"Abstract Integrating the selectivity of biological recognition with the robustness of solid-state electronics remains a formidable challenge. Here, we demonstrate the functional integration of myoglobin (Mb) and its heme-depleted analogue, apomyoglobin (apoMb), within lithographically defined gold (Au) nanogap junctions bridged by Au nanowires (AuNWs). Electronic measurements reveal that the heme cofactor facilitates electron transport (ETp), with oxygen (O2) coordination at the Fe center modulating ETp by up to ∼ 10-fold. In contrast, apoMb junctions lacking the heme cofactor exhibit uniformly low conductance with negligible O2 sensitivity. QM/MM and EDA-NOCV analyses indicate that O2 coordination induces a charge-separated Fe3+–O2– configuration, characterized by combined Fe3+←O2̅ donor–acceptor π and Fe3+↔O2̅ σ-bonding interactions. This charge polarization toward O2 redistributes electron density away from the Fe center, resulting in strong π-back-donation, which destabilizes the Fe-centered antibonding orbitals, shifting the LUMO of MbO2 (Fe–O2 π*) to a higher energy consistent with the observed increase in tunneling barrier. Ultraviolet photoelectron spectroscopy (UPS) further reveals distinct HOMOonset values for Mb and apoMb monolayers, directly linking cofactor presence to electronic coupling. Collectively, our findings establish a clear mechanistic link between heme-mediated gas recognition coupled to ETp, providing a framework for integrating biological recognition with solid-state electronic devices within a single platform.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11008/5439332/Heme-Mediated-Charge-Transport-Modulation-Coupling","c":"通用技术/基础学科/医学&生物学","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"血红蛋白电荷传输","sc":6.3,"scd":{"b":7.5,"i":3.0,"r":5.5,"d":7.0,"t":5.0},"as":"研究将肌红蛋白及其脱血红素类似物（脱辅基肌红蛋白）功能集成于光刻定义的金纳米间隙结中，用金纳米线桥接。电子测量表明，血红素辅因子促进电子传输，且氧分子与Fe中心配位可将电子传输调节约10倍；缺乏血红素的脱辅基肌红蛋白结则表现出均匀低电导，对O2几乎不敏感。QM/MM和EDA-NOCV分析显示，O2配位诱导Fe3+–O2–电荷分离构型，具有Fe3+←O2供体相互作用特征。该工作实现了生物识别选择性与固态蛋白电子学的耦合。","kp":["电荷传输调控[肌红蛋白/脱血红素肌红蛋白@金纳米间隙]: 血红素辅因子促进电子传输，O2配位于Fe中心可调节传输"]},{"t":"基于联吡啶的共价三嗪框架中可控暗态释放的直接光储存","b":"Abstract Utilizing bifunctional materials capable of direct light-to-charge storage offers an attractive strategy to overcome solar intermittency and enable reliable power supply under dark conditions. Reported bifunctional materials are predominantly based on metal oxides and metal–organic compounds, whereas fully organic systems remain rare despite their rich structural diversity and tunability, which enable systematic structure–property–function investigations. Here, we reveal the light-induced, reversible electron storage properties of a two-dimensional (2D) 2,2′-bipyridine (bpy)-based crystalline covalent triazine framework (CTF), CTF-Bpy. Mechanistic studies suggest that the photoreduction of CTF-Bpy primarily proceeds through a proton-coupled, one-electron reduction of the bpy units, yielding bpyH• and bpyH2•+ as the identified reduction products. Photoanodes based on CTF-Bpy show a stable photoinduced open-circuit potential (photo-OCP) of −0.92 V vs Ag/AgCl, which is so far the most negative potential reported for an organic bifunctional material. Under oxygen-free conditions, photogenerated electrons remain stable and can be controllably released on-demand in the dark, either by electrical discharge (for aqueous solar battery applications) or by reducing O2 to H2O2. Moreover, this work establishes CTF-Bpy as the first photochargeable covalent organic framework (COF) with stored electrons sufficiently reducing to drive H2 evolution in the dark in the presence of a Pt cocatalyst, highlighting the promise of using COFs for \"dark photocatalysis\". The systematic investigation of the light-induced electron storage in CTF-Bpy with a set of spectroscopic and (spectro-)electrochemical techniques provides a framework for studying optoionic materials and guiding their rational design for tailored dark photocatalysis.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c09757/5439387/Direct-Light-Storage-with-Controlled-Dark-Release","c":"零碳产业/能量转化/能量存储/其它储能技术","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"有机框架直接光储","sc":6.6,"scd":{"b":7.5,"i":3.5,"r":5.5,"d":6.5,"t":5.0},"aip":1,"as":"研究揭示了一种二维2,2'-联吡啶基共价三嗪框架CTF-Bpy的光诱导可逆电子储存特性，实现直接光-电荷储存。机理研究表明，CTF-Bpy的光还原主要通过联吡啶单元的质子耦合单电子还原过程进行，并可控制地释放暗态储存的电荷。该工作提供了少数完全有机的双功能光储存体系之一，克服了以往此类材料以金属氧化物和金属有机化合物为主的局限，为应对太阳能间歇性、实现暗条件下的可靠供电提供了全有机材料平台。","kp":["光储存材料[联吡啶共价三嗪框架]: 可控暗态电荷释放，实现全有机直接光-电储存"]},{"t":"共价性驱动的框架收缩削弱隧道型TlCu5Se3中电荷与声子输运的耦合","b":"Abstract Framework thermoelectrics are promising for decoupling charge and phonon transport, yet a general structural strategy for simultaneously enhancing carrier mobility and suppressing lattice thermal conductivity (κL) remains unclear. Here, a comparative survey of representative layered, tunnel-type, and cage-like framework thermoelectrics reveals an empirical trend within an isomorphic family: reduced unit-cell volume is generally accompanied by enhanced apparent weighted mobility (μw) and power factor (PF), whereas κL shows no corresponding dependence on unit-cell volume. This weakened coupling suggests that framework contraction is a promising method for achieving excellent thermoelectric performance. Among tunnel-type thermoelectric materials MCu5Se3 (M = Tl, K, Cs), TlCu5Se3 with the smallest volume is selected to verify this strategy. Owing to the enhanced covalent character of Tl–Se interactions relative to nearly ionic K–Se and Cs–Se bonds, TlCu5Se3 exhibits an anomalously contracted Cu–Se framework despite the larger ionic radius of Tl+ than K+. This relative Tl–Se covalency contracts and moderately reinforces the Cu–Se framework, modifies Cu–Se orbital overlap and the valence-band-edge structure, and thereby provides a structural contribution favorable to carrier transport. Meanwhile, because the Tl–Se interaction remains weak and soft in absolute strength, heavy Tl+ cations with stereochemically active 6s2 lone pairs generate low-frequency localized vibrations and strong anharmonicity, efficiently scattering heat-carrying phonons. Consequently, TlCu5Se3 achieves an ultralow κL of 0.27 W m–1 K–1 and a PF of 9 μW cm–1 K–2 at 750 K, yielding ZT ≈ 1.9. These findings establish covalency-driven framework contraction combined with lone-pair-induced phonon scattering as an effective route for high-performance framework thermoelectrics.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11762/5439378/Covalency-Driven-Framework-Contraction-Weakens-the","c":"通用技术/材料工程/特种功能材料/导热/耐热材料","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"框架热电材料","sc":5.5,"scd":{"b":6.5,"i":2.5,"r":5.0,"d":7.0,"t":5.0},"as":"研究对层状、隧道型和笼状框架热电材料进行对比分析，发现在同构家族中存在经验趋势：晶胞体积减小通常伴随表观加权迁移率（μw）和功率因数（PF）提升，而晶格热导率（κL）与晶胞体积无相应依赖关系。这种电荷与声子输运的解耦表明框架收缩是获得优异热电性能的有效策略。在隧道型热电材料MCu5Se3（M=Tl、K、Cs）中，TlCu5Se3表现出共价性驱动的框架收缩，削弱了其中电荷与声子输运的耦合。","kp":["框架热电[同构族经验规律]: 单胞体积减小伴随表观加权迁移率(μw)提升","框架热电[结构策略]: 共价性驱动的框架收缩可同时增强载流子迁移率并抑制晶格热导率，实现电荷与声子输运解耦"]},{"t":"化学脱锂诱导层状氧化物正极表面重构用于高性能全固态电池","b":"Abstract Developing all-solid-state batteries (ASSBs) based on high-capacity cathodes (e.g., Ni-rich and Li-rich layered oxides) offers a promising route toward next-generation batteries with high energy density and safety. However, under high voltage, the cathode/solid electrolyte (SE) interface suffers from severe chemical degradation due to enhanced cathode–catholyte interactions. Here, we propose a chemical-delithiation-induced surface reconstruction strategy for Li-rich layered oxide cathodes, as a proof of concept, to effectively eliminate cathode-catholyte interfacial chemical degradation in ASSBs. We found that chemical-delithiation treatment by NO2BF4 induces a surface reconstruction of Li-rich layered oxide, forming a cation-disordered subsurface layer, which can then incorporate fluorine alike disordered rock-salt cathodes. Such surface reconstruction passivates the oxidative surface of Li-rich cathode in which oxygen redox is prevalent at high potential, thus eliminating the interfacial chemical degradation during cycling. As a result, the treated Li-rich layered cathode achieved a reversible capacity of ∼300.3 mA h g–1 that is comparable to liquid cells and a capacity retention of 82.3% over 1500 cycles at 1 C. By extending this strategy to Ni-rich layered oxides, we further demonstrate its universality in interfacial chemical design for high-energy-density ASSBs.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11457/5439250/Chemical-Delithiation-Induced-Surface","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"固态电池正极重构","sc":6.0,"scd":{"b":6.5,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"as":"研究提出化学脱锂诱导表面重构策略，用于富锂层状氧化物正极，消除全固态电池（ASSB）中正极/固态电解质界面在高压下的化学退化。NO2BF4化学脱锂处理使富锂层状氧化物表面重构，形成阳离子无序亚表面层，可有效抑制正极-电解质界面退化。该策略针对基于高容量正极（如富镍和富锂层状氧化物）的ASSB中高压下正极-电解液相互作用增强导致的界面化学降解问题，为开发高能量密度、高安全性的下一代全固态电池提供了概念验证方案。","kp":["表面重构策略[富锂层状氧化物正极]: 化学脱锂诱导重构，用于改善全固态电池高压下正极/固态电解质界面化学降解","正极类型[全固态电池]: 高容量镍富/锂富层状氧化物"]},{"t":"位阻与客体控制的应变重分布调控BODIPY功能化Hofmann型框架中的自旋交叉与光学读出","b":"Abstract Modulating spin crossover (SCO) in Fe(II) frameworks requires control over both the ligand field and the way spin-state strain is redistributed through the lattice. Herein, we report a BODIPY-functionalized Hofmann-type framework platform in which steric design and guest-imposed mechanical constraints tune SCO through lattice compliance. 1 and 2, constructed from methyl- and phenyl-substituted pyridyl-BODIPY ligands, retain closely related [Ag(CN)2]−-based connectivity. The moderate increase in ligand steric demand from 1 to 2 perturbs linker geometry, interlayer coupling, and packing environment, producing two-step SCO in 1 and a frustrated four-step transition in 2. In contrast, the anthracenyl-substituted ligand in 3 induces formation of a distinct framework containing [Ag2(CN)3]− linkers. Its higher-temperature one-step SCO therefore reflects the combined effects of ligand identity, altered cyanometallate connectivity, and framework packing rather than anthracenyl steric alone. Guest inclusion within porous 1 provides an alternative strategy: differences in guest rigidity, loading, and host–guest contact density reshape the host deformation pathway and tune the SCO profile without changing the Fe–Ag framework connectivity. The incorporation of the BODIPY chromophore induces diverse, nonmonotonic emission evolution across 1, 2, desolvated 3, and guest-loaded derivatives of 1, suggesting the unique ability of the BODIPY chromophore to probe both spin transitions and local microenvironments. These results identify steric bulk, framework connectivity, and guest-imposed constraints as coupled chemical variables for controlling strain accommodation and SCO in Hofmann-type frameworks featuring optical readouts.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11688/5439252/Steric-and-Guest-Controlled-Strain-Redistribution","c":"通用技术/基础学科/基础化学","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"自旋交叉框架调控","sc":5.1,"scd":{"b":6.0,"i":2.0,"r":4.5,"d":6.5,"t":5.0},"as":"研究报道了BODIPY功能化的Hofmann型框架平台，通过位阻设计和客体施加的机械约束调控Fe(II)框架中的自旋交叉（SCO）。由甲基和苯基取代的吡啶-BODIPY配体构建的化合物1和2保留相近的[Ag(CN)2]⁻连接方式：从1到2配体位阻的适度增加扰动连接子几何构型、层间耦合和堆积环境，使1产生两步SCO，2则呈现受挫的四步转变。而蒽基取代配体（3）则诱导形成含[Ag2(CN)…]单元的不同框架。研究表明晶格顺应性可用于调控自旋态应变重分布并实现光学读出。","kp":["自旋交叉调控[Fe(II) BODIPY功能化Hofmann框架]: 通过位阻设计与客体机械约束调控晶格柔顺性实现SCO调制与光学读出","框架连接性[1和2]: 基于相关联的[Ag(CN)2]−连接，分别采用甲基/苯基取代吡啶-BODIPY配体"]},{"t":"利用原位光电化学质谱将析氧选择性与赤铁矿光电极上水氧化反应级数相关联","b":"Abstract Water oxidation on metal-oxide (photo)anodes is often assumed to yield molecular oxygen. Here, we combine operando photoelectrochemical mass-spectrometry oxygen detection with spectroelectrochemical rate law analyses to link oxygen selectivity to surface-hole density on hematite photoanodes. At low current and hole densities, where first-order kinetics dominate, a near-zero Faradaic efficiency for oxygen evolution is observed, revealing that isolated single-hole water oxidation is poorly coupled to molecular oxygen formation. Increasing surface-hole density sharply increases O2 Faradaic efficiency, showing that the kinetic crossover to cooperative third-order water oxidation is also a selectivity switch toward O2 evolution. Equivalent behavior under dark electrochemical operation shows that multihole chemistry is intrinsic to hematite and governs selective oxygen evolution, likely representing a general feature of semiconducting metaloxides.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11949/5439333/Linking-Oxygen-Evolution-Selectivity-to-Water","c":"通用技术/材料工程/特种功能材料/催化材料","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"赤铁矿水氧化机理","sc":5.5,"scd":{"b":6.5,"i":2.0,"r":5.0,"d":7.5,"t":5.0},"as":"研究将操作条件下光电化学质谱氧检测与光谱电化学速率律分析相结合，建立赤铁矿光电极上析氧选择性与表面空穴密度的关联。在低电流和低空穴密度下（一级动力学主导），析氧的法拉第效率接近于零，表明单空穴水氧化与分子氧生成的耦合很差；随表面空穴密度增加，O2法拉第效率急剧上升，表明向协同三级水氧化动力学的转变同时也是向O2析出的选择性开关。暗态电化学操作下观察到等效行为。","kp":["析氧法拉第效率[赤铁矿光电极、低电流/低空穴密度]: 接近零","动力学[低空穴密度、单空穴水氧化]: 一级动力学主导，孤立单空穴水氧化选择性差"]},{"t":"两步法合成肽源大环共价基因编码文库，可使用具有多样反应活性的亲电试剂","b":"Abstract Genetically encoded libraries of peptide-derived macrocycles containing electrophile “warheads” (cGELs) can be used to identify potent and selective covalent ligands for protein targets. Such cGELs are synthesized either by incorporation of unnatural amino acids that display mild electrophiles on their side chains or by chemical post-translational modification (cPTM) of mRNA-displayed or phage-displayed peptide libraries. Here, we investigate fundamental barriers to the synthesis of cGELs and observe that a previously reported cPTM that proceeds in neutral-to-basic conditions creates mixtures of regioisomers. The complexity of the resulting mixture scales with the electrophilicity of the warhead used in the linker, with some electrophiles being not suitable for use under basic conditions. In contrast, use of a Knorr-pyrazole cPTM enables attachment of electrophiles in acidic pH, thus preventing unwanted reactions with nucleophilic side chains. The electrophile is activated only upon mixing with the desired protein target in neutral pH. We use this approach to generate a cGEL with alkyne-bearing macrocycles and use it to identify covalent macrocyclic ligands for pyruvate kinase 2 (PKM2). Our results suggest that construction of cGELs should be performed in conditions that silence the electrophiles (e.g., acidic environment) to prevent unwanted side reactions. In addition to the Knorr-pyrazole method, many other biocompatible bond-forming processes that proceed in mildly acidic pH are likely to be equally effective in constructing cGELs.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c12299/5439335/A-Two-Step-Synthesis-of-Covalent-Genetically","c":"通用技术/基础学科/医学&生物学","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"肽大环编码文库","sc":5.3,"scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.5,"t":5.0},"as":"研究考察了含亲电子弹头的肽源大环基因编码文库（cGELs）合成中的基本障碍。此类文库可通过整合展示温和亲电子侧链的非天然氨基酸，或对mRNA展示/噬菌体展示肽库进行化学翻译后修饰来合成。研究发现，已报道的中性至碱性条件下的化学修饰方法会产生区域异构体混合物，混合物复杂度随弹头亲电性增加而升高，某些亲电试剂不适用于碱性条件。为此，研究开发了适用具有多样反应活性亲电试剂的两步合成法。","kp":["肽源大环共价基因编码文库合成[方法]: 采用具有多样反应活性亲电试剂弹头的两步法合成","文库构建途径[cGEL]: 非天然氨基酸掺入或mRNA/噬菌体展示肽库的化学翻译后修饰(cPTM)"]},{"t":"通过促进高镍正极材料高压结构可逆性提升循环稳定性","b":"Cycling stability remains a critical challenge in the development of high-nickel positive electrode materials for lithium-ion batteries. Although existing strategies such as delaying the formation of the H3 phase or operating below a cut-off voltage have shown promise, they limit the exploitation of the full energy density. In this study, we introduce nanorod high-nickel materials, including LiNiO2, which demonstrate high-voltage cycling stability up to 4.95 V, more stable than traditional microcrystal counterparts. Our comparative analysis reveals that enhanced structural reversibility in the bulk structure is the key factor contributing to this improved cycling performance. The nanorod structure demonstrates an ability to endure the substantial lattice mismatch present in the Li layer at the H2-H3 interphase, thereby facilitating a comprehensive recovery from H3 to the H2 phase during discharge. This work offers insights into optimizing high-nickel positive electrode materials, improving cycling stability in high-energy battery applications.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78069-9","c":"零碳产业/能量转化/能量存储/电化学储能/二次电池/传统蓄电池/有机体系/锂电","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"高镍正极循环稳定","sc":5.9,"scd":{"b":5.5,"i":5.0,"r":5.0,"d":7.0,"t":5.0},"as":"研究引入纳米棒状高镍正极材料（包括LiNiO2），实现高达4.95V的高压循环稳定性，优于传统微晶材料。对比分析表明，体相结构可逆性的增强是循环性能改善的关键因素。纳米棒结构能够承受高电压下层状结构中Li层存在的大晶格失配。与延迟H3相形成或限制截止电压等以牺牲能量密度为代价的策略不同，该方法通过促进高镍正极高压下的结构可逆性，在不限制电压窗口的情况下提升了锂离子电池的循环稳定性。","kp":["高电压循环稳定性[纳米棒高镍正极(含LiNiO2)]: 可稳定循环至4.95 V，优于传统微米材料","循环稳定策略[高镍正极]: 通过促进高压结构可逆性，避免延迟H3相形成或降低截止电压对能量密度的限制"]},{"t":"利用光驱动非线性Edelstein-Zeeman场调控铁磁性","b":"Optical control of magnetization is often symmetry-forbidden because electric fields and magnetization transform differently under inversion and time-reversal. However, through even-order nonlinear response, optical excitation can generate a nonequilibrium magnetic density (the nonlinear Edelstein effect) that acts as an internal Edelstein-Zeeman field coupling to slower magnetic degrees of freedom. Here we demonstrate non-thermal, ultrafast optical control of ferromagnetism in the centrosymmetric van der Waals semiconductor Cr2Ge2Te6 via a resonant nonlinear Edelstein effect. Using time-domain THz emission spectroscopy under near-infrared excitation, we directly observe magnetic dipole radiation arising from optically driven magnetization dynamics. The polarization, fluence, and temperature dependences of the THz emission are quantitatively captured by a mean-field description of a weakly anisotropic Heisenberg ferromagnet subject to an Edelstein-Zeeman field. Our results establish a general nonequilibrium route to optical control of magnetism in centrosymmetric materials.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-77965-4","c":"通用技术/基础学科/基础物理","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"光控铁磁性","sc":6.1,"scd":{"b":7.5,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"as":"研究提出利用偶数阶非线性响应对铁磁性进行超快光学调控。由于电场与磁化在空间反演和时间反演变换性质不同，传统光控磁化常受对称性限制。通过共振非线性Edelstein效应可在中心对称范德华半导体Cr2Ge2Te6中产生非平衡磁密度，形成内部Edelstein-Zeeman场，与较慢的磁自由度耦合，实现对铁磁性的非热学、超快调控。实验采用近红外激发下的时域太赫兹发射光谱，直接观测到光驱动磁化动力学产生的磁偶极辐射，并研究了其偏振、注量及温度依赖特性。","kp":["铁磁性调控[中心对称体系]: 通过偶阶非线性响应产生非平衡磁密度(非线性Edelstein效应)，形成内Edelstein-Zeeman场","调控特性[光控磁化]: 非热、超快光学控制铁磁性"]},{"t":"单原子Ce调控碱性氧还原中Fe2原子对的界面路径","b":"Abstract Fe2 atomic pairs are among the most active motifs in Fe–N–C catalysts for the alkaline oxygen reduction reaction (ORR), but their performance is limited by an activity–stability trade-off. In alkaline media, slow interfacial water dissociation restricts proton-coupled electron transfer (PCET). Under these proton-deficient conditions, the more proton-demanding 4e– pathway is suppressed, whereas the competing 2e– route becomes more favorable, leading to peroxide/reactive oxygen species (ROS) accumulation and accelerated Fe demetalation. Here we show that atomically dispersed Ce can mitigate this limitation by regulating the interfacial reaction environment around Fe2 atomic pairs. In situ spectroscopy, kinetic isotope measurements, and theoretical calculations indicate that Ce promotes the main 4e– pathway by improving the interfacial water/proton environment, while also reducing peroxide-related species formed through the competing 2e– route near Fe2 sites. Accordingly, the resulting FeAPCeSA-NHCS catalyst, consisting of Fe2 atomic pairs and isolated Ce species on N-doped hollow carbon spheres, delivers a high half-wave potential of 0.92 V with a peroxide yield of only 1.6% in alkaline media. It also mitigates Fe demetalation, retains 96% of its current after 50,000 s of ORR operation, sustains Zn–air battery cycling for over 1100 h, and achieves peak power densities of 1.0 W cm–2 in anion-exchange membrane fuel cells. This work establishes an interfacial pathway-regulation strategy for decoupling activity and stability in alkaline ORR catalysis.","d":"2026-09-26","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c07837/5439437/Single-Atom-Ce-Enables-Interfacial-Pathway","c":"通用技术/材料工程/特种功能材料/催化材料","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"Fe-N-C氧还原催化","sc":5.7,"scd":{"b":6.5,"i":3.0,"r":5.0,"d":7.5,"t":5.0},"as":"Fe2原子对是Fe-N-C催化剂在碱性氧还原反应（ORR）中最活跃的位点之一，但受活性-稳定性权衡限制。碱性介质中界面水解离缓慢制约质子耦合电子转移（PCET），质子缺乏条件下对质子需求更高的4e⁻路径被抑制，竞争性2e⁻路径占优，导致过氧化物和活性氧物种（ROS）积累，加速铁脱金属。研究采用原子级分散的Ce调控Fe2原子对周围的界面反应环境，结合原位光谱、动力学同位素测量和理论计算，证实Ce促进界面水解离，缓解上述活性-稳定性限制。","kp":["ORR催化瓶颈[碱性介质Fe2原子对Fe–N–C]: 界面水解离缓慢限制质子耦合电子转移(PCET)，存在活性-稳定性权衡","反应路径[碱性、质子匮乏条件]: 4e–路径受抑制，2e–竞争路径占优，导致过氧化物/活性氧生成","调控策略[Fe2原子对]: 单原子Ce调控界面反应路径"]},{"t":"支化型纳米簇-结氟流体凝胶用于界面自适应导热与机械韧性","b":"With the miniaturization and high integration of microelectronic devices, efficient thermal management is increasingly critical. Conventional thermal interface materials often suffer from a certain degree of mismatch between their thermal conductivity and contact thermal resistance. Herein, we develop a thermal interface fluorofluidic-gel with a branched-type nanocluster-junction network. Benefiting from the interfacial infiltration enabled by the branched-junction fluoronetwork and the efficient thermal pathways constructed by thermal conductive nanocomposites, the fluorofluidic-gel exhibits a high thermal conductivity of 5.89 W·m⁻¹·K⁻¹ and a low contact thermal resistance of 0.15 cm²·K·W⁻¹. It also achieves reversible adhesion and mechanical resistance, with an adhesive strength of 189.3 kPa, adhesion energy of 220.3 J·m⁻² and impact resistance of 3.91 J·cm⁻¹. In addition, this gel maintains thermal stability from −80 °C to 300 °C and exhibits an electrical breakdown strength exceeding 24 kV/mm. We ‌anticipate‌ that adaptive thermal interface fluorofluidic-gel presents a promising solution for high-heat-flux electronic thermal management.","d":"2026-09-26","u":"https://www.nature.com/articles/s41467-026-78046-2","c":"通用技术/材料工程/特种功能材料/导热/耐热材料","a":"Physical sciences : Nature Communications subject feeds","i":"l","source":"news_with_abstract_2026-09-27.csv","sr":"literature/news_with_abstract_2026-09-27.csv","tg":"研究论文","tp":"导热氟凝胶","sc":5.6,"scd":{"b":6.0,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"as":"针对微电子器件小型化高集成带来的热管理需求，研究开发了一种具有支化型纳米簇-结网络的导热界面氟流体凝胶。传统导热界面材料常存在导热率与接触热阻的失配问题。得益于支化结氟网络的界面浸润能力和导热纳米复合材料构建的高效热通路，该材料导热率达5.89 W·m⁻¹·K⁻¹，接触热阻低至0.15 cm²·K·W⁻¹，并具备可逆粘附性能与机械强度，粘附强度达189.3，实现了界面自适应导热与机械韧性的结合。","kp":["热界面材料[支化型纳米簇-结氟流体凝胶]: 通过支化结氟网络实现界面渗透，兼具界面自适应导热与机械韧性","现有热界面材料缺陷[常规]: 热导率与接触热阻之间存在失配"]}]);